namespace {
// The hub (bot.php) defines NIKTO_CONFIG from the main config.php before loading this module.
// Opened directly from the web it does nothing: all updates go through the hub's bot.php.
if (!defined('NIKTO_CONFIG') && PHP_SAPI !== 'cli') {
    http_response_code(403);
    exit('forbidden');
}
if (!defined('NIKTO_CONFIG')) {
    define('NIKTO_CONFIG', [
        'bot_token'      => '',
        'owner_id'       => 0,
        'admins'         => [],
        'webhook_url'    => '',
        'webhook_secret' => '',
        'timezone'       => 'Asia/Tehran',
        'brand'          => 'NIKTO CRYPTO',
        'http_proxy'     => '',
        'data_proxy'     => '',
        'coinglass_key'  => '',
        'coingecko_key'  => '',
    ]);
}
}
namespace Nikto\Bundle {
    final class Assets
    {
        public const VERSION = '481104b4b02a';

        public static function files(): array
        {
            $packed = self::PACKED;
            $out = [];
            foreach ($packed as $path => $blob) {
                $raw = @gzinflate((string) base64_decode($blob, true));
                if ($raw !== false) {
                    $out[$path] = base64_encode($raw);
                }
            }

            return $out;
        }

