namespace Nikto\Bundle {
use Nikto\Core\Config;
use Nikto\Core\Db;
use Nikto\Core\Diagnostics;
use Nikto\Core\Log;
use Nikto\Core\PublicUrl;
use Nikto\Core\Settings;
use Nikto\Jobs\Dispatcher;
use Nikto\Jobs\Registry;
use Nikto\Jobs\Scheduler;
use Nikto\Telegram\Api;
use Nikto\Telegram\Panel;

final class Runtime
{
    public const VERSION = '2.0';

    public static function boot(array $config): void
    {
        $token = trim((string) ($config['bot_token'] ?? ''));
        $botId = (int) (strtok($token, ':') ?: 0);
        $root  = (string) ($config['root'] ?? __DIR__);

        $data = rtrim($root, '/') . '/nikto-' . ($botId ?: 'bot') . '-data';

        if (!defined('APP_ROOT')) {
            define('APP_ROOT', $root);
            define('APP_SRC', $data);
            define('APP_DATA', $data);
            define('APP_STORAGE', $data . '/storage');
            define('APP_ASSETS', $data . '/assets');
            define('APP_FIXTURES', $data . '/fixtures');
        }

        foreach ([APP_DATA, APP_STORAGE, APP_STORAGE . '/cards', APP_STORAGE . '/logs', APP_ASSETS, APP_FIXTURES] as $dir) {
            if (!is_dir($dir)) {
                @mkdir($dir, 0775, true);
            }
        }
        self::protect($data);
        self::extractAssets();

        mb_internal_encoding('UTF-8');
        date_default_timezone_set('UTC');
        Log::guardFatals();

        Config::boot();
        foreach ([
            'bot_token'      => $token,
            'bot_id'         => $botId,
            'owner_id'       => (int) ($config['owner_id'] ?? 0),
            'admins'         => (array) ($config['admins'] ?? []),
            'webhook_url'    => (string) ($config['webhook_url'] ?? ''),
            'webhook_secret' => (string) ($config['webhook_secret'] ?? ''),
            'http_proxy'     => (string) ($config['http_proxy'] ?? ''),
            'data_proxy'     => (string) ($config['data_proxy'] ?? ''),
            'coinglass_key'  => (string) ($config['coinglass_key'] ?? ''),
            'coingecko_key'  => (string) ($config['coingecko_key'] ?? ''),
            'db_path'        => $data . '/bot.sqlite',
            'timezone'       => (string) ($config['timezone'] ?? 'Asia/Tehran'),
            'brand'          => (string) ($config['brand'] ?? 'NIKTO CRYPTO'),
        ] as $key => $value) {
            Config::set($key, $value);
        }

        $admins = Config::get('admins');
        $admins = is_array($admins) ? $admins : [];
        $owner = (int) Config::get('owner_id', 0);
        if ($owner > 0) {
            $admins[] = $owner;
        }
        Config::set('admins', array_values(array_unique(array_filter(array_map('intval', $admins)))));
    }

    private static function protect(string $dir): void
    {
        $htaccess = $dir . '/.htaccess';
        if (!is_file($htaccess)) {
            @file_put_contents($htaccess, "Require all denied\nDeny from all\n");
        }
        $index = $dir . '/index.html';
        if (!is_file($index)) {
            @file_put_contents($index, '');
        }
    }

    private static function extractAssets(): void
    {
        if (!class_exists(Assets::class)) {
            return;
        }
        $marker = APP_ASSETS . '/.version';
        if (is_file($marker) && trim((string) file_get_contents($marker)) === Assets::VERSION) {
            return;
        }

        foreach (Assets::files() as $relative => $base64) {
            $path = APP_DATA . '/' . $relative;
            $dir = dirname($path);
            if (!is_dir($dir)) {
                @mkdir($dir, 0775, true);
            }
            $bytes = base64_decode($base64, true);
            if ($bytes !== false) {
                @file_put_contents($path, $bytes);
            }
        }
        @file_put_contents($marker, Assets::VERSION);
    }

    public static function handleWeb(): void
    {
        $method = $_SERVER['REQUEST_METHOD'] ?? 'GET';

        if ($method !== 'POST') {
            header('Content-Type: text/plain; charset=utf-8');
            http_response_code(200);

            $secret = (string) Config::get('webhook_secret', '');
            $given = (string) ($_GET['check'] ?? '');
            if ($given !== '' && $secret !== '' && hash_equals($secret, $given)) {
                echo Diagnostics::renderText();
                return;
            }

            $setup = (string) ($_GET['setup'] ?? '');
            if ($setup !== '') {
                if ($secret === '' || !hash_equals($secret, $setup)) {
                    http_response_code(403);
                    echo "کلید نادرست است. مقدار webhook_secret بالای فایل ربات را بگذارید:\n";
                    echo '  ' . (PublicUrl::current() ?: 'nikto-bot.php') . "?setup=<webhook_secret>\n";
                    return;
                }
                echo self::webSetup();
                return;
            }

            echo PublicUrl::statusPage(
                self::VERSION,
                'php ' . basename((string) ($_SERVER['SCRIPT_NAME'] ?? 'nikto-bot.php')) . ' webhook'
            );
            return;
        }

        $secret = (string) Config::get('webhook_secret', '');
        $header = (string) ($_SERVER['HTTP_X_TELEGRAM_BOT_API_SECRET_TOKEN'] ?? '');
        if ($secret !== '' && !hash_equals($secret, $header)) {
            http_response_code(403);
            echo 'forbidden';
            return;
        }

        $update = json_decode((string) file_get_contents('php://input'), true);
        if (!is_array($update)) {
            http_response_code(400);
            echo 'bad request';
            return;
        }

        http_response_code(200);
        echo 'ok';
        if (function_exists('fastcgi_finish_request')) {
            fastcgi_finish_request();
        }

        try {
            Db::migrate();
            Registry::all();
            (new Panel(new Api()))->handleUpdate($update);
        } catch (\Throwable $e) {
            Log::error('Webhook handling failed', ['error' => $e->getMessage()]);
        }
    }

    private static function webSetup(): string
    {
        if (!Config::isConfigured()) {
            return "توکن ربات بالای فایل تنظیم نشده است (bot_token).\n";
        }

        $current = PublicUrl::current();
        $configured = trim((string) Config::get('webhook_url', ''));
        $strip = static fn (string $u): string => rtrim((string) preg_replace('#^https?://#i', '', $u), '/');

        if ($configured !== '' && $strip($configured) === $strip($current)) {
            $url = $configured;
        } elseif (str_starts_with(strtolower($current), 'https://')) {
            $url = $current;
        } else {
            $url = $configured;
        }
        if (!str_starts_with(strtolower($url), 'https://')) {
            return "تلگرام فقط آدرس https قبول می‌کند.\n"
                . "آدرس فعلی: " . ($current ?: '(نامشخص)') . "\n"
                . "این صفحه را با https باز کنید یا webhook_url را بالای فایل درست بنویسید.\n";
        }

        $api = new Api();
        $me = $api->getMe();
        if (!($me['ok'] ?? false)) {
            $why = (string) ($me['description'] ?? 'نامشخص');
            $badToken = isset($me['error_code']) || stripos($why, 'Unauthorized') !== false || stripos($why, 'Not Found') !== false;

            return "اتصال به تلگرام ناموفق بود: {$why}\n"
                . ($badToken
                    ? "توکن ربات (bot_token بالای فایل) نادرست است.\n"
                    : "هاست به api.telegram.org دسترسی ندارد؛ اگر لازم است http_proxy را بالای فایل تنظیم کنید.\n");
        }

        $res = $api->setWebhook($url, (string) Config::get('webhook_secret', ''));
        $lines = ['NIKTO CRYPTO BOT — ثبت وب‌هوک', ''];
        $lines[] = 'ربات:   @' . ($me['result']['username'] ?? '?');
        $lines[] = 'آدرس:   ' . $url;
        $lines[] = '';
        if (!($res['ok'] ?? false)) {
            $lines[] = 'ناموفق: ' . ($res['description'] ?? 'نامشخص');
            return implode("\n", $lines) . "\n";
        }
        $lines[] = 'وب‌هوک با موفقیت ثبت شد.';
        if ($configured !== '' && $url !== $configured) {
            $lines[] = '';
            $lines[] = 'توجه: webhook_url بالای فایل با این آدرس فرق دارد؛ بهتر است آن را هم به همین آدرس تغییر دهید.';
        }
        $lines[] = '';
        $lines[] = 'حالا در تلگرام به ربات /start بفرستید.';

        return implode("\n", $lines) . "\n";
    }

    public static function handleCli(array $argv): int
    {
        $command = $argv[1] ?? 'poll';
        $arg = $argv[2] ?? '';

        if (!Config::isConfigured()) {
            fwrite(STDERR, "❌ توکن ربات تنظیم نشده است (بالای همین فایل، مقدار bot_token).\n");
            return 1;
        }

        Db::migrate();
        Registry::all();

        return match ($command) {
            'poll', 'start' => self::poll(),
            'webhook'       => self::webhook(true),
            'webhook:off'   => self::webhook(false),
            'webhook:info'  => self::webhookInfo(),
            'send'          => self::send($arg),
            'preview'       => self::preview($arg),
            'doctor', 'check' => self::doctor(),
            'cron', 'tick'  => self::tick(),
            'cron:loop'     => self::cronLoop(),
            default         => self::usage($command),
        };
    }

    private static function usage(string $command): int
    {
        $file = basename($_SERVER['SCRIPT_NAME'] ?? 'nikto-bot.php');
        echo "دستور ناشناخته: {$command}\n\n";
        echo "روش استفاده:\n";
        echo "  php {$file}                  روشن‌کردن ربات (long polling)\n";
        echo "  php {$file} webhook          ثبت وب‌هوک روی تلگرام\n";
        echo "  php {$file} webhook:info     وضعیت وب‌هوک\n";
        echo "  php {$file} webhook:off      حذف وب‌هوک\n";
        echo "  php {$file} send prices      ارسال فوری یک کارت\n";
        echo "  php {$file} preview          ساخت پیش‌نمایش کارت‌ها روی دیسک\n";
        echo "  php {$file} doctor           بررسی سلامت\n";
        echo "  php {$file} cron             یک بار بررسی زمان‌بندی\n";

        return 1;
    }

    private static function poll(): int
    {
        $api = new Api();
        $me = $api->getMe();
        if (!($me['ok'] ?? false)) {
            fwrite(STDERR, '❌ اتصال به تلگرام ناموفق بود: ' . ($me['description'] ?? '') . "\n");
            return 1;
        }
        $api->deleteWebhook();

        echo '✅ ربات @' . ($me['result']['username'] ?? '?') . " روشن شد. (Ctrl+C برای توقف)\n";
        $panel = new Panel($api);
        $offset = 0;
        $running = true;

        if (function_exists('pcntl_signal')) {
            pcntl_async_signals(true);
            $stop = static function () use (&$running): void { $running = false; };
            pcntl_signal(SIGTERM, $stop);
            pcntl_signal(SIGINT, $stop);
        }

        while ($running) {
            try {
                foreach ($api->getUpdates($offset, 30) as $update) {
                    $offset = max($offset, (int) ($update['update_id'] ?? 0) + 1);
                    try {
                        $panel->handleUpdate($update);
                    } catch (\Throwable $e) {
                        Log::error('Update handling failed', ['error' => $e->getMessage()]);
                    }
                }
            } catch (\Throwable $e) {
                Log::error('Polling loop error', ['error' => $e->getMessage()]);
                sleep(3);
            }
        }

        return 0;
    }

    private static function webhook(bool $enable): int
    {
        $api = new Api();
        if (!$enable) {
            $res = $api->deleteWebhook();
            echo ($res['ok'] ?? false) ? "✅ وب‌هوک حذف شد.\n" : '❌ ' . ($res['description'] ?? '') . "\n";
            return ($res['ok'] ?? false) ? 0 : 1;
        }

        $url = (string) Config::get('webhook_url', '');
        if ($url === '') {
            fwrite(STDERR, "❌ مقدار webhook_url بالای فایل تنظیم نشده است.\n");
            return 1;
        }
        $res = $api->setWebhook($url, (string) Config::get('webhook_secret', ''));
        if ($res['ok'] ?? false) {
            echo "✅ وب‌هوک ثبت شد:\n   {$url}\n";
            return 0;
        }
        echo '❌ ' . ($res['description'] ?? 'خطا') . "\n";

        return 1;
    }

    private static function webhookInfo(): int
    {
        $res = (new Api())->getWebhookInfo();
        echo json_encode($res['result'] ?? $res, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . "\n";

        return 0;
    }

    private static function send(string $jobKey): int
    {
        if (!in_array($jobKey, Registry::keys(), true)) {
            echo 'کارهای موجود: ' . implode(', ', Registry::keys()) . "\n";
            return 1;
        }
        $result = Dispatcher::run($jobKey);
        echo ($result['ok'] ? '✅ ' : '❌ ') . $result['message'] . "\n";

        return $result['ok'] ? 0 : 1;
    }

    private static function preview(string $jobKey): int
    {
        $keys = $jobKey !== '' ? [$jobKey] : Registry::keys();
        foreach ($keys as $key) {
            $result = Dispatcher::build($key);
            echo ($result['ok'] ?? false)
                ? sprintf("✅ %-10s → %s\n", $key, $result['path'])
                : sprintf("❌ %-10s → %s\n", $key, $result['message'] ?? '');
        }

        return 0;
    }

    private static function tick(): int
    {
        Settings::set('scheduler_heartbeat', (string) time());
        foreach (Scheduler::tick() as $item) {
            printf("[%s] %s → %s\n", date('H:i:s'), $item['job'], $item['result']['message'] ?? '');
        }

        return 0;
    }

    private static function cronLoop(): int
    {
        $running = true;
        if (function_exists('pcntl_signal')) {
            pcntl_async_signals(true);
            $stop = static function () use (&$running): void { $running = false; };
            pcntl_signal(SIGTERM, $stop);
            pcntl_signal(SIGINT, $stop);
        }

        echo '⏰ زمان‌بند روشن شد — منطقه‌ی زمانی: ' . Settings::get('timezone') . "\n";
        while ($running) {
            self::tick();
            $sleep = 60 - (int) date('s');
            for ($i = 0; $i < $sleep && $running; $i++) {
                sleep(1);
            }
        }

        return 0;
    }

    private static function doctor(): int
    {
        echo "\n" . Diagnostics::renderText() . "\n";

        return 0;
    }

    private static function doctorLegacy(): int
    {
        $problems = 0;
        echo "\n🔎 بررسی سلامت — NIKTO CRYPTO BOT v" . self::VERSION . "\n" . str_repeat('─', 46) . "\n";

        printf("  PHP %s%s\n", PHP_VERSION, version_compare(PHP_VERSION, '8.1.0', '>=') ? ' ✅' : ' ❌');
        $problems += version_compare(PHP_VERSION, '8.1.0', '>=') ? 0 : 1;

        foreach (['curl', 'gd', 'mbstring', 'pdo_sqlite'] as $ext) {
            $has = extension_loaded($ext);
            printf("  افزونه %-12s %s\n", $ext, $has ? '✅' : '❌');
            $problems += $has ? 0 : 1;
        }
        printf("  FreeType %s\n", function_exists('imagettftext') ? '✅' : '❌');

        printf("  پوشه‌ی داده: %s %s\n", APP_DATA, is_writable(APP_DATA) ? '✅' : '❌');
        $problems += is_writable(APP_DATA) ? 0 : 1;

        $fonts = glob(APP_ASSETS . '/fonts/*.ttf') ?: [];
        $logos = glob(APP_ASSETS . '/coins/color/*.png') ?: [];
        printf("  فونت‌ها: %d  |  لوگوها: %d\n", count($fonts), count($logos));
        $problems += count($fonts) > 0 ? 0 : 1;

        $me = (new Api())->getMe();
        if ($me['ok'] ?? false) {
            printf("  تلگرام: @%s ✅\n", $me['result']['username'] ?? '?');
        } else {
            printf("  تلگرام: ❌ %s\n", $me['description'] ?? '');
            $problems++;
        }

        $url = (string) Config::get('webhook_url', '');
        if ($url !== '') {
            $info = (new Api())->getWebhookInfo();
            $current = (string) ($info['result']['url'] ?? '');
            printf("  وب‌هوک: %s\n", $current === $url ? 'ثبت شده ✅' : ($current === '' ? 'ثبت نشده ⚠️' : 'آدرس متفاوت: ' . $current));
        }

        foreach (Registry::all() as $key => $job) {
            printf(
                "  %s %-22s %s | کانال: %d | بعدی: %s\n",
                $job->icon(),
                $job->title(),
                $job->enabled() ? 'فعال ' : 'خاموش',
                count($job->channels()),
                Scheduler::nextRun($key)?->format('Y-m-d H:i') ?? '—'
            );
        }

        echo str_repeat('─', 46) . "\n";
        echo $problems === 0 ? "✅ همه‌چیز آماده است.\n\n" : "❌ {$problems} مورد نیاز به رسیدگی دارد.\n\n";

        return $problems === 0 ? 0 : 1;
    }

    public static function handleWebCron(): void
    {
        header('Content-Type: text/plain; charset=utf-8');
        $secret = (string) Config::get('webhook_secret', '');
        $given = (string) ($_GET['key'] ?? $_GET['secret'] ?? '');

        if ($secret === '' || !hash_equals($secret, $given)) {
            http_response_code(403);
            $url = PublicUrl::current();
            echo "NIKTO CRYPTO BOT — scheduler\n\n";
            echo "این آدرس باید هر دقیقه صدا زده شود:\n";
            echo '  ' . ($url !== '' ? $url : 'https://your-domain/nikto-cron.php') . "?key=<webhook_secret>\n\n";
            echo "یا از کرون خط فرمان استفاده کنید:\n";
            $script = (string) ($_SERVER['SCRIPT_FILENAME'] ?? '') ?: __FILE__;
            echo '  * * * * * /usr/local/bin/php ' . $script . " >/dev/null 2>&1\n\n";
            echo "مقدار webhook_secret بالای فایل ربات نوشته شده است.\n";
            return;
        }

        try {
            Db::migrate();
            Registry::all();
            Settings::set('scheduler_heartbeat', (string) time());
            $results = Scheduler::tick();
            echo 'ok ' . count($results) . " job(s)\n";
            foreach ($results as $item) {
                echo $item['job'] . ': ' . ($item['result']['message'] ?? '') . "\n";
            }
        } catch (\Throwable $e) {
            http_response_code(500);
            Log::error('Web cron failed', ['error' => $e->getMessage()]);
            echo "error\n";
        }
    }
}
}

namespace Nikto\Core {
final class Config
{
    private static array $data = [];
    private static bool $booted = false;

    public static function boot(): void
    {
        if (self::$booted) {
            return;
        }
        self::$booted = true;

        $defaults = [
            'bot_token'      => '',
            'bot_id'         => 0,
            'owner_id'       => 0,
            'admins'         => [],
            'db_path'        => APP_DATA . '/bot.sqlite',
            'timezone'       => 'Asia/Tehran',
            'brand'          => 'NIKTO CRYPTO',
            'http_timeout'   => 25,
            'http_proxy'     => '',
            'data_proxy'     => '',
            'coinglass_key'  => '',
            'coingecko_key'  => '',
            'api_keys'       => [],
            'log_level'      => 'info',
            'webhook_secret' => '',
        ];

        $fromFile = self::readFile(APP_ROOT . '/config.php');
        $fromLocal = self::readFile(APP_ROOT . '/config.local.php');

        $fromEnv = array_filter([
            'bot_token' => getenv('BOT_TOKEN') ?: null,
            'bot_id'    => getenv('BOT_ID') ? (int) getenv('BOT_ID') : null,
            'owner_id'  => getenv('OWNER_ID') ? (int) getenv('OWNER_ID') : null,
            'timezone'  => getenv('BOT_TIMEZONE') ?: null,
            'brand'     => getenv('BOT_BRAND') ?: null,
        ], static fn ($v) => $v !== null);

        self::$data = array_replace($defaults, $fromFile, $fromLocal, $fromEnv);

        $admins = self::$data['admins'];
        if (!is_array($admins)) {
            $admins = array_filter(array_map('intval', preg_split('/[,\s]+/', (string) $admins)));
        }
        if (!empty(self::$data['owner_id'])) {
            $admins[] = (int) self::$data['owner_id'];
        }
        self::$data['admins'] = array_values(array_unique(array_filter(array_map('intval', $admins))));
    }

    private static function readFile(string $path): array
    {
        if (!is_file($path)) {
            return [];
        }
        $data = require $path;

        return is_array($data) ? array_filter($data, static fn ($v) => $v !== '' && $v !== null) : [];
    }

    public static function get(string $key, mixed $default = null): mixed
    {
        self::boot();
        return self::$data[$key] ?? $default;
    }

    public static function set(string $key, mixed $value): void
    {
        self::boot();
        self::$data[$key] = $value;
    }

    public static function token(): string
    {
        return (string) self::get('bot_token', '');
    }

    public static function admins(): array
    {
        return (array) self::get('admins', []);
    }

    public static function isConfigured(): bool
    {
        return preg_match('/^\d{5,}:[A-Za-z0-9_-]{30,}$/', self::token()) === 1;
    }
}
}

namespace Nikto\Core {
use PDO;

final class Db
{
    private static ?PDO $pdo = null;

    public static function pdo(): PDO
    {
        if (self::$pdo instanceof PDO) {
            return self::$pdo;
        }
        $path = (string) Config::get('db_path');
        $dir = dirname($path);
        if (!is_dir($dir)) {
            @mkdir($dir, 0775, true);
        }
        $pdo = new PDO('sqlite:' . $path, null, null, [
            PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_EMULATE_PREPARES   => false,
        ]);
        $pdo->exec('PRAGMA journal_mode = WAL');
        $pdo->exec('PRAGMA busy_timeout = 8000');
        $pdo->exec('PRAGMA foreign_keys = ON');
        self::$pdo = $pdo;
        self::migrate();

        return self::$pdo;
    }

    public static function migrate(): void
    {
        $pdo = self::$pdo ?? self::pdo();
        $pdo->exec(<<<'SQL'
        CREATE TABLE IF NOT EXISTS settings (
            key   TEXT PRIMARY KEY,
            value TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS channels (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_id    TEXT NOT NULL UNIQUE,
            title      TEXT NOT NULL DEFAULT '',
            username   TEXT NOT NULL DEFAULT '',
            type       TEXT NOT NULL DEFAULT 'channel',
            active     INTEGER NOT NULL DEFAULT 1,
            created_at INTEGER NOT NULL
        );

        CREATE TABLE IF NOT EXISTS jobs (
            key        TEXT PRIMARY KEY,
            title      TEXT NOT NULL,
            enabled    INTEGER NOT NULL DEFAULT 0,
            theme      TEXT NOT NULL DEFAULT 'glass',
            caption    TEXT NOT NULL DEFAULT '',
            options    TEXT NOT NULL DEFAULT '{}',
            updated_at INTEGER NOT NULL DEFAULT 0
        );

        CREATE TABLE IF NOT EXISTS job_channels (
            job_key    TEXT NOT NULL,
            channel_id INTEGER NOT NULL,
            PRIMARY KEY (job_key, channel_id),
            FOREIGN KEY (channel_id) REFERENCES channels(id) ON DELETE CASCADE
        );

        CREATE TABLE IF NOT EXISTS schedules (
            id       INTEGER PRIMARY KEY AUTOINCREMENT,
            job_key  TEXT NOT NULL,
            at_time  TEXT NOT NULL,
            days     TEXT NOT NULL DEFAULT '*',
            enabled  INTEGER NOT NULL DEFAULT 1,
            created_at INTEGER NOT NULL
        );
        CREATE UNIQUE INDEX IF NOT EXISTS idx_schedule_unique ON schedules(job_key, at_time, days);

        CREATE TABLE IF NOT EXISTS runs (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            job_key    TEXT NOT NULL,
            slot       TEXT NOT NULL,
            status     TEXT NOT NULL,
            detail     TEXT NOT NULL DEFAULT '',
            created_at INTEGER NOT NULL
        );
        CREATE UNIQUE INDEX IF NOT EXISTS idx_runs_slot ON runs(job_key, slot);

        CREATE TABLE IF NOT EXISTS user_state (
            user_id    INTEGER PRIMARY KEY,
            action     TEXT NOT NULL DEFAULT '',
            payload    TEXT NOT NULL DEFAULT '',
            updated_at INTEGER NOT NULL
        );

        CREATE TABLE IF NOT EXISTS panel_anchor (
            user_id            INTEGER PRIMARY KEY,
            chat_id            TEXT NOT NULL,
            message_id         INTEGER NOT NULL,
            preview_message_id INTEGER NOT NULL DEFAULT 0,
            updated_at         INTEGER NOT NULL
        );

        CREATE TABLE IF NOT EXISTS admins (
            user_id    INTEGER PRIMARY KEY,
            name       TEXT NOT NULL DEFAULT '',
            created_at INTEGER NOT NULL
        );

        CREATE TABLE IF NOT EXISTS logs (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            level      TEXT NOT NULL,
            message    TEXT NOT NULL,
            context    TEXT NOT NULL DEFAULT '',
            created_at INTEGER NOT NULL
        );

        CREATE TABLE IF NOT EXISTS cache (
            key        TEXT PRIMARY KEY,
            value      TEXT NOT NULL,
            expires_at INTEGER NOT NULL
        );
        SQL);
    }

    public static function all(string $sql, array $params = []): array
    {
        $st = self::pdo()->prepare($sql);
        $st->execute($params);
        return $st->fetchAll();
    }

    public static function one(string $sql, array $params = []): ?array
    {
        $st = self::pdo()->prepare($sql);
        $st->execute($params);
        $row = $st->fetch();
        return $row === false ? null : $row;
    }

    public static function exec(string $sql, array $params = []): int
    {
        $st = self::pdo()->prepare($sql);
        $st->execute($params);
        return $st->rowCount();
    }

    public static function lastId(): int
    {
        return (int) self::pdo()->lastInsertId();
    }

    public static function scalar(string $sql, array $params = []): mixed
    {
        $st = self::pdo()->prepare($sql);
        $st->execute($params);
        $row = $st->fetch(PDO::FETCH_NUM);
        return $row === false ? null : $row[0];
    }
}
}

namespace Nikto\Core {
use Nikto\Jobs\Registry;
use Nikto\Jobs\Scheduler;
use Nikto\Telegram\Api;
use Nikto\Telegram\Channels;

final class Diagnostics
{
    private const DATA_SOURCES = [
        'منبع: Binance Futures'   => 'https://fapi.binance.com/fapi/v1/ping',
        'منبع: Binance Spot'      => 'https://api.binance.com/api/v3/ping',
        'منبع: Binance (mirror)'  => 'https://data-api.binance.vision/api/v3/ping',
        'منبع: Bybit'             => 'https://api.bybit.com/v5/market/time',
        'منبع: OKX'               => 'https://www.okx.com/api/v5/public/time',
        'منبع: Gate.io'           => 'https://api.gateio.ws/api/v4/spot/time',
        'منبع: MEXC'              => 'https://api.mexc.com/api/v3/ping',
        'منبع: MEXC Futures'      => 'https://contract.mexc.com/api/v1/contract/ping',
        'منبع: KuCoin'            => 'https://api.kucoin.com/api/v1/timestamp',
        'منبع: KuCoin Futures'    => 'https://api-futures.kucoin.com/api/v1/timestamp',
        'منبع: Nobitex'           => 'https://api.nobitex.ir/market/stats?srcCurrency=btc&dstCurrency=usdt',
        'منبع: Bitget'            => 'https://api.bitget.com/api/v2/public/time',
        'منبع: BingX'             => 'https://open-api.bingx.com/openApi/swap/v2/server/time',
        'منبع: CoinEx'            => 'https://api.coinex.com/v2/time',
        'منبع: HTX'               => 'https://api.hbdm.com/api/v1/timestamp',
        'منبع: Ourbit'            => 'https://futures.ourbit.com/api/v1/contract/ticker',
        'منبع: Hyperliquid'       => ['https://api.hyperliquid.xyz/info', '{"type":"l2Book","coin":"BTC"}'],
        'منبع: CoinGecko'         => 'https://api.coingecko.com/api/v3/ping',
        'منبع: ترس و طمع'          => 'https://api.alternative.me/fng/?limit=1&format=json',
        'منبع: ForexFactory'      => 'https://nfs.faireconomy.media/ff_calendar_thisweek.json',
    ];

    public static function run(): array
    {
        $out = [];
        $add = static function (?bool $ok, string $label, string $detail = '') use (&$out): void {
            $out[] = ['ok' => $ok, 'label' => $label, 'detail' => $detail];
        };

        $phpOk = version_compare(PHP_VERSION, '8.0.0', '>=');
        $add($phpOk, 'نسخه PHP', PHP_VERSION . ($phpOk ? '' : ' — حداقل ۸.۰ لازم است'));

        foreach (['curl', 'gd', 'mbstring', 'pdo_sqlite', 'json', 'zlib'] as $ext) {
            $has = extension_loaded($ext);
            $add($has, 'افزونه ' . $ext, $has ? 'نصب است' : 'نصب نیست');
        }
        $add(function_exists('imagettftext'), 'پشتیبانی FreeType در GD', function_exists('imagettftext') ? 'دارد' : 'ندارد — متن روی تصویر رسم نمی‌شود');

        $limit = (string) ini_get('memory_limit');
        $add(null, 'حافظه PHP', $limit);

        foreach ([APP_DATA => 'پوشه data', APP_STORAGE . '/cards' => 'پوشه storage/cards'] as $dir => $label) {
            if (!is_dir($dir)) {
                @mkdir($dir, 0775, true);
            }
            $writable = is_dir($dir) && is_writable($dir);
            $add($writable, $label, $writable ? 'قابل نوشتن' : 'قابل نوشتن نیست — دسترسی 755 یا 775 بدهید');
        }

        $token = Config::token();
        $validToken = Config::isConfigured();
        $add($validToken, 'توکن ربات', $validToken ? self::mask($token) : ($token === '' ? 'تنظیم نشده' : 'نامعتبر — توکن را از BotFather کپی کنید'));
        $owner = (int) Config::get('owner_id', 0);
        $add($owner > 0, 'شناسه مدیر', $owner > 0 ? (string) $owner : 'تنظیم نشده');
        $add(null, 'آدرس وب‌هوک در تنظیمات', (string) Config::get('webhook_url', '—'));
        $current = PublicUrl::current();
        if ($current !== '') {
            $add(null, 'آدرس واقعی این فایل', $current);
        }

        try {
            Db::migrate();
            Registry::all();
            $channels = count(Channels::all());
            $add(true, 'دیتابیس', 'سالم — ' . $channels . ' کانال ثبت‌شده');
        } catch (\Throwable $e) {
            $add(false, 'دیتابیس', 'خطا: ' . $e->getMessage());
        }

        $fonts = count(glob(APP_ASSETS . '/fonts/*.ttf') ?: []);
        $logos = count(glob(APP_ASSETS . '/coins/color/*.png') ?: []);
        $add($fonts > 0, 'فونت‌ها', $fonts . ' فایل');
        $add($logos > 0, 'لوگوی ارزها', $logos . ' فایل');

        if (!$validToken) {
            return $out;
        }
        $api = new Api();
        $me = $api->getMe();
        if ($me['ok'] ?? false) {
            $add(true, 'اتصال به تلگرام', '@' . ($me['result']['username'] ?? '?') . ' (id: ' . ($me['result']['id'] ?? '?') . ')');
        } else {
            $add(false, 'اتصال به تلگرام', (string) ($me['description'] ?? 'ناموفق — احتمالاً سرور به api.telegram.org دسترسی ندارد'));
            return $out;
        }

        $info = $api->getWebhookInfo();
        if ($info['ok'] ?? false) {
            $result = $info['result'] ?? [];
            $url = (string) ($result['url'] ?? '');
            $add($url !== '', 'وب‌هوک ثبت‌شده', $url !== '' ? $url : 'ثبت نشده — ربات در حالت پولینگ است');

            if ($url !== '' && $current !== '' && rtrim($url, '/') !== rtrim($current, '/')) {
                $add(false, 'تطابق آدرس', 'آدرس ثبت‌شده با این فایل یکی نیست');
            }

            $pending = (int) ($result['pending_update_count'] ?? 0);
            $add($pending === 0, 'پیام‌های در صف', (string) $pending);

            $lastError = (string) ($result['last_error_message'] ?? '');
            if ($lastError !== '') {
                $when = isset($result['last_error_date']) ? date('Y-m-d H:i', (int) $result['last_error_date']) : '';
                $add(false, 'آخرین خطای تلگرام', $lastError . ($when !== '' ? ' (' . $when . ')' : ''));
            } else {
                $add(true, 'آخرین خطای تلگرام', 'خطایی ثبت نشده');
            }

            $add(null, 'کلید امنیتی وب‌هوک', ($result['has_custom_certificate'] ?? false) ? 'گواهی سفارشی' : 'استاندارد');
        }

        $proxy = Http::proxy();
        $add(null, 'پراکسی داده', $proxy === '' ? 'ندارد (اتصال مستقیم)' : (string) preg_replace('#//[^@/]*@#', '//***@', $proxy));

        if (\Nikto\Data\CoinGeckoApi::enabled()) {
            Http::resetFailures();
            $ping = \Nikto\Data\CoinGeckoApi::get('/ping', [], 10);
            $add(
                is_array($ping),
                'کلید CoinGecko',
                is_array($ping) ? 'کلید معتبر است' : (Http::explainFailures(1) !== '' ? ltrim(Http::explainFailures(1), '• ') : 'پاسخی نیامد')
            );
        } else {
            $add(null, 'کلید CoinGecko', 'تنظیم نشده (رایگان؛ coingecko_key بالای فایل)');
        }

        if (\Nikto\Data\CoinGlass::enabled()) {
            Http::resetFailures();
            $coins = \Nikto\Data\CoinGlass::get('/futures/supported-coins');
            $add(
                is_array($coins),
                'منبع: CoinGlass',
                is_array($coins) ? 'کلید معتبر است' : (Http::explainFailures(1) !== '' ? ltrim(Http::explainFailures(1), '• ') : 'پاسخی نیامد')
            );
        } else {
            $add(null, 'منبع: CoinGlass', 'کلید تنظیم نشده (اختیاری؛ coinglass_key بالای فایل)');
        }

        foreach (Http::probe(self::DATA_SOURCES) as $label => $r) {
            $add(
                $r['ok'],
                $label,
                $r['ok'] ? 'در دسترس (' . $r['ms'] . ' ms)' : Http::explain($r['code'], $r['error'], $r['body'])
            );
        }

        foreach (Registry::all() as $key => $job) {
            $add(null, $job->title(), ($job->enabled() ? 'فعال' : 'خاموش')
                . ' | کانال: ' . count($job->channels())
                . ' | ارسال بعدی: ' . (Scheduler::nextRun($key)?->format('Y-m-d H:i') ?? '—'));
        }

        $heartbeat = Settings::get('scheduler_heartbeat', '');
        $add(
            $heartbeat !== '' && (time() - (int) $heartbeat) < 300,
            'زمان‌بند',
            $heartbeat !== '' ? 'آخرین بررسی ' . date('Y-m-d H:i:s', (int) $heartbeat) : 'هنوز اجرا نشده'
        );

        return $out;
    }

    public static function renderText(): string
    {
        $lines = ['NIKTO CRYPTO BOT — عیب‌یابی', str_repeat('=', 46), ''];
        $problems = 0;

        foreach (self::run() as $row) {
            $mark = match ($row['ok']) {
                true  => '[ OK ]',
                false => '[ !! ]',
                null  => '[ -- ]',
            };
            if ($row['ok'] === false) {
                $problems++;
            }
            $lines[] = sprintf('%s %-28s %s', $mark, $row['label'], $row['detail']);
        }

        $recent = Log::recent(8);
        if ($recent !== []) {
            $lines[] = '';
            $lines[] = str_repeat('-', 46);
            $lines[] = 'آخرین خطاهای ثبت‌شده:';
            foreach ($recent as $row) {
                $lines[] = sprintf(
                    '  %s  %s  %s %s',
                    date('m-d H:i:s', $row['created_at']),
                    strtoupper($row['level']),
                    $row['message'],
                    mb_substr($row['context'], 0, 160)
                );
            }
        }

        $lines[] = '';
        $lines[] = str_repeat('=', 46);
        $lines[] = $problems === 0
            ? 'همه‌چیز سالم است.'
            : $problems . ' مورد نیاز به رسیدگی دارد (خط‌های [ !! ]).';

        return implode("\n", $lines) . "\n";
    }

    private static function mask(string $token): string
    {
        $parts = explode(':', $token, 2);

        return ($parts[0] ?? '') . ':' . substr($parts[1] ?? '', 0, 3) . str_repeat('*', 8);
    }
}
}

namespace Nikto\Core {
final class Http
{
    private static array $failures = [];

    public static function resetFailures(): void
    {
        self::$failures = [];
    }

    public static function failures(): array
    {
        return self::$failures;
    }

    public static function lastCode(string $url): int
    {
        return (int) (self::$failures[self::host($url)]['code'] ?? 0);
    }

    public static function explainFailures(int $max = 8): string
    {
        $lines = [];
        foreach (array_slice(self::$failures, 0, $max, true) as $host => $f) {
            $lines[] = '• ' . $host . ': ' . self::explain((int) $f['code'], (string) $f['error'], (string) ($f['body'] ?? ''));
        }
        if (count(self::$failures) > $max) {
            $lines[] = '• و ' . (count(self::$failures) - $max) . ' سرویس دیگر';
        }

        return implode("\n", $lines);
    }

    public static function allRegionBlocked(): bool
    {
        if (self::$failures === []) {
            return false;
        }
        foreach (self::$failures as $f) {
            if (!self::isRegionBlock((int) $f['code'], (string) ($f['body'] ?? ''))) {
                return false;
            }
        }

        return true;
    }

    public static function isRegionBlock(int $code, string $body): bool
    {
        return $code === 451
            || ($code === 403 && preg_match('/country|countries|region|restricted location|eligibility|jurisdiction|1009/i', $body) === 1);
    }

    public static function explain(int $code, string $error, string $body = ''): string
    {
        $error = str_replace(['<', '>', '&'], '', $error);

        return match (true) {
            self::isRegionBlock($code, $body) => 'HTTP ' . $code . ' — این سرویس کشورِ سرورِ شما را مسدود کرده است',
            $code === 403 => 'HTTP 403 — دسترسی رد شد (فایروالِ هاست یا محدودیتِ سرویس)',
            $code === 401 => 'HTTP 401 — کلیدِ API نامعتبر است',
            $code === 429, $code === 418 => 'HTTP ' . $code . ' — محدودیت تعداد درخواست؛ چند دقیقه بعد دوباره امتحان کنید',
            $code >= 500 => 'HTTP ' . $code . ' — خطای موقت سمت سرویس',
            $code > 0 => 'HTTP ' . $code,
            stripos($error, 'SSL') !== false || stripos($error, 'certificate') !== false
                => 'خطای SSL/گواهی روی سرور: ' . mb_substr($error, 0, 80),
            stripos($error, 'timed out') !== false || stripos($error, 'timeout') !== false
                => 'مهلت اتصال تمام شد (سرور به این آدرس دسترسی ندارد)',
            stripos($error, 'resolve') !== false => 'نام دامنه پیدا نشد (DNS سرور)',
            stripos($error, 'JSON') !== false => 'پاسخ نامعتبر (JSON نبود)',
            $error !== '' => mb_substr($error, 0, 80),
            default => 'خطای نامشخص شبکه',
        };
    }

    public static function probe(array $urls, int $timeout = 8): array
    {
        $mh = curl_multi_init();
        $handles = [];
        foreach ($urls as $label => $target) {
            [$url, $post] = is_array($target) ? $target : [$target, null];
            $ch = curl_init($url);
            curl_setopt_array($ch, self::options($timeout, $post !== null ? ['Content-Type: application/json'] : []));
            if ($post !== null) {
                curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_POSTFIELDS => $post]);
            }
            $proxy = self::proxy();
            if ($proxy !== '') {
                curl_setopt($ch, CURLOPT_PROXY, $proxy);
            }
            curl_multi_add_handle($mh, $ch);
            $handles[$label] = $ch;
        }

        do {
            $status = curl_multi_exec($mh, $running);
            if ($running) {
                curl_multi_select($mh, 1.0);
            }
        } while ($running && $status === CURLM_OK);

        $results = [];
        while (($info = curl_multi_info_read($mh)) !== false) {
            $results[spl_object_id($info['handle'])] = (int) $info['result'];
        }

        $out = [];
        foreach ($handles as $label => $ch) {
            $code = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
            $result = $results[spl_object_id($ch)] ?? CURLE_OK;
            $out[$label] = [
                'ok'    => $code >= 200 && $code < 300,
                'code'  => $code,
                'error' => $result !== CURLE_OK ? (string) curl_strerror($result) : '',
                'body'  => self::snippet(curl_multi_getcontent($ch)),
                'ms'    => (int) round((float) curl_getinfo($ch, CURLINFO_TOTAL_TIME) * 1000),
            ];
            curl_multi_remove_handle($mh, $ch);
            curl_close($ch);
        }
        curl_multi_close($mh);

        return $out;
    }

    private static function options(int $timeout, array $headers): array
    {
        return [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_MAXREDIRS      => 4,
            CURLOPT_TIMEOUT        => $timeout,
            CURLOPT_CONNECTTIMEOUT => min(12, $timeout),
            CURLOPT_ENCODING       => '',
            CURLOPT_USERAGENT      => 'NiktoCryptoBot/1.0 (+php)',
            CURLOPT_HTTPHEADER     => array_merge(['Accept: application/json'], $headers),
        ];
    }

    public static function proxy(): string
    {
        return (string) (Config::get('data_proxy', '') ?: Config::get('http_proxy', ''));
    }

    private static function snippet(mixed $body): string
    {
        return is_string($body) ? mb_substr(trim((string) preg_replace('/\s+/', ' ', strip_tags($body))), 0, 300) : '';
    }

    private static function host(string $url): string
    {
        return strtolower((string) (parse_url($url, PHP_URL_HOST) ?: $url));
    }

    public static function note(string $url, int $code, string $error): void
    {
        self::fail($url, $code, $error);
    }

    private static function fail(string $url, int $code, string $error, string $body = ''): void
    {
        $host = self::host($url);
        unset(self::$failures[$host]);
        self::$failures[$host] = ['code' => $code, 'error' => $error, 'body' => $body];
    }

    public static function get(string $url, array $headers = [], int $timeout = 0, int $retries = 2, ?string $post = null): ?string
    {
        $timeout = $timeout ?: (int) Config::get('http_timeout', 25);
        $lastErr = '';
        $lastCode = 0;
        $lastBody = '';
        $err = '';

        for ($attempt = 0; $attempt <= $retries; $attempt++) {
            if ($attempt > 0) {
                usleep((int) (500000 * (2 ** ($attempt - 1))));
            }
            $ch = curl_init($url);
            curl_setopt_array($ch, self::options($timeout, $post !== null ? array_merge($headers, ['Content-Type: application/json']) : $headers));
            if ($post !== null) {
                curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_POSTFIELDS => $post]);
            }
            $proxy = self::proxy();
            if ($proxy !== '') {
                curl_setopt($ch, CURLOPT_PROXY, $proxy);
            }
            $body = curl_exec($ch);
            $code = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
            $err  = curl_error($ch);
            curl_close($ch);

            if ($body !== false && $code >= 200 && $code < 300) {
                unset(self::$failures[self::host($url)]);
                return (string) $body;
            }
            $lastErr = $err !== '' ? $err : ('HTTP ' . $code);
            $lastCode = $code;
            $lastBody = self::snippet($body);
            if ($code >= 400 && $code < 500 && $code !== 429) {
                break;
            }
        }

        self::fail($url, $lastCode, $err, $lastBody);
        Log::warn('HTTP request failed', ['url' => self::maskUrl($url), 'error' => $lastErr]);
        return null;
    }

    public static function postJson(string $url, array $body, int $timeout = 0, int $retries = 1): ?array
    {
        return self::getJson($url, [], $timeout, $retries, (string) json_encode($body));
    }

    public static function getJson(string $url, array $headers = [], int $timeout = 0, int $retries = 2, ?string $post = null): ?array
    {
        $raw = self::get($url, $headers, $timeout, $retries, $post);
        if ($raw === null) {
            return null;
        }
        $data = json_decode($raw, true);
        if (!is_array($data)) {
            self::fail($url, 0, 'Invalid JSON');
            Log::warn('Invalid JSON response', ['url' => self::maskUrl($url)]);
            return null;
        }
        return $data;
    }

    public static function remember(string $key, int $ttl, callable $produce): ?array
    {
        $row = Db::one('SELECT value, expires_at FROM cache WHERE key = :k', [':k' => $key]);
        if ($row && (int) $row['expires_at'] > time()) {
            $data = json_decode((string) $row['value'], true);
            if (is_array($data)) {
                return $data;
            }
        }

        $data = $produce();
        if (is_array($data) && $data !== []) {
            Db::exec(
                'INSERT INTO cache(key, value, expires_at) VALUES(:k, :v, :e)
                 ON CONFLICT(key) DO UPDATE SET value = excluded.value, expires_at = excluded.expires_at',
                [':k' => $key, ':v' => json_encode($data, JSON_UNESCAPED_UNICODE), ':e' => time() + $ttl]
            );
            return $data;
        }
        if ($row) {
            $stale = json_decode((string) $row['value'], true);
            if (is_array($stale)) {
                Log::warn('Using stale cache', ['key' => $key]);
                return $stale;
            }
        }

        return null;
    }

    public static function cachedJson(string $key, string $url, int $ttl, array $headers = []): ?array
    {
        $row = Db::one('SELECT value, expires_at FROM cache WHERE key = :k', [':k' => $key]);
        if ($row && (int) $row['expires_at'] > time()) {
            $data = json_decode((string) $row['value'], true);
            if (is_array($data)) {
                return $data;
            }
        }
        $data = self::getJson($url, $headers);
        if ($data !== null) {
            Db::exec(
                'INSERT INTO cache(key, value, expires_at) VALUES(:k, :v, :e)
                 ON CONFLICT(key) DO UPDATE SET value = excluded.value, expires_at = excluded.expires_at',
                [':k' => $key, ':v' => json_encode($data, JSON_UNESCAPED_UNICODE), ':e' => time() + $ttl]
            );
            return $data;
        }
        if ($row) {
            $stale = json_decode((string) $row['value'], true);
            if (is_array($stale)) {
                Log::warn('Using stale cache', ['key' => $key]);
                return $stale;
            }
        }
        return null;
    }

    private static function maskUrl(string $url): string
    {
        return preg_replace('/(token|apikey|api_key|key)=[^&]+/i', '$1=***', $url) ?? $url;
    }
}
}

namespace Nikto\Core {
final class Jalali
{
    public const MONTHS = [
        1 => 'فروردین', 2 => 'اردیبهشت', 3 => 'خرداد', 4 => 'تیر', 5 => 'مرداد', 6 => 'شهریور',
        7 => 'مهر', 8 => 'آبان', 9 => 'آذر', 10 => 'دی', 11 => 'بهمن', 12 => 'اسفند',
    ];

    public const WEEKDAYS = [
        0 => 'یکشنبه', 1 => 'دوشنبه', 2 => 'سه‌شنبه', 3 => 'چهارشنبه',
        4 => 'پنجشنبه', 5 => 'جمعه', 6 => 'شنبه',
    ];

    public static function fromGregorian(int $gy, int $gm, int $gd): array
    {
        $jdn = self::gregorianToJdn($gy, $gm, $gd);
        return self::jdnToJalali($jdn);
    }

    public static function format(\DateTimeInterface $date, string $pattern = 'l j F Y'): string
    {
        [$jy, $jm, $jd] = self::fromGregorian(
            (int) $date->format('Y'),
            (int) $date->format('n'),
            (int) $date->format('j')
        );
        $weekday = self::WEEKDAYS[(int) $date->format('w')] ?? '';

        $map = [
            'Y' => (string) $jy,
            'y' => substr((string) $jy, -2),
            'm' => str_pad((string) $jm, 2, '0', STR_PAD_LEFT),
            'n' => (string) $jm,
            'd' => str_pad((string) $jd, 2, '0', STR_PAD_LEFT),
            'j' => (string) $jd,
            'F' => self::MONTHS[$jm] ?? '',
            'l' => $weekday,
            'H' => $date->format('H'),
            'i' => $date->format('i'),
        ];

        $out = '';
        $len = strlen($pattern);
        for ($i = 0; $i < $len; $i++) {
            $ch = $pattern[$i];
            if ($ch === '\\' && $i + 1 < $len) {
                $out .= $pattern[++$i];
                continue;
            }
            $out .= $map[$ch] ?? $ch;
        }
        return $out;
    }

    private static function gregorianToJdn(int $gy, int $gm, int $gd): int
    {
        $d = (int) ((($gy + (int) (($gm - 8) / 6) + 100100) * 1461) / 4)
            + (int) ((153 * (($gm + 9) % 12) + 2) / 5)
            + $gd - 34840408;
        $d = $d - (int) (((int) (($gy + 100100 + (int) (($gm - 8) / 6)) / 100) * 3) / 4) + 752;
        return $d;
    }

    private static function jdnToJalali(int $jdn): array
    {
        $gy = self::jdnToGregorianYear($jdn);
        $jy = $gy - 621;
        $march = self::firstMarchJdn($jy);
        $k = $jdn - $march;

        if ($k >= 0) {
            if ($k <= 185) {
                $jm = 1 + (int) ($k / 31);
                $jd = ($k % 31) + 1;
                return [$jy, $jm, $jd];
            }
            $k -= 186;
        } else {
            $jy--;
            $k += 179;
            if (self::isLeap($jy)) {
                $k++;
            }
        }
        $jm = 7 + (int) ($k / 30);
        $jd = ($k % 30) + 1;

        return [$jy, $jm, $jd];
    }

    private static function jdnToGregorianYear(int $jdn): int
    {
        $j = 4 * $jdn + 139361631 + (int) (((int) ((4 * $jdn + 183187720) / 146097) * 3) / 4) * 4 - 3908;
        $i = (int) ((($j % 1461) / 4) * 5) + 308;
        return (int) ($j / 1461) - 100100 + (int) ((8 - $i / 25) / 100);
    }

    private static function firstMarchJdn(int $jy): int
    {
        $breaks = [-61, 9, 38, 199, 426, 686, 756, 818, 1111, 1181, 1210,
            1635, 1701, 1866, 2020, 2369, 2394, 2456, 3178];
        $gy = $jy + 621;
        $leapJ = -14;
        $jp = $breaks[0];
        $jump = 0;
        for ($i = 1; $i < count($breaks); $i++) {
            $jm = $breaks[$i];
            $jump = $jm - $jp;
            if ($jy < $jm) {
                break;
            }
            $leapJ += (int) ($jump / 33) * 8 + (int) ((($jump % 33)) / 4);
            $jp = $jm;
        }
        $n = $jy - $jp;
        $leapJ += (int) ($n / 33) * 8 + (int) ((($n % 33) + 3) / 4);
        if (($jump % 33) === 4 && $jump - $n === 4) {
            $leapJ++;
        }
        $leapG = (int) ($gy / 4) - (int) (((int) ($gy / 100) + 1) * 3 / 4) - 150;
        $march = 20 + $leapJ - $leapG;

        return self::gregorianToJdn($gy, 3, $march);
    }

    public static function isLeap(int $jy): bool
    {
        $a = $jy - 474;
        $b = (($a % 2820) + 2820) % 2820 + 474;
        return ((($b + 38) * 682) % 2816) < 682;
    }
}
}

namespace Nikto\Core {
final class Log
{
    private const LEVELS = ['debug' => 10, 'info' => 20, 'warn' => 30, 'error' => 40];

    private static bool $guarded = false;

    public static function guardFatals(): void
    {
        if (self::$guarded) {
            return;
        }
        self::$guarded = true;

        set_exception_handler(static function (\Throwable $e): void {
            self::error('Uncaught exception', [
                'message' => $e->getMessage(),
                'where'   => basename($e->getFile()) . ':' . $e->getLine(),
            ]);
        });

        register_shutdown_function(static function (): void {
            $error = error_get_last();
            if ($error === null || !in_array($error['type'], [E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR], true)) {
                return;
            }
            self::error('Fatal error', [
                'message' => $error['message'],
                'where'   => basename((string) $error['file']) . ':' . $error['line'],
            ]);
        });
    }

    public static function recent(int $limit = 8): array
    {
        try {
            $rows = Db::all(
                "SELECT level, message, context, created_at FROM logs
                 WHERE level IN ('error','warn') ORDER BY created_at DESC LIMIT :n",
                [':n' => $limit]
            );
        } catch (\Throwable) {
            return [];
        }

        return array_map(static fn (array $r): array => [
            'level'      => (string) $r['level'],
            'message'    => (string) $r['message'],
            'context'    => (string) $r['context'],
            'created_at' => (int) $r['created_at'],
        ], $rows);
    }

    public static function debug(string $msg, array $ctx = []): void { self::write('debug', $msg, $ctx); }
    public static function info(string $msg, array $ctx = []): void  { self::write('info', $msg, $ctx); }
    public static function warn(string $msg, array $ctx = []): void  { self::write('warn', $msg, $ctx); }
    public static function error(string $msg, array $ctx = []): void { self::write('error', $msg, $ctx); }

    private static function write(string $level, string $msg, array $ctx): void
    {
        $min = self::LEVELS[strtolower((string) Config::get('log_level', 'info'))] ?? 20;
        if ((self::LEVELS[$level] ?? 20) < $min) {
            return;
        }
        $ctxJson = $ctx ? json_encode($ctx, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) : '';
        $line = sprintf('[%s] %-5s %s %s', date('Y-m-d H:i:s'), strtoupper($level), $msg, $ctxJson);

        if (PHP_SAPI === 'cli') {
            fwrite($level === 'error' ? STDERR : STDOUT, $line . PHP_EOL);
        }
        @file_put_contents(APP_STORAGE . '/logs/bot-' . date('Y-m-d') . '.log', $line . PHP_EOL, FILE_APPEND);

        try {
            Db::exec(
                'INSERT INTO logs(level, message, context, created_at) VALUES(:l, :m, :c, :t)',
                [':l' => $level, ':m' => $msg, ':c' => $ctxJson, ':t' => time()]
            );
            if (random_int(1, 50) === 1) {
                Db::exec('DELETE FROM logs WHERE created_at < :t', [':t' => time() - 7 * 86400]);
                foreach (glob(APP_STORAGE . '/logs/bot-*.log') ?: [] as $file) {
                    if (filemtime($file) < time() - 14 * 86400) {
                        @unlink($file);
                    }
                }
            }
        } catch (\Throwable) {
        }
    }
}
}

namespace Nikto\Core {
final class PublicUrl
{
    public static function current(): string
    {
        $host = (string) ($_SERVER['HTTP_HOST'] ?? $_SERVER['SERVER_NAME'] ?? '');
        if ($host === '') {
            return '';
        }

        $https = (!empty($_SERVER['HTTPS']) && strtolower((string) $_SERVER['HTTPS']) !== 'off')
            || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https')
            || ((int) ($_SERVER['SERVER_PORT'] ?? 0) === 443);

        $path = (string) ($_SERVER['SCRIPT_NAME'] ?? '');
        $path = '/' . ltrim($path, '/');

        return ($https ? 'https' : 'http') . '://' . $host . $path;
    }

    public static function statusPage(string $version = '', string $registerHint = ''): string
    {
        $url = self::current();
        $configured = trim((string) Config::get('webhook_url', ''));

        $lines = ['NIKTO CRYPTO BOT' . ($version !== '' ? ' v' . $version : '') . ' is running.', ''];

        if ($url !== '') {
            $lines[] = 'Webhook URL for this file:';
            $lines[] = '  ' . $url;
            $lines[] = '';
            if ($configured !== '' && rtrim($configured, '/') !== rtrim($url, '/')) {
                $lines[] = 'NOTE: config says ' . $configured;
                $lines[] = 'Update webhook_url to the address above, then register it again.';
                $lines[] = '';
            }
        }
        $lines[] = 'To register this URL with Telegram, run on the server:';
        $lines[] = '  ' . ($registerHint !== '' ? $registerHint : 'php tools/webhook-set.php');

        return implode("\n", $lines) . "\n";
    }
}
}

namespace Nikto\Core {
final class Settings
{
    private static ?array $cache = null;

    public const DEFAULTS = [
        'timezone'          => 'Asia/Tehran',
        'brand'             => 'NIKTO CRYPTO',
        'brand_link'        => '',
        'digits'            => 'fa',
        'digits_data'       => 'en',
        'catchup_minutes'   => '10',
        'quality'           => 'high',
        'send_mode'         => 'photo',
        'calendar_source'   => 'auto',
        'price_source'      => 'auto',
        'calendar_min_impact' => '2',
        'calendar_currencies' => 'USD,EUR,GBP,JPY,CAD,AUD,NZD,CHF,CNY',
        'coins'             => 'BTC,ETH,XRP,BNB,SOL,TRX',
        'silent_night'      => '0',
    ];

    private static function load(): void
    {
        if (self::$cache !== null) {
            return;
        }
        self::$cache = [];
        foreach (Db::all('SELECT key, value FROM settings') as $row) {
            self::$cache[(string) $row['key']] = (string) $row['value'];
        }
    }

    public static function get(string $key, ?string $default = null): string
    {
        self::load();
        if (isset(self::$cache[$key])) {
            return self::$cache[$key];
        }
        if ($default !== null) {
            return $default;
        }
        return self::DEFAULTS[$key] ?? '';
    }

    public static function int(string $key, int $default = 0): int
    {
        $v = self::get($key, (string) $default);
        return is_numeric($v) ? (int) $v : $default;
    }

    public static function bool(string $key, bool $default = false): bool
    {
        $v = self::get($key, $default ? '1' : '0');
        return in_array(strtolower($v), ['1', 'true', 'yes', 'on'], true);
    }

    public static function set(string $key, string $value): void
    {
        self::load();
        Db::exec(
            'INSERT INTO settings(key, value) VALUES(:k, :v)
             ON CONFLICT(key) DO UPDATE SET value = excluded.value',
            [':k' => $key, ':v' => $value]
        );
        self::$cache[$key] = $value;
    }

    public static function forget(string $key): void
    {
        Db::exec('DELETE FROM settings WHERE key = :k', [':k' => $key]);
        self::$cache = null;
    }

    public static function all(): array
    {
        self::load();
        return array_replace(self::DEFAULTS, self::$cache ?? []);
    }

    public static function timezone(): \DateTimeZone
    {
        $tz = self::get('timezone');
        try {
            return new \DateTimeZone($tz);
        } catch (\Throwable) {
            return new \DateTimeZone('Asia/Tehran');
        }
    }

    public static function now(): \DateTimeImmutable
    {
        return new \DateTimeImmutable('now', self::timezone());
    }

    public static function coins(): array
    {
        $raw = self::get('coins');
        $list = array_values(array_filter(array_map(
            static fn ($s) => strtoupper(trim($s)),
            explode(',', $raw)
        )));
        return $list ?: ['BTC', 'ETH', 'XRP', 'BNB', 'SOL', 'TRX'];
    }
}
}

namespace Nikto\Data {
use DateTimeImmutable;
use DateTimeZone;
use Nikto\Core\Http;
use Nikto\Core\Log;
use Nikto\Core\Settings;

final class CalendarProvider
{
    private const FF_WEEK = 'https://nfs.faireconomy.media/ff_calendar_thisweek.json';
    private const FF_NEXT = 'https://nfs.faireconomy.media/ff_calendar_nextweek.json';
    private const TV      = 'https://economic-calendar.tradingview.com/events';

    public static function forDay(?DateTimeImmutable $day = null): array
    {
        $tz = Settings::timezone();
        $day ??= new DateTimeImmutable('now', $tz);
        $day = $day->setTimezone($tz);

        if (Mock::enabled()) {
            return self::filter(Mock::calendar($day), $day);
        }

        $source = Settings::get('calendar_source');
        $rows = [];

        if ($source === 'forexfactory' || $source === 'auto') {
            $rows = self::fromForexFactory($day);
        }
        if ($rows === [] && ($source === 'tradingview' || $source === 'auto')) {
            $rows = self::fromTradingView($day);
        }
        if ($rows === []) {
            Log::warn('Economic calendar returned no rows', ['day' => $day->format('Y-m-d')]);
        }

        return self::filter($rows, $day);
    }

    private static function fromForexFactory(DateTimeImmutable $day): array
    {
        $tz = $day->getTimezone();
        $out = [];

        foreach ([self::FF_WEEK => 'ff_week', self::FF_NEXT => 'ff_next'] as $url => $cacheKey) {
            $data = Http::cachedJson($cacheKey, $url, 1800);
            if (!is_array($data)) {
                continue;
            }
            foreach ($data as $row) {
                if (!isset($row['date'], $row['title'])) {
                    continue;
                }
                try {
                    $at = new DateTimeImmutable((string) $row['date']);
                } catch (\Throwable) {
                    continue;
                }
                $at = $at->setTimezone($tz);
                if ($at->format('Y-m-d') !== $day->format('Y-m-d')) {
                    continue;
                }
                $impactRaw = strtolower((string) ($row['impact'] ?? ''));
                $allDay = $impactRaw === 'holiday' || $at->format('H:i') === '00:00';

                $out[] = self::row(
                    $at,
                    (string) ($row['country'] ?? ''),
                    self::impactLevel($impactRaw),
                    (string) $row['title'],
                    (string) ($row['previous'] ?? ''),
                    (string) ($row['forecast'] ?? ''),
                    (string) ($row['actual'] ?? ''),
                    $allDay
                );
            }
            if ($out !== []) {
                break;
            }
        }

        return $out;
    }

    private static function fromTradingView(DateTimeImmutable $day): array
    {
        $tz = $day->getTimezone();
        $from = $day->setTime(0, 0)->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s.000\Z');
        $to   = $day->setTime(23, 59, 59)->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s.000\Z');
        $countries = 'US,EU,GB,JP,CA,AU,NZ,CH,CN,DE,FR,IT,ES';

        $url = self::TV . '?from=' . rawurlencode($from) . '&to=' . rawurlencode($to)
            . '&countries=' . rawurlencode($countries);
        $data = Http::cachedJson('tv_' . $day->format('Ymd'), $url, 1800, [
            'Origin: https://www.tradingview.com',
            'Referer: https://www.tradingview.com/',
        ]);

        if (!is_array($data) || !isset($data['result']) || !is_array($data['result'])) {
            return [];
        }

        $out = [];
        foreach ($data['result'] as $row) {
            if (!isset($row['date'], $row['title'])) {
                continue;
            }
            try {
                $at = (new DateTimeImmutable((string) $row['date']))->setTimezone($tz);
            } catch (\Throwable) {
                continue;
            }
            $importance = (int) ($row['importance'] ?? -1);
            $impact = match (true) {
                $importance >= 1  => 3,
                $importance === 0 => 2,
                default           => 1,
            };
            $currency = Countries::currencyOf((string) ($row['country'] ?? ''));

            $out[] = self::row(
                $at,
                $currency,
                $impact,
                (string) $row['title'],
                self::stringify($row['previous'] ?? null),
                self::stringify($row['forecast'] ?? null),
                self::stringify($row['actual'] ?? null),
                false
            );
        }

        return $out;
    }

    private static function row(
        DateTimeImmutable $at,
        string $currency,
        int $impact,
        string $title,
        string $previous,
        string $forecast,
        string $actual,
        bool $allDay
    ): array {
        $currency = strtoupper(trim($currency));

        return [
            'timestamp' => $at->getTimestamp(),
            'time'      => $allDay ? '' : $at->format('H:i'),
            'all_day'   => $allDay,
            'currency'  => $currency,
            'country'   => Countries::code($currency),
            'impact'    => $impact,
            'title_en'  => $title,
            'title_fa'  => EventTranslator::translate($title),
            'previous'  => self::clean($previous),
            'forecast'  => self::clean($forecast),
            'actual'    => self::clean($actual),
            'speech'    => self::isSpeech($title),
        ];
    }

    private static function filter(array $rows, DateTimeImmutable $day): array
    {
        $minImpact = max(0, min(3, Settings::int('calendar_min_impact', 2)));
        $allowed = array_values(array_filter(array_map(
            'trim',
            explode(',', strtoupper(Settings::get('calendar_currencies')))
        )));

        $out = [];
        foreach ($rows as $row) {
            $impact = (int) $row['impact'];
            $isHoliday = $impact === 0;
            if (!$isHoliday && $impact < $minImpact) {
                continue;
            }
            if ($allowed !== [] && !in_array((string) $row['currency'], $allowed, true)) {
                continue;
            }
            $out[] = $row;
        }

        usort($out, static function (array $a, array $b): int {
            if ($a['all_day'] !== $b['all_day']) {
                return $a['all_day'] ? -1 : 1;
            }
            return $a['timestamp'] <=> $b['timestamp'];
        });

        return $out;
    }

    public static function isSpeech(string $title): bool
    {
        return (bool) preg_match(
            '/(speaks?\b|speech|testif|press conference|presser|statement\b|meeting minutes)/i',
            $title
        );
    }

    private static function impactLevel(string $impact): int
    {
        return match (strtolower($impact)) {
            'high'   => 3,
            'medium' => 2,
            'low'    => 1,
            default  => 0,
        };
    }

    private static function clean(string $value): string
    {
        $value = trim($value);
        return in_array(strtolower($value), ['', 'null', 'n/a', '-'], true) ? '' : $value;
    }

    private static function stringify(mixed $value): string
    {
        if ($value === null || $value === '') {
            return '';
        }
        if (is_float($value) || is_int($value)) {
            $abs = abs((float) $value);
            if ($abs >= 1000000) {
                return round((float) $value / 1000000, 2) . 'M';
            }
            if ($abs >= 1000) {
                return round((float) $value / 1000, 1) . 'K';
            }
            return (string) round((float) $value, 2);
        }
        return (string) $value;
    }
}
}

namespace Nikto\Data {
use Nikto\Core\Config;
use Nikto\Core\Http;

final class CoinGeckoApi
{
    public const BASE = 'https://api.coingecko.com/api/v3';

    public static function enabled(): bool
    {
        return trim((string) Config::get('coingecko_key', '')) !== '';
    }

    public static function headers(): array
    {
        return self::enabled() ? ['x-cg-demo-api-key: ' . trim((string) Config::get('coingecko_key'))] : [];
    }

    public static function get(string $path, array $query = [], int $timeout = 25): ?array
    {
        return Http::getJson(self::BASE . $path . ($query !== [] ? '?' . http_build_query($query) : ''), self::headers(), $timeout, 1);
    }

    public static function futuresTickers(string $exchangeId = 'binance_futures'): array
    {
        $data = self::get('/derivatives/exchanges/' . $exchangeId, ['include_tickers' => 'unexpired'], 30);
        $rows = [];
        $ids = [];
        foreach ((array) ($data['tickers'] ?? []) as $t) {
            $base = strtoupper((string) ($t['base'] ?? ''));
            if (!is_array($t) || ($t['contract_type'] ?? '') !== 'perpetual' || strtoupper((string) ($t['target'] ?? '')) !== 'USDT'
                || !preg_match('/^[A-Z0-9]+$/', $base)
            ) {
                continue;
            }
            $pair = $base . 'USDT';
            $last = (float) ($t['converted_last']['usd'] ?? 0) ?: (float) ($t['last'] ?? 0);
            $rows[] = Exchanges::ticker($pair, $last, (float) ($t['h24_percentage_change'] ?? 0), 0.0, 0.0, (float) ($t['converted_volume']['usd'] ?? 0));
            if (($t['coin_id'] ?? '') !== '') {
                $ids[$pair] = (string) $t['coin_id'];
            }
        }

        return [$rows, $ids];
    }

    public static function sparklines(array $coinIds): array
    {
        $coinIds = array_values(array_unique(array_filter($coinIds)));
        if ($coinIds === []) {
            return [];
        }
        $data = self::get('/coins/markets', ['vs_currency' => 'usd', 'ids' => implode(',', $coinIds), 'sparkline' => 'true', 'per_page' => 250]);
        $out = [];
        foreach (is_array($data) ? $data : [] as $row) {
            $prices = $row['sparkline_in_7d']['price'] ?? null;
            if (is_array($row) && isset($row['id']) && is_array($prices)) {
                $out[(string) $row['id']] = array_slice(array_map('floatval', $prices), -24);
            }
        }

        return $out;
    }
}
}

namespace Nikto\Data {
use Nikto\Core\Config;
use Nikto\Core\Http;

final class CoinGlass
{
    public const NAME_FA = 'کوین‌گلس';

    private const BASE = 'https://open-api-v4.coinglass.com/api';

    public static function enabled(): bool
    {
        return trim((string) Config::get('coinglass_key', '')) !== '';
    }

    public static function get(string $path, array $query = []): mixed
    {
        if (!self::enabled()) {
            return null;
        }
        $url = self::BASE . $path . ($query !== [] ? '?' . http_build_query($query) : '');
        $res = Http::getJson($url, ['CG-API-KEY: ' . trim((string) Config::get('coinglass_key'))], 20, 0);
        if (!is_array($res)) {
            return null;
        }
        if ((string) ($res['code'] ?? '') !== '0') {
            Http::note($url, 0, 'CoinGlass ' . (string) ($res['code'] ?? '?') . ': ' . (string) ($res['msg'] ?? 'unknown error'));
            return null;
        }

        return $res['data'] ?? null;
    }

    public static function book(string $exchange, string $pair): ?array
    {
        $data = self::get('/futures/orderbook/history', ['exchange' => $exchange, 'symbol' => $pair, 'interval' => '1m', 'limit' => 1]);
        $snap = is_array($data) && $data !== [] ? end($data) : null;
        if (!is_array($snap) || !is_array($snap[1] ?? null) || !is_array($snap[2] ?? null)) {
            return null;
        }
        $a = self::levels($snap[1]);
        $b = self::levels($snap[2]);
        if ($a === [] || $b === []) {
            return null;
        }
        return self::median($a) >= self::median($b) ? ['bids' => $b, 'asks' => $a] : ['bids' => $a, 'asks' => $b];
    }

    public static function klines(string $exchange, string $pair, int $limit): array
    {
        $data = self::get('/futures/price/history', ['exchange' => $exchange, 'symbol' => $pair, 'interval' => '1h', 'limit' => $limit]);
        $out = [];
        foreach (is_array($data) ? $data : [] as $k) {
            if (is_array($k) && is_numeric($k['time'] ?? null) && is_numeric($k['close'] ?? null)) {
                $out[] = [(int) $k['time'], (float) ($k['open'] ?? 0), (float) ($k['high'] ?? 0), (float) ($k['low'] ?? 0), (float) $k['close']];
            }
        }
        usort($out, static fn (array $a, array $b): int => $a[0] <=> $b[0]);

        return array_slice($out, -$limit);
    }

    public static function futuresTickers(): array
    {
        $out = [];
        for ($page = 1; $page <= 5; $page++) {
            $data = self::get('/futures/coins-markets', ['per_page' => 200, 'page' => $page]);
            if (!is_array($data) || $data === []) {
                break;
            }
            foreach ($data as $c) {
                $base = strtoupper((string) ($c['symbol'] ?? ''));
                if (!is_array($c) || !preg_match('/^[A-Z0-9]+$/', $base) || !is_numeric($c['current_price'] ?? null)) {
                    continue;
                }
                $ratio = (float) ($c['open_interest_volume_ratio'] ?? 0);
                $out[] = Exchanges::ticker(
                    $base . 'USDT',
                    (float) $c['current_price'],
                    (float) ($c['price_change_percent_24h'] ?? 0),
                    0.0,
                    0.0,
                    $ratio > 0 ? (float) ($c['open_interest_usd'] ?? 0) / $ratio : 0.0
                );
            }
            if (count($data) < 200) {
                break;
            }
        }

        return $out;
    }

    private static function levels(array $levels): array
    {
        $out = [];
        foreach ($levels as $l) {
            if (is_array($l) && is_numeric($l[0] ?? null) && is_numeric($l[1] ?? null) && (float) $l[1] > 0) {
                $out[] = [(float) $l[0], (float) $l[1]];
            }
        }

        return $out;
    }

    private static function median(array $levels): float
    {
        $prices = array_column($levels, 0);
        sort($prices);

        return (float) $prices[intdiv(count($prices), 2)];
    }
}
}

