            );
        }

        return $out;
    }

    private static function gate(string $path, string $key, string $volumeKey): array
    {
        $list = Http::getJson(self::GATE . $path, [], 25, 1);
        if (!is_array($list) || array_values($list) !== $list) {
            return [];
        }
        $out = [];
        foreach ($list as $t) {
            if (!is_array($t) || !preg_match('/^([A-Z0-9]+)_USDT$/', (string) ($t[$key] ?? ''), $m)) {
                continue;
            }
            $out[] = self::ticker(
                $m[1] . 'USDT',
                (float) ($t['last'] ?? 0),
                (float) ($t['change_percentage'] ?? 0),
                (float) ($t['high_24h'] ?? 0),
                (float) ($t['low_24h'] ?? 0),
                (float) ($t[$volumeKey] ?? 0)
            );
        }

        return $out;
    }

    /** First Ourbit ticker endpoint that answers with a list; field names differ between its futures and spot APIs. */
    private static function ourbit(): array
    {
        foreach (self::OURBIT_TICKERS as $url) {
            $res = Http::getJson($url, [], 20, 0);
            $list = self::ourbitList($res);
            $out = [];
            foreach ($list as $t) {
                if (!is_array($t)) {
                    continue;
                }
                $symbol = strtoupper((string) ($t['symbol'] ?? $t['s'] ?? $t['sb'] ?? ''));
                if (!preg_match('/^([A-Z0-9]+)_?USDT$/', $symbol, $m)) {
                    continue;
                }
                $last = self::num($t, ['lastPrice', 'last', 'c', 'p', 'close']);
                if ($last <= 0) {
                    continue;
                }
                // riseFallRate / r are fractions (0.0123); priceChangePercent is already a percent.
                $pct = isset($t['priceChangePercent'])
                    ? (float) rtrim((string) $t['priceChangePercent'], '%')
                    : self::num($t, ['riseFallRate', 'r', 'rate', 'change24h']) * 100;
                $out[] = self::ticker(
                    $m[1] . 'USDT',
                    $last,
                    $pct,
                    self::num($t, ['high24Price', 'high', 'h']),
                    self::num($t, ['lower24Price', 'low', 'l']),
                    self::num($t, ['amount24', 'quoteVolume', 'a', 'amount', 'volume24', 'v'])
                );
            }
            if ($out !== []) {
                return $out;
            }
            if (is_array($res)) {
                // Answered, but not in a shape we know: record it so the diagnostics show what came back.
                Http::note($url, 0, 'Ourbit: unknown format ' . mb_substr((string) json_encode($res), 0, 120));
            }
        }

        return [];
    }

    private static function ourbitList(mixed $res): array
    {
        $data = is_array($res) ? ($res['data'] ?? $res) : null;
        if (is_array($data) && isset($data['list']) && is_array($data['list'])) {
            $data = $data['list'];
        }

        return is_array($data) && array_values($data) === $data ? $data : [];
    }

    /** Accepts column arrays {t:[],o:[],h:[],l:[],c:[]}, a list of objects, or a list of [t, o, h, l, c]. */
    private static function ourbitCandles(mixed $data): array
    {
        $out = [];
        if (is_array($data) && isset($data['t']) && is_array($data['t'])) {
            foreach ($data['t'] as $i => $t) {
                $out[] = self::candle(self::ms($t), $data['o'][$i] ?? null, $data['h'][$i] ?? null, $data['l'][$i] ?? null, $data['c'][$i] ?? null);
            }
        } elseif (is_array($data)) {
            foreach ($data as $k) {
                if (!is_array($k)) {
                    continue;
                }
                $out[] = array_values($k) === $k
                    ? self::candle(self::ms($k[0] ?? null), $k[1] ?? null, $k[2] ?? null, $k[3] ?? null, $k[4] ?? null)
                    : self::candle(self::ms($k['t'] ?? $k['time'] ?? null), $k['o'] ?? $k['open'] ?? null, $k['h'] ?? $k['high'] ?? null, $k['l'] ?? $k['low'] ?? null, $k['c'] ?? $k['close'] ?? null);
            }
        }

        return $out;
    }

    private static function ms(mixed $t): mixed
    {
        return is_numeric($t) && (float) $t < 1e12 ? (float) $t * 1000 : $t;
    }

    private static function num(array $row, array $keys): float
    {
        foreach ($keys as $k) {
            if (isset($row[$k]) && is_numeric($row[$k])) {
                return (float) $row[$k];
            }
        }

        return 0.0;
    }

    private static function bitget(): array
    {
        $list = Http::getJson(self::BITGET . '/tickers?productType=USDT-FUTURES', [], 20, 1)['data'] ?? null;
        $out = [];
        foreach (is_array($list) ? $list : [] as $t) {
            if (!is_array($t) || !preg_match('/^[A-Z0-9]+USDT$/', (string) ($t['symbol'] ?? ''))) {
                continue;
            }
            $out[] = self::ticker(
                (string) $t['symbol'],
                (float) ($t['lastPr'] ?? 0),
                (float) ($t['change24h'] ?? 0) * 100,
                (float) ($t['high24h'] ?? 0),
                (float) ($t['low24h'] ?? 0),
                (float) ($t['quoteVolume'] ?? ($t['usdtVolume'] ?? 0))
            );
        }

        return $out;
    }

    private static function bingx(): array
    {
        $list = Http::getJson(self::BINGX . '/v2/quote/ticker', [], 20, 1)['data'] ?? null;
        $out = [];
        foreach (is_array($list) ? $list : [] as $t) {
            if (!is_array($t) || !preg_match('/^([A-Z0-9]+)-USDT$/', (string) ($t['symbol'] ?? ''), $m)) {
                continue;
            }
            $out[] = self::ticker(
                $m[1] . 'USDT',
                (float) ($t['lastPrice'] ?? 0),
                (float) rtrim((string) ($t['priceChangePercent'] ?? '0'), '%'),
                (float) ($t['highPrice'] ?? 0),
                (float) ($t['lowPrice'] ?? 0),
                (float) ($t['quoteVolume'] ?? 0)
            );
        }

        return $out;
    }

    private static function coinex(): array
    {
        $list = Http::getJson(self::COINEX . '/ticker', [], 20, 1)['data'] ?? null;
        $out = [];
        foreach (is_array($list) ? $list : [] as $t) {
            if (!is_array($t) || !preg_match('/^[A-Z0-9]+USDT$/', (string) ($t['market'] ?? ''))) {
                continue;
            }
            $last = (float) ($t['last'] ?? 0);
            $open = (float) ($t['open'] ?? 0);
            $out[] = self::ticker((string) $t['market'], $last, $open > 0 ? ($last - $open) / $open * 100 : 0.0, (float) ($t['high'] ?? 0), (float) ($t['low'] ?? 0), (float) ($t['value'] ?? 0));
        }

        return $out;
    }

    private static function htx(): array
    {
        $list = Http::getJson(self::HTX . '/detail/batch_merged?business_type=swap', [], 20, 1)['ticks'] ?? null;
        $out = [];
        foreach (is_array($list) ? $list : [] as $t) {
            if (!is_array($t) || !preg_match('/^([A-Z0-9]+)-USDT$/', (string) ($t['contract_code'] ?? ''), $m)) {
                continue;
            }
            $last = (float) ($t['close'] ?? 0);
            $open = (float) ($t['open'] ?? 0);
            $out[] = self::ticker($m[1] . 'USDT', $last, $open > 0 ? ($last - $open) / $open * 100 : 0.0, (float) ($t['high'] ?? 0), (float) ($t['low'] ?? 0), (float) ($t['trade_turnover'] ?? 0));
        }

        return $out;
    }

    private static function nobitex(array $bases): array
    {
        $bases = array_values(array_filter(array_map('strtolower', $bases), static fn ($b) => preg_match('/^[a-z0-9]+$/', $b) === 1));
        if ($bases === []) {
            return [];
        }
        $stats = Http::getJson(self::NOBITEX . '/market/stats?srcCurrency=' . implode(',', $bases) . '&dstCurrency=usdt', [], 20, 1)['stats'] ?? null;
        $out = [];
        foreach (is_array($stats) ? $stats : [] as $market => $t) {
            if (!is_array($t) || !preg_match('/^([a-z0-9]+)-usdt$/', (string) $market, $m) || !empty($t['isClosed'])) {
                continue;
            }
            $out[] = self::ticker(
                strtoupper($m[1]) . 'USDT',
                (float) ($t['latest'] ?? 0),
                (float) ($t['dayChange'] ?? 0),
                (float) ($t['dayHigh'] ?? 0),
                (float) ($t['dayLow'] ?? 0),
                (float) ($t['volumeDst'] ?? 0)
            );
        }

        return $out;
    }
}
}

namespace Nikto\Data {
use Nikto\Core\Http;
use Nikto\Core\Log;

final class FearGreedProvider
{
    private const URL = 'https://api.alternative.me/fng/?limit=32&format=json';

    public const ZONES = [
        ['max' => 24,  'fa' => 'ترس شدید',  'en' => 'Extreme Fear',  'color' => '#E1273E'],
        ['max' => 44,  'fa' => 'ترس',       'en' => 'Fear',          'color' => '#F0762B'],
        ['max' => 55,  'fa' => 'خنثی',      'en' => 'Neutral',       'color' => '#F3C13A'],
        ['max' => 75,  'fa' => 'طمع',       'en' => 'Greed',         'color' => '#93C846'],
        ['max' => 100, 'fa' => 'طمع شدید',  'en' => 'Extreme Greed', 'color' => '#15A05F'],
    ];

    public static function fetch(): ?array
    {
        if (Mock::enabled()) {
            return Mock::fearGreed();
        }

        $data = Http::cachedJson('fng', self::URL, 900);
        if (!is_array($data) || !isset($data['data']) || !is_array($data['data']) || $data['data'] === []) {
            Log::error('Fear & Greed fetch failed');
            return null;
        }

        $series = [];
        foreach ($data['data'] as $row) {
            $series[] = [
                'value'     => (int) ($row['value'] ?? 0),
                'class'     => (string) ($row['value_classification'] ?? ''),
                'timestamp' => (int) ($row['timestamp'] ?? 0),
            ];
        }

        return self::build($series);
    }

    public static function build(array $series): array
    {
        $today = $series[0] ?? ['value' => 50, 'class' => 'Neutral', 'timestamp' => time()];
        $pick = static function (array $series, int $index): ?array {
            return $series[$index] ?? null;
        };

        $history = [];
        foreach (['yesterday' => 1, 'week' => 7, 'month' => 30] as $key => $index) {
            $row = $pick($series, $index);
            if ($row === null) {
                continue;
            }
            $history[$key] = [
                'value' => (int) $row['value'],
                'zone'  => self::zone((int) $row['value']),
            ];
        }

        $value = (int) $today['value'];
        $zone = self::zone($value, (string) ($today['class'] ?? ''));

        return [
            'value'     => $value,
            'zone'      => $zone,
            'history'   => $history,
            'series'    => array_reverse(array_map(static fn ($r) => (int) $r['value'], array_slice($series, 0, 30))),
            'timestamp' => (int) ($today['timestamp'] ?? time()),
        ];
    }

    public static function zone(int $value, string $classification = ''): array
    {
        if ($classification !== '') {
            foreach (self::ZONES as $zone) {
                if (strcasecmp($zone['en'], $classification) === 0) {
                    return ['fa' => $zone['fa'], 'en' => $zone['en'], 'color' => $zone['color']];
                }
            }
        }
        foreach (self::ZONES as $zone) {
            if ($value <= $zone['max']) {
                return ['fa' => $zone['fa'], 'en' => $zone['en'], 'color' => $zone['color']];
            }
        }
        $last = self::ZONES[count(self::ZONES) - 1];

        return ['fa' => $last['fa'], 'en' => $last['en'], 'color' => $last['color']];
    }
}
}

namespace Nikto\Data {
use Nikto\Core\Http;
use Nikto\Core\Log;

final class FuturesProvider
{
    public const SOURCE_BINANCE = 'Binance Futures';

    private const FAPI = 'https://fapi.binance.com/fapi/v1';
    private const SPOT_MIRROR = 'https://data-api.binance.vision/api/v3';

    public static function movers(int $count = 5, float $minVolume = 5_000_000, bool $withSparkline = true): ?array
    {
        $count = max(1, min(8, $count));

        if (Mock::enabled()) {
            $tickers = Mock::futuresTickers();
            $tradable = self::tradable(Mock::futuresExchangeInfo());
            $exchange = 'Binance';
            $coinIds = [];
        } else {
            [$tickers, $tradable, $exchange, $coinIds] = self::tickers();
        }

        if (!is_array($tickers) || $tickers === [] || array_values($tickers) !== $tickers) {
            Log::error('Futures tickers unavailable from every source');
            return null;
        }

        $result = self::rank($tickers, $tradable ?: null, $count, $minVolume);
        if ($result === null) {
            return null;
        }
        $result['exchange'] = 'Ourbit';
        $result['source'] = 'Ourbit Futures';
        $result['data_source'] = $exchange;
        if ($exchange !== 'Ourbit') {
            Log::warn('Movers card labelled Ourbit but served by fallback', ['source' => $exchange]);
        }

        if ($withSparkline) {
            $shown = array_merge(array_column($result['gainers'], 'pair'), array_column($result['losers'], 'pair'));
            $geckoSparks = $exchange === 'CoinGecko'
                ? CoinGeckoApi::sparklines(array_map(static fn (string $p): string => $coinIds[$p] ?? '', $shown))
                : [];
            foreach (['gainers', 'losers'] as $side) {
                foreach ($result[$side] as $i => $row) {
                    $pair = (string) $row['pair'];
                    $result[$side][$i]['spark'] = $geckoSparks[$coinIds[$pair] ?? ''] ?? self::sparkline($pair, (float) $row['change_pct'], $exchange);
                }
            }
        }

        return $result;
    }

    private static function tickers(): array
    {
        // Ourbit is the chosen source for this card; everything below is a fallback.
        $rows = Exchanges::futuresTickers('Ourbit');
        if ($rows !== []) {
            return [$rows, null, 'Ourbit', []];
        }
        if (CoinGlass::enabled()) {
            $rows = CoinGlass::futuresTickers();
            if ($rows !== []) {
                return [$rows, null, 'CoinGlass', []];
            }
        }
        if (CoinGeckoApi::enabled()) {
            [$rows, $ids] = CoinGeckoApi::futuresTickers();
            if ($rows !== []) {
                return [$rows, null, 'CoinGecko', $ids];
            }
        }

        $tickers = Http::getJson(self::FAPI . '/ticker/24hr', [], 20, 1);
        if (is_array($tickers) && $tickers !== [] && array_values($tickers) === $tickers) {
            $tradable = Http::remember('fapi:tradable', 6 * 3600, static function (): ?array {
                $info = Http::getJson(self::FAPI . '/exchangeInfo', [], 25, 1);
                return is_array($info) ? self::tradable($info) : null;
            });

            return [$tickers, $tradable, 'Binance', []];
        }

        foreach (Exchanges::FUTURES as $exchange) {
            $rows = Exchanges::futuresTickers($exchange);
            if ($rows !== []) {
                Log::warn('Futures tickers served by fallback exchange', ['exchange' => $exchange]);
                return [$rows, null, $exchange, []];
            }
        }

        return [null, null, 'Binance', []];
    }

    public static function tradable(array $exchangeInfo): array
    {
        $out = [];
        foreach ((array) ($exchangeInfo['symbols'] ?? []) as $s) {
            if (!is_array($s)) {
                continue;
            }
            if (($s['contractType'] ?? '') !== 'PERPETUAL'
                || ($s['status'] ?? '') !== 'TRADING'
                || ($s['quoteAsset'] ?? '') !== 'USDT'
            ) {
                continue;
            }
            $symbol = (string) ($s['symbol'] ?? '');
            if ($symbol !== '') {
                $out[$symbol] = (string) ($s['baseAsset'] ?? substr($symbol, 0, -4));
            }
        }

        return $out;
    }

    public static function rank(array $tickers, ?array $tradable, int $count, float $minVolume): ?array
    {
        $rows = [];
        foreach ($tickers as $t) {
            if (!is_array($t) || !is_string($t['symbol'] ?? null)) {
                continue;
            }
            $pair = $t['symbol'];

            if ($tradable !== null) {
                if (!isset($tradable[$pair])) {
                    continue;
                }
                $base = $tradable[$pair];
            } else {
                if (!preg_match('/^([A-Z0-9]+)USDT$/', $pair, $m)) {
                    continue;
                }
                $base = $m[1];
            }

            $price = (float) ($t['lastPrice'] ?? 0);
            if ($price <= 0 || (int) ($t['count'] ?? 1) === 0) {
                continue;
            }

            $rows[] = [
                'symbol'       => $base,
                'logo'         => self::logoSymbol($base),
                'pair'         => $pair,
                'price'        => $price,
                'change_pct'   => (float) ($t['priceChangePercent'] ?? 0),
                'change_abs'   => (float) ($t['priceChange'] ?? 0),
                'high'         => (float) ($t['highPrice'] ?? 0),
                'low'          => (float) ($t['lowPrice'] ?? 0),
                'quote_volume' => (float) ($t['quoteVolume'] ?? 0),
                'spark'        => [],
            ];
        }

        if ($rows === []) {
            return null;
        }

        $up = $down = 0;
        $sum = 0.0;
        foreach ($rows as $r) {
            $sum += $r['change_pct'];
            if ($r['change_pct'] > 0.005) {
                $up++;
            } elseif ($r['change_pct'] < -0.005) {
                $down++;
            }
        }
        $breadth = [
            'up'    => $up,
            'down'  => $down,
            'flat'  => count($rows) - $up - $down,
            'total' => count($rows),
            'avg'   => $sum / count($rows),
        ];

        $liquid = array_values(array_filter($rows, static fn (array $r): bool => $r['quote_volume'] >= $minVolume));
        if (count($liquid) < $count * 2) {
            $liquid = $rows;
        }

        usort($liquid, static fn (array $a, array $b): int => $b['change_pct'] <=> $a['change_pct']);
        $gainers = array_slice($liquid, 0, $count);
        $losers = array_slice(array_reverse($liquid), 0, $count);

        $taken = array_column($gainers, 'pair');
        $losers = array_values(array_filter($losers, static fn (array $r): bool => !in_array($r['pair'], $taken, true)));

        return [
            'gainers'    => $gainers,
            'losers'     => $losers,
            'breadth'    => $breadth,
            'min_volume' => $minVolume,
        ];
    }

    public static function logoSymbol(string $base): string
    {
        return (string) (preg_replace('/^(1000000|100000|10000|1000|1M)(?=[A-Z])/', '', strtoupper($base)) ?: $base);
    }

    private static function sparkline(string $pair, float $changePct, string $exchange = 'Binance'): array
    {
        if (Mock::enabled()) {
            return Mock::series(crc32($pair), 24, $changePct);
        }

        $candles = match ($exchange) {
            'Binance'   => Http::getJson(self::FAPI . '/klines?symbol=' . rawurlencode($pair) . '&interval=1h&limit=24', [], 12, 1),
            'CoinGlass' => CoinGlass::klines('Binance', $pair, 24),
            'CoinGecko' => [],
            default     => Exchanges::klines($exchange, 'futures', $pair, 24),
        };
        if (!is_array($candles) || $candles === []) {
            $candles = Http::getJson(self::SPOT_MIRROR . '/klines?symbol=' . rawurlencode($pair) . '&interval=1h&limit=24', [], 12, 0);
        }

        $out = [];
        foreach (is_array($candles) ? $candles : [] as $candle) {
            if (is_array($candle) && isset($candle[4]) && is_numeric($candle[4])) {
                $out[] = (float) $candle[4];
            }
        }

        return $out;
    }

    public static function formatVolume(float $usd): string
    {
        foreach ([[1e9, 'B'], [1e6, 'M'], [1e3, 'K']] as [$unit, $suffix]) {
            if ($usd >= $unit) {
                $v = $usd / $unit;
                return '$' . number_format($v, $v >= 100 ? 0 : 1) . $suffix;
            }
        }

        return '$' . number_format($usd, 0);
    }
}
}

namespace Nikto\Data {
use Nikto\Core\Http;
use Nikto\Core\Log;

final class LiquidityProvider
{
    private const FAPI = 'https://fapi.binance.com/fapi/v1';
    private const SPOT = ['https://api.binance.com/api/v3', 'https://data-api.binance.vision/api/v3'];

    private const WALL_FACTOR = 1.5;

    public static function btc(int $levels = 5): ?array
    {
        $levels = max(2, min(8, $levels));

        if (Mock::enabled()) {
            return self::analyze(
                ['Binance Futures' => Mock::btcDepth('futures'), 'Binance Spot' => Mock::btcDepth('spot')],
                Mock::btcKlines(),
                $levels
            );
        }

        $books = [];
        $klines = [];
        if (CoinGlass::enabled()) {
            foreach (['Binance', 'Bybit'] as $exchange) {
                $book = CoinGlass::book($exchange, 'BTCUSDT');
                if ($book !== null) {
                    $books[($books === [] ? 'CoinGlass · ' : '') . $exchange] = $book;
                }
            }
            $klines = CoinGlass::klines('Binance', 'BTCUSDT', 48);
            if ($books !== []) {
                return self::analyze($books, $klines !== [] ? $klines : self::klines(null), $levels);
            }
        }

        $futures = Http::getJson(self::FAPI . '/depth?symbol=BTCUSDT&limit=1000', [], 15, 1);
        if (self::isBook($futures)) {
            $books['Binance Futures'] = $futures;
        }
        foreach (self::SPOT as $base) {
            $spot = Http::getJson($base . '/depth?symbol=BTCUSDT&limit=5000', [], 20, 1);
            if (self::isBook($spot)) {
                $books['Binance Spot'] = $spot;
                break;
            }
        }

        $fallback = null;
        if ($books === []) {
            foreach (Exchanges::BOOKS as $exchange => $name) {
                $book = Exchanges::book($exchange, 'BTCUSDT');
                if ($book === null) {
                    continue;
                }
                $books[$name] = $book;
                $fallback ??= $exchange;
                if (count($books) >= 3) {
                    break;
                }
            }
            if (count($books) > 1 && isset($books['Hyperliquid'])) {
                $grouped = $books['Hyperliquid'];
                unset($books['Hyperliquid']);
                $books['Hyperliquid'] = $grouped;
            }
            if ($books !== []) {
                Log::warn('BTC order book served by fallback exchanges', ['sources' => array_keys($books)]);
            }
        }
        if ($books === []) {
            Log::error('BTC order book unavailable');
            return null;
        }

        return self::analyze($books, $klines !== [] ? $klines : self::klines($fallback), $levels);
    }

    private static function klines(?string $preferred): array
    {
        $klines = Http::getJson(self::FAPI . '/klines?symbol=BTCUSDT&interval=1h&limit=48', [], 15, 1);
        if (!is_array($klines)) {
            foreach (self::SPOT as $base) {
                $klines = Http::getJson($base . '/klines?symbol=BTCUSDT&interval=1h&limit=48', [], 15, 1);
                if (is_array($klines)) {
                    break;
                }
            }
        }
        if (!is_array($klines) || $klines === []) {
            $order = array_unique(array_merge($preferred !== null ? [$preferred] : [], ['Hyperliquid'], Exchanges::SPOT));
            foreach ($order as $exchange) {
                $klines = Exchanges::klines($exchange, 'spot', 'BTCUSDT', 48);
                if ($klines !== []) {
                    break;
                }
            }
        }

        return is_array($klines) ? $klines : [];
    }

    private static function isBook(mixed $data): bool
    {
        return is_array($data) && is_array($data['bids'] ?? null) && is_array($data['asks'] ?? null)
            && $data['bids'] !== [] && $data['asks'] !== [];
    }

    public static function analyze(array $books, array $klines, int $levels = 5): ?array
    {
        $parsed = [];
        foreach ($books as $name => $book) {
            if (!self::isBook($book)) {
                continue;
            }
            $bids = self::side($book['bids']);
            $asks = self::side($book['asks']);
            if ($bids !== [] && $asks !== []) {
                $parsed[$name] = [$bids, $asks];
            }
        }
        if ($parsed === []) {
            return null;
        }

        [$refBids, $refAsks] = reset($parsed);
        $bestBid = max(array_column($refBids, 0));
        $bestAsk = min(array_column($refAsks, 0));
        $mid = ($bestBid + $bestAsk) / 2;

        $candles = self::candles($klines);
        $price = $candles !== [] ? (float) end($candles)['c'] : $mid;

        $bucket = self::niceStep($mid * 0.001);

        $bidBuckets = [];
        $askBuckets = [];
        $bidFloor = $mid;
        $askCeil = $mid;
        foreach ($parsed as [$bids, $asks]) {
            foreach ($bids as [$p, $q]) {
                if ($p > $mid) {
                    continue;
                }
                $key = (string) (round($p / $bucket) * $bucket);
                $bidBuckets[$key] = ($bidBuckets[$key] ?? 0.0) + $q;
                $bidFloor = min($bidFloor, $p);
            }
            foreach ($asks as [$p, $q]) {
                if ($p < $mid) {
                    continue;
                }
                $key = (string) (round($p / $bucket) * $bucket);
                $askBuckets[$key] = ($askBuckets[$key] ?? 0.0) + $q;
                $askCeil = max($askCeil, $p);
            }
        }
        if ($bidBuckets === [] || $askBuckets === []) {
            return null;
        }

        $range = min($mid - $bidFloor, $askCeil - $mid);
        $bidTotal = 0.0;
        $askTotal = 0.0;
        foreach ($bidBuckets as $p => $q) {
            if ((float) $p >= $mid - $range) {
                $bidTotal += $q * (float) $p;
            }
        }
        foreach ($askBuckets as $p => $q) {
            if ((float) $p <= $mid + $range) {
                $askTotal += $q * (float) $p;
            }
        }

        $bidWalls = self::walls($bidBuckets, $bucket, $mid, $levels);
        $askWalls = self::walls($askBuckets, $bucket, $mid, $levels);
        $maxQty = max(array_merge([1e-9], array_column($bidWalls, 'qty'), array_column($askWalls, 'qty')));
        foreach ([&$bidWalls, &$askWalls] as &$list) {
            foreach ($list as &$w) {
                $w['strength'] = $w['qty'] / $maxQty;
            }
            unset($w);
        }
        unset($list);

        return [
            'symbol'      => 'BTC',
            'price'       => $price,
            'mid'         => $mid,
            'best_bid'    => $bestBid,
            'best_ask'    => $bestAsk,
            'spread'      => $bestAsk - $bestBid,
            'bucket'      => $bucket,
            'range_pct'   => $range / $mid * 100,
            'bid_total'   => $bidTotal,
            'ask_total'   => $askTotal,
            'imbalance'   => ($bidTotal + $askTotal) > 0 ? $bidTotal / ($bidTotal + $askTotal) : 0.5,
            'bid_walls'   => $bidWalls,
            'ask_walls'   => $askWalls,
            'profile'     => self::profile($bidBuckets, $askBuckets),
            'candles'     => $candles,
            'sources'     => array_keys($parsed),
        ];
    }

    private static function side(array $levels): array
    {
        $out = [];
        foreach ($levels as $level) {
            if (!is_array($level) || !isset($level[0], $level[1])) {
                continue;
            }
            $p = (float) $level[0];
            $q = (float) $level[1];
            if ($p > 0 && $q > 0) {
                $out[] = [$p, $q];
            }
        }

        return $out;
    }

    private static function walls(array $buckets, float $bucket, float $mid, int $levels): array
    {
        $qtys = array_values($buckets);
        sort($qtys);
        $median = $qtys[intdiv(count($qtys), 2)] ?? 0.0;
        $threshold = $median * self::WALL_FACTOR;

        arsort($buckets);
        $picked = [];
        foreach ($buckets as $p => $q) {
            if ($q < $threshold || count($picked) >= $levels) {
                break;
            }
            $price = (float) $p;
            foreach ($picked as $w) {
                if (abs($w['price'] - $price) < $bucket * 2.5) {
                    continue 2;
                }
            }
            $picked[] = [
                'price'        => $price,
                'qty'          => $q,
                'usd'          => $q * $price,
                'distance_pct' => ($price - $mid) / $mid * 100,
            ];
        }

        usort($picked, static fn (array $a, array $b): int => abs($a['distance_pct']) <=> abs($b['distance_pct']));

        return $picked;
    }

    private static function profile(array $bidBuckets, array $askBuckets): array
    {
        $toList = static function (array $buckets): array {
            $out = [];
            foreach ($buckets as $p => $q) {
                $out[] = [(float) $p, (float) $q];
            }
            usort($out, static fn (array $a, array $b): int => $a[0] <=> $b[0]);
            return $out;
        };

        return ['bids' => $toList($bidBuckets), 'asks' => $toList($askBuckets)];
    }

    private static function candles(array $klines): array
    {
        $out = [];
        foreach ($klines as $k) {
            if (!is_array($k) || !isset($k[0], $k[1], $k[2], $k[3], $k[4])) {
                continue;
            }
            $c = ['t' => (int) ((int) $k[0] / 1000), 'o' => (float) $k[1], 'h' => (float) $k[2], 'l' => (float) $k[3], 'c' => (float) $k[4]];
            if ($c['h'] > 0 && $c['l'] > 0 && $c['h'] >= $c['l']) {
                $out[] = $c;
            }
        }

        return $out;
    }

    public static function niceStep(float $raw): float
    {
        if ($raw <= 0) {
            return 1.0;
        }
        $pow = 10 ** floor(log10($raw));
        foreach ([1, 2.5, 5, 10] as $m) {
            if ($m * $pow >= $raw - 1e-9) {
                return $m * $pow;
            }
        }

        return 10 * $pow;
    }

    public static function formatBtc(float $qty): string
    {
        return number_format($qty, $qty >= 100 ? 0 : 1) . ' BTC';
    }

    public static function formatUsd(float $usd): string
    {
        return FuturesProvider::formatVolume($usd);
    }
}
}

namespace Nikto\Data {
use DateTimeImmutable;

final class Mock
{
    private static ?bool $forced = null;

    public static function enable(bool $on = true): void
    {
        self::$forced = $on;
    }

    public static function enabled(): bool
    {
        if (self::$forced !== null) {
            return self::$forced;
        }
        return in_array(strtolower((string) getenv('NIKTO_MOCK')), ['1', 'true', 'yes'], true);
    }

    public static function prices(array $symbols): array
    {
        $fixture = self::load('prices.json');
        $out = [];
        foreach ($symbols as $i => $symbol) {
            $symbol = strtoupper($symbol);
            $data = $fixture[$symbol] ?? [
                'price'      => 12.5 + $i * 7.3,
                'change_pct' => ((($i * 37) % 11) - 5) / 1.7,
            ];
            $price = (float) $data['price'];
            $pct   = (float) $data['change_pct'];
            $abs   = $data['change_abs'] ?? ($price - $price / (1 + $pct / 100));

            $out[] = PriceProvider::row(
                $symbol,
                $price,
                $pct,
                (float) $abs,
                $price * 1.035,
                $price * 0.962,
                (float) ($data['volume'] ?? 1.2e9 / ($i + 1)),
                self::sparkline($price, $pct, crc32($symbol))
            );
        }

        return $out;
    }

    private static function sparkline(float $price, float $pct, int $seed): array
    {
        mt_srand($seed);
        $start = $price / (1 + $pct / 100);
        $points = [];
        for ($i = 0; $i < 24; $i++) {
            $t = $i / 23;
            $trend = $start + ($price - $start) * $t;
            $noise = $trend * (mt_rand(-45, 45) / 10000);
            $points[] = round($trend + $noise, 8);
        }
        $points[23] = $price;
        mt_srand();

        return $points;
    }

    public static function fearGreed(): array
    {
        $fixture = self::load('feargreed.json');
        $series = [];
        foreach (($fixture['series'] ?? [27, 26, 24, 22, 19, 18, 17, 16]) as $i => $value) {
            $series[] = [
                'value'     => (int) $value,
                'class'     => '',
                'timestamp' => time() - $i * 86400,
            ];
        }
        while (count($series) < 32) {
            $series[] = ['value' => 11 + (count($series) % 7), 'class' => '', 'timestamp' => time() - count($series) * 86400];
        }

        return FearGreedProvider::build($series);
    }

    public static function calendar(DateTimeImmutable $day): array
    {
        $fixture = self::load('calendar.json');
        $rows = [];
        foreach ($fixture as $item) {
            $time = (string) ($item['time'] ?? '');
            $allDay = $time === '';
            $at = $allDay
                ? $day->setTime(0, 0)
                : $day->setTime((int) substr($time, 0, 2), (int) substr($time, 3, 2));

            $title = (string) ($item['title'] ?? '');
            $currency = strtoupper((string) ($item['currency'] ?? 'USD'));

            $rows[] = [
                'timestamp' => $at->getTimestamp(),
                'time'      => $allDay ? '' : $at->format('H:i'),
                'all_day'   => $allDay,
                'currency'  => $currency,
                'country'   => Countries::code($currency),
                'impact'    => (int) ($item['impact'] ?? 2),
                'title_en'  => $title,
                'title_fa'  => EventTranslator::translate($title),
                'previous'  => (string) ($item['previous'] ?? ''),
                'forecast'  => (string) ($item['forecast'] ?? ''),
                'actual'    => (string) ($item['actual'] ?? ''),
                'speech'    => CalendarProvider::isSpeech($title),
            ];
        }

        return $rows;
    }

    private static function load(string $file): array
    {
        $path = APP_FIXTURES . '/' . $file;
        if (!is_file($path)) {
            return [];
        }
        $data = json_decode((string) file_get_contents($path), true);

        return is_array($data) ? $data : [];
    }

