        ['1000SATS', 0.000312, -4.84, 6.1e7], ['BOME', 0.009312, 13.47, 3.6e8], ['PEOPLE', 0.08121, -21.64, 3.3e8],
    ];

    public static function futuresTickers(): array
    {
        $out = [];
        foreach (self::FUTURES as [$base, $price, $pct, $volume]) {
            $out[] = self::ticker($base . 'USDT', $price, $pct, $volume);
        }
        $out[] = self::ticker('DEADUSDT', 0.0421, 95.0, 5e8);
        $out[] = self::ticker('BTCUSDT_251226', 65890.0, 12.0, 4e8);
        $out[] = self::ticker('ETHUSDC', 3121.0, 30.0, 6e8);
        $out[] = self::ticker('TINYUSDT', 0.0021, 60.0, 2e5);
        $zero = self::ticker('ZEROUSDT', 0.12, -80.0, 9e8);
        $zero['count'] = 0;
        $out[] = $zero;

        return $out;
    }

    public static function futuresExchangeInfo(): array
    {
        $symbols = [];
        foreach (self::FUTURES as [$base]) {
            $symbols[] = self::contract($base . 'USDT', $base, 'USDT', 'PERPETUAL', 'TRADING');
        }
        $symbols[] = self::contract('DEADUSDT', 'DEAD', 'USDT', 'PERPETUAL', 'SETTLING');
        $symbols[] = self::contract('BTCUSDT_251226', 'BTC', 'USDT', 'CURRENT_QUARTER', 'TRADING');
        $symbols[] = self::contract('ETHUSDC', 'ETH', 'USDC', 'PERPETUAL', 'TRADING');
        $symbols[] = self::contract('TINYUSDT', 'TINY', 'USDT', 'PERPETUAL', 'TRADING');
        $symbols[] = self::contract('ZEROUSDT', 'ZERO', 'USDT', 'PERPETUAL', 'TRADING');

        return ['timezone' => 'UTC', 'symbols' => $symbols];
    }

    private static function ticker(string $pair, float $price, float $pct, float $quoteVolume): array
    {
        $open = $price / (1 + $pct / 100);

        return [
            'symbol'             => $pair,
            'priceChange'        => (string) round($price - $open, 8),
            'priceChangePercent' => number_format($pct, 3, '.', ''),
            'weightedAvgPrice'   => (string) round(($price + $open) / 2, 8),
            'lastPrice'          => (string) $price,
            'openPrice'          => (string) round($open, 8),
            'highPrice'          => (string) round(max($price, $open) * 1.021, 8),
            'lowPrice'           => (string) round(min($price, $open) * 0.978, 8),
            'volume'             => (string) round($quoteVolume / $price, 3),
            'quoteVolume'        => (string) $quoteVolume,
            'count'              => 184233,
        ];
    }

    private static function contract(string $pair, string $base, string $quote, string $type, string $status): array
    {
        return [
            'symbol'       => $pair,
            'pair'         => $base . $quote,
            'contractType' => $type,
            'status'       => $status,
            'baseAsset'    => $base,
            'quoteAsset'   => $quote,
        ];
    }

    public static function series(int $seed, int $points, float $changePct, float $end = 100.0): array
    {
        mt_srand($seed);
        $start = $end / (1 + $changePct / 100);
        $out = [];
        $wobble = 0.0;
        for ($i = 0; $i < $points; $i++) {
            $t = $i / max(1, $points - 1);
            $wobble = $wobble * 0.6 + mt_rand(-60, 60) / 10000;
            $out[] = round(($start + ($end - $start) * $t) * (1 + $wobble), 8);
        }
        $out[$points - 1] = $end;
        mt_srand();

        return $out;
    }

    public const BTC_MID = 64210.5;

    public static function btcDepth(string $market): array
    {
        $futures = $market === 'futures';
        mt_srand($futures ? 7001 : 7002);
        $levels = $futures ? 1000 : 5000;
        $tick = $futures ? 0.1 : 0.01;
        $meanGap = $futures ? 1.6 : 0.55;

        $walls = $futures
            ? ['bids' => [63800 => 44.0, 63500 => 78.0, 63150 => 36.0, 62900 => 31.0],
               'asks' => [64600 => 51.0, 65000 => 108.0, 65400 => 40.0, 65750 => 33.0]]
            : ['bids' => [63500 => 34.0, 62800 => 58.0, 62500 => 41.0, 63950 => 22.0],
               'asks' => [65000 => 69.0, 66000 => 88.0, 65400 => 21.0, 66400 => 37.0]];

        $book = ['lastUpdateId' => 4815162342, 'bids' => [], 'asks' => []];
        foreach (['bids' => -1, 'asks' => 1] as $side => $dir) {
            $price = self::BTC_MID + $dir * $tick * 5;
            $planted = $walls[$side];
            for ($i = 0; $i < $levels; $i++) {
                $price += $dir * max($tick, round((mt_rand(1, 200) / 100) * $meanGap / $tick) * $tick);
                $qty = (mt_rand(1, 100) <= 92 ? mt_rand(2, 180) / 1000 : mt_rand(200, 2600) / 1000) * ($futures ? 1.6 : 1.0);
                foreach ($planted as $wallPrice => $wallQty) {
                    $d = abs($price - $wallPrice);
                    if ($d < 40) {
                        $qty += $wallQty * (1 - $d / 40) / 12;
                    }
                }
                $book[$side][] = [number_format($price, 2, '.', ''), number_format($qty, 3, '.', '')];
            }
        }
        mt_srand();

        return $book;
    }

    public static function btcKlines(): array
    {
        $closes = self::series(9101, 48, 2.4, self::BTC_MID);
        mt_srand(9102);
        $out = [];
        $start = (int) (floor(time() / 3600) - 47) * 3600;
        $prev = $closes[0] * 0.998;
        foreach ($closes as $i => $close) {
            $open = $prev;
            $high = max($open, $close) * (1 + mt_rand(5, 45) / 10000);
            $low = min($open, $close) * (1 - mt_rand(5, 45) / 10000);
            $t = ($start + $i * 3600) * 1000;
            $out[] = [$t, (string) round($open, 2), (string) round($high, 2), (string) round($low, 2),
                (string) round($close, 2), '1843.221', $t + 3599999, '118300422.19', 51234, '921.1', '59111203.4', '0'];
            $prev = $close;
        }
        mt_srand();

        return $out;
    }
}
}

namespace Nikto\Data {
use Nikto\Core\Http;
use Nikto\Core\Log;
use Nikto\Core\Settings;

final class PriceProvider
{
    private const BINANCE = ['https://api.binance.com/api/v3', 'https://data-api.binance.vision/api/v3'];
    private const GECKO   = 'https://api.coingecko.com/api/v3';

    public static function fetch(array $symbols, bool $withSparkline = true): array
    {
        $symbols = array_values(array_unique(array_map('strtoupper', $symbols)));
        if ($symbols === []) {
            return [];
        }
        if (Mock::enabled()) {
            return Mock::prices($symbols);
        }

        $source = Settings::get('price_source');
        $order = match (true) {
            $source === 'binance'   => ['binance'],
            $source === 'coingecko' => ['coingecko'],
            CoinGeckoApi::enabled() => ['coingecko', 'binance', 'exchanges'],
            default                 => ['binance', 'coingecko', 'exchanges'],
        };

        $rows = [];
        foreach ($order as $provider) {
            $missing = array_values(array_diff($symbols, array_column($rows, 'symbol')));
            if ($missing === []) {
                break;
            }
            $rows = array_merge($rows, match ($provider) {
                'binance'   => self::fromBinance($missing, $withSparkline),
                'coingecko' => self::fromGecko($missing),
                default     => self::fromExchanges($missing, $withSparkline),
            });
        }
        usort($rows, static fn (array $a, array $b): int =>
            array_search($a['symbol'], $symbols, true) <=> array_search($b['symbol'], $symbols, true));
        if ($rows === []) {
            Log::error('Price fetch failed from every source', ['symbols' => $symbols]);
        }

        return $rows;
    }

    private static function fromBinance(array $symbols, bool $withSparkline): array
    {
        $pairs = array_map(static fn (string $s): string => self::pair($s), $symbols);
        $query = '["' . implode('","', $pairs) . '"]';

        $data = null;
        $base = '';
        foreach (self::BINANCE as $base) {
            $data = Http::getJson($base . '/ticker/24hr?symbols=' . rawurlencode($query), [], 0, 1);
            if (!is_array($data) && count($pairs) > 1 && Http::lastCode($base) === 400) {
                $data = [];
                foreach ($pairs as $pair) {
                    $one = Http::getJson($base . '/ticker/24hr?symbol=' . $pair, [], 15, 0);
                    if (is_array($one) && isset($one['symbol'])) {
                        $data[] = $one;
                    }
                }
            }
            if (is_array($data) && $data !== []) {
                break;
            }
        }

        if (!is_array($data) || $data === []) {
            return [];
        }
        $bySymbol = [];
        foreach ($data as $row) {
            if (isset($row['symbol'])) {
                $bySymbol[(string) $row['symbol']] = $row;
            }
        }

        $out = [];
        foreach ($symbols as $i => $symbol) {
            $row = $bySymbol[$pairs[$i]] ?? null;
            if ($row === null) {
                continue;
            }
            $out[] = self::row(
                $symbol,
                (float) ($row['lastPrice'] ?? 0),
                (float) ($row['priceChangePercent'] ?? 0),
                (float) ($row['priceChange'] ?? 0),
                (float) ($row['highPrice'] ?? 0),
                (float) ($row['lowPrice'] ?? 0),
                (float) ($row['quoteVolume'] ?? 0),
                $withSparkline ? self::sparkline($base, $pairs[$i]) : []
            );
        }

        return $out;
    }

    private static function fromExchanges(array $symbols, bool $withSparkline): array
    {
        $rows = [];
        foreach (Exchanges::SPOT as $exchange) {
            $missing = array_values(array_diff($symbols, array_column($rows, 'symbol')));
            if ($missing === []) {
                break;
            }
            $rows = array_merge($rows, self::fromExchange($exchange, $missing, $withSparkline));
        }

        return $rows;
    }

    private static function fromExchange(string $exchange, array $symbols, bool $withSparkline): array
    {
        $tickers = Exchanges::spotTickers($exchange, array_map(static fn (string $s): string => substr(self::pair($s), 0, -4), $symbols));
        $out = [];
        foreach ($symbols as $symbol) {
            $t = $tickers[self::pair($symbol)] ?? null;
            if ($t === null || (float) $t['lastPrice'] <= 0) {
                continue;
            }
            $spark = [];
            if ($withSparkline) {
                foreach (Exchanges::klines($exchange, 'spot', self::pair($symbol), 24) as $candle) {
                    $spark[] = (float) $candle[4];
                }
            }
            $out[] = self::row(
                $symbol,
                (float) $t['lastPrice'],
                (float) $t['priceChangePercent'],
                (float) $t['priceChange'],
                (float) $t['highPrice'],
                (float) $t['lowPrice'],
                (float) $t['quoteVolume'],
                $spark
            );
        }
        if ($out !== []) {
            Log::warn('Prices served by fallback exchange', ['exchange' => $exchange, 'symbols' => array_column($out, 'symbol')]);
        }

        return $out;
    }

    private static function sparkline(string $base, string $pair): array
    {
        $data = Http::getJson($base . '/klines?symbol=' . $pair . '&interval=1h&limit=24', [], 15, 1);
        if (!is_array($data)) {
            return [];
        }
        $out = [];
        foreach ($data as $candle) {
            if (isset($candle[4])) {
                $out[] = (float) $candle[4];
            }
        }
        return $out;
    }

    private static function fromGecko(array $symbols): array
    {
        $ids = [];
        foreach ($symbols as $s) {
            $id = Coins::geckoId($s);
            if ($id !== null) {
                $ids[$id] = $s;
            }
        }
        if ($ids === []) {
            return [];
        }
        $url = self::GECKO . '/coins/markets?vs_currency=usd&ids=' . implode(',', array_keys($ids))
            . '&order=market_cap_desc&sparkline=true&price_change_percentage=24h';
        $data = Http::getJson($url, CoinGeckoApi::headers());
        if (!is_array($data)) {
            return [];
        }

        $byId = [];
        foreach ($data as $row) {
            if (isset($row['id'])) {
                $byId[(string) $row['id']] = $row;
            }
        }

        $out = [];
        foreach ($ids as $id => $symbol) {
            $row = $byId[$id] ?? null;
            if ($row === null) {
                continue;
            }
            $spark = $row['sparkline_in_7d']['price'] ?? [];
            $spark = is_array($spark) ? array_slice(array_map('floatval', $spark), -24) : [];
            $out[] = self::row(
                $symbol,
                (float) ($row['current_price'] ?? 0),
                (float) ($row['price_change_percentage_24h'] ?? 0),
                (float) ($row['price_change_24h'] ?? 0),
                (float) ($row['high_24h'] ?? 0),
                (float) ($row['low_24h'] ?? 0),
                (float) ($row['total_volume'] ?? 0),
                $spark
            );
        }

        usort($out, static function (array $a, array $b) use ($symbols): int {
            return array_search($a['symbol'], $symbols, true) <=> array_search($b['symbol'], $symbols, true);
        });

        return $out;
    }

    public static function row(
        string $symbol,
        float $price,
        float $changePct,
        float $changeAbs,
        float $high = 0,
        float $low = 0,
        float $volume = 0,
        array $spark = []
    ): array {
        return [
            'symbol'     => strtoupper($symbol),
            'name'       => Coins::name($symbol),
            'name_fa'    => Coins::nameFa($symbol),
            'color'      => Coins::color($symbol),
            'price'      => $price,
            'change_pct' => $changePct,
            'change_abs' => $changeAbs,
            'high'       => $high,
            'low'        => $low,
            'volume'     => $volume,
            'spark'      => $spark,
        ];
    }

    private static function pair(string $symbol): string
    {
        $symbol = strtoupper($symbol);
        if ($symbol === 'USDT') {
            return 'USDCUSDT';
        }
        return $symbol . 'USDT';
    }

    public static function formatPrice(float $price): string
    {
        if ($price >= 1000) {
            return number_format($price, 0);
        }
        if ($price >= 100) {
            return self::trim(number_format($price, 2));
        }
        if ($price >= 1) {
            return self::trim(number_format($price, 3));
        }
        if ($price >= 0.01) {
            return self::trim(number_format($price, 4));
        }
        if ($price >= 0.0001) {
            return self::trim(number_format($price, 6));
        }
        return self::trim(sprintf('%.8f', $price));
    }

    public static function formatChange(float $value): string
    {
        $abs = abs($value);
        if ($abs >= 100000) {
            return number_format($value, 0);
        }
        if ($abs >= 1000) {
            return number_format($value, 2);
        }
        if ($abs >= 1) {
            return number_format($value, 2);
        }
        if ($abs >= 0.01) {
            return number_format($value, 4);
        }
        return rtrim(rtrim(sprintf('%.6f', $value), '0'), '.') ?: '0';
    }

    private static function trim(string $value): string
    {
        if (!str_contains($value, '.')) {
            return $value;
        }
        return rtrim(rtrim($value, '0'), '.');
    }

    public static function formatCompact(float $value): string
    {
        foreach ([[1e12, 'T'], [1e9, 'B'], [1e6, 'M'], [1e3, 'K']] as [$unit, $suffix]) {
            if ($value >= $unit) {
                return number_format($value / $unit, $value / $unit >= 100 ? 0 : 2) . $suffix;
            }
        }
        return number_format($value, 0);
    }
}
}

namespace Nikto\Jobs {
use Nikto\Core\Settings;
use Nikto\Data\CalendarProvider;
use Nikto\Render\CalendarCard;
use Nikto\Render\Card;
use Nikto\Render\Theme;
use Nikto\Text\Persian;

final class CalendarJob extends Job
{
    public const KEY = 'calendar';

    public function title(): string
    {
        return 'تقویم اقتصادی';
    }

    public function icon(): string
    {
        return '📅';
    }

    public function description(): string
    {
        return 'رویدادهای اقتصادی امروز با اهمیت، مقدار قبلی و پیش‌بینی';
    }

    public function defaultTheme(): string
    {
        return Theme::DEFAULT;
    }

    public function defaultOptions(): array
    {
        return [
            'headline'  => 'تقویم اقتصادی امروز',
            'day_shift' => 0,
        ];
    }

    public function defaultCaption(): string
    {
        return "📅 <b>تقویم اقتصادی امروز</b>\n\n{summary}\n\n🗓 {date}\n{link}";
    }

    public function fetch(): mixed
    {
        $shift = (int) $this->option('day_shift', 0);
        $day = Settings::now();
        if ($shift !== 0) {
            $day = $day->modify(sprintf('%+d day', $shift));
        }

        return CalendarProvider::forDay($day);
    }

    public function card(mixed $data): Card
    {
        $shift = (int) $this->option('day_shift', 0);
        $now = Settings::now();
        if ($shift !== 0) {
            $now = $now->modify(sprintf('%+d day', $shift));
        }

        return new CalendarCard((array) $data, $this->theme(), [
            'title' => (string) $this->option('headline', 'تقویم اقتصادی امروز'),
            'now'   => $now,
        ]);
    }

    public function summary(mixed $data): string
    {
        $rows = (array) $data;
        if ($rows === []) {
            return 'امروز رویداد مهمی در تقویم اقتصادی ثبت نشده است.';
        }

        $important = array_values(array_filter($rows, static fn ($r) => (int) $r['impact'] >= 3));
        usort($important, static fn ($a, $b) => $a['timestamp'] <=> $b['timestamp']);
        $important = array_slice($important, 0, 5);

        $lines = ['🔔 مهم‌ترین رویدادهای امروز:'];
        foreach ($important as $row) {
            $time = $row['all_day'] ? 'تعطیل' : (string) $row['time'];
            $title = (string) ($row['title_fa'] !== '' ? $row['title_fa'] : $row['title_en']);
            $lines[] = sprintf('• <b>%s</b> | %s — %s', $time, $row['currency'], $title);
        }
        $lines[] = '';
        $lines[] = sprintf('مجموع رویدادها: %d — زمان‌ها به وقت ایران', count($rows));

        $text = implode("\n", $lines);

        return Settings::get('digits_data') === 'fa' ? Persian::faDigits($text) : $text;
    }
}
}

namespace Nikto\Jobs {
use Nikto\Core\Db;
use Nikto\Core\Http;
use Nikto\Core\Log;
use Nikto\Core\Settings;
use Nikto\Telegram\Api;

final class Dispatcher
{
    private static ?Api $api = null;

    public static function setApi(?Api $api): void
    {
        self::$api = $api;
    }

    private static function api(): Api
    {
        return self::$api ??= new Api();
    }

    public static function run(string $jobKey, array $options = []): array
    {
        $job = Registry::refresh($jobKey);
        if ($job === null) {
            return ['ok' => false, 'message' => 'کار ناشناخته: ' . $jobKey, 'sent' => 0, 'failed' => 0];
        }

        $started = microtime(true);
        Http::resetFailures();

        try {
            $data = $job->fetch();
        } catch (\Throwable $e) {
            Log::error('Job fetch threw', ['job' => $jobKey, 'error' => $e->getMessage()]);
            return self::fail($jobKey, $options, 'خطا در دریافت داده: ' . $e->getMessage());
        }

        if ($data === null || $data === []) {
            $empty = $jobKey === CalendarJob::KEY && $data === [];
            if (!$empty) {
                return self::fail($jobKey, $options, self::noDataMessage(), true);
            }
        }

        try {
            $path = $job->card($data)->save();
            $caption = $job->renderCaption($data);
        } catch (\Throwable $e) {
            Log::error('Card render failed', ['job' => $jobKey, 'error' => $e->getMessage()]);
            return self::fail($jobKey, $options, 'خطا در ساخت تصویر: ' . $e->getMessage());
        }

        $targets = $options['chat_ids'] ?? array_map(
            static fn (array $ch) => $ch['chat_id'],
            $job->channels()
        );

        if ($targets === []) {
            return [
                'ok'      => false,
                'message' => 'هیچ کانال مقصدی برای این کار انتخاب نشده است.',
                'sent'    => 0,
                'failed'  => 0,
                'path'    => $path,
            ];
        }

        $api = self::api();
        $asDocument = Settings::get('send_mode') === 'document';
        $sent = 0;
        $failed = 0;
        $errors = [];

        $silent = (bool) ($options['silent'] ?? false);

        foreach ($targets as $chatId) {
            $api->sendChatAction($chatId, $asDocument ? 'upload_document' : 'upload_photo');
            $res = self::deliver($api, $chatId, $path, $caption, $asDocument, $silent);

            if ($res['ok'] ?? false) {
                $sent++;
            } else {
                $failed++;
                $errors[] = $chatId . ': ' . ($res['description'] ?? 'نامشخص');
            }
        }

        $took = round(microtime(true) - $started, 2);
        $message = sprintf('ارسال شد به %d کانال (%s ثانیه)', $sent, $took);
        if ($failed > 0) {
            $message .= sprintf(' — %d خطا: %s', $failed, implode(' | ', array_slice($errors, 0, 3)));
        }

        self::record($jobKey, $options['slot'] ?? null, $failed === 0 ? 'ok' : 'partial', $message);
        Log::info('Job dispatched', ['job' => $jobKey, 'sent' => $sent, 'failed' => $failed, 'took' => $took]);
        self::cleanup();

        return [
            'ok'      => $sent > 0,
            'message' => $message,
            'sent'    => $sent,
            'failed'  => $failed,
            'path'    => $path,
            'retry'   => $sent === 0 && $failed > 0,
        ];
    }

    public static function build(string $jobKey): array
    {
        $job = Registry::refresh($jobKey);
        if ($job === null) {
            return ['ok' => false, 'message' => 'کار ناشناخته'];
        }
        try {
            Http::resetFailures();
            $data = $job->fetch();
            if ($data === null) {
                return ['ok' => false, 'message' => self::noDataMessage()];
            }
            $path = $job->card($data)->save();

            return ['ok' => true, 'path' => $path, 'caption' => $job->renderCaption($data), 'message' => 'ساخته شد'];
        } catch (\Throwable $e) {
            Log::error('Preview failed', ['job' => $jobKey, 'error' => $e->getMessage()]);

            return ['ok' => false, 'message' => 'خطا: ' . $e->getMessage()];
        }
    }

    private static function noDataMessage(): string
    {
        $message = 'داده‌ای از سرویس دریافت نشد (اینترنت یا API).';
        $reasons = Http::explainFailures();
        if ($reasons !== '') {
            $message .= "\nعلت:\n" . $reasons;
        }
        if (Http::allRegionBlocked()) {
            $message .= "\n\nهمه‌ی منابع، کشورِ سرورِ ربات را مسدود کرده‌اند. راهِ قطعی: بالای فایل nikto-bot.php مقدارِ "
                . "data_proxy را یک پراکسیِ خارج از این کشور بگذارید (مثلاً socks5h://user:pass@1.2.3.4:1080) "
                . 'یا ربات را روی هاستی در کشورِ دیگر ببرید.';
        }

        return $message;
    }

    private static function deliver(
        Api $api,
        int|string $chatId,
        string $path,
        string $caption,
        bool $asDocument,
        bool $silent
    ): array {
        $extra = ['disable_notification' => $silent];

        return $asDocument
            ? $api->sendDocument($chatId, $path, $caption, $extra)
            : $api->sendPhoto($chatId, $path, $caption, $extra);
    }

    private static function fail(string $jobKey, array $options, string $message, bool $retry = false): array
    {
        self::record($jobKey, $options['slot'] ?? null, 'error', $message);
        Log::error('Job failed', ['job' => $jobKey, 'message' => $message]);

        return ['ok' => false, 'message' => $message, 'sent' => 0, 'failed' => 0, 'retry' => $retry];
    }

    private static function record(string $jobKey, ?string $slot, string $status, string $detail): void
    {
        $slot ??= 'manual-' . Settings::now()->format('Y-m-d H:i:s');
        Db::exec(
            'INSERT INTO runs(job_key, slot, status, detail, created_at) VALUES(:j, :s, :st, :d, :t)
             ON CONFLICT(job_key, slot) DO UPDATE SET status = excluded.status, detail = excluded.detail',
            [':j' => $jobKey, ':s' => $slot, ':st' => $status, ':d' => mb_substr($detail, 0, 500), ':t' => time()]
        );
    }

    private static function cleanup(int $keepHours = 48): void
    {
        $dir = APP_STORAGE . '/cards';
        foreach (glob($dir . '/*.png') ?: [] as $file) {
            if (filemtime($file) < time() - $keepHours * 3600) {
                @unlink($file);
            }
        }
        Db::exec('DELETE FROM runs WHERE created_at < :t', [':t' => time() - 30 * 86400]);
    }
}
}

namespace Nikto\Jobs {
use Nikto\Core\Settings;
use Nikto\Data\FearGreedProvider;
use Nikto\Render\Card;
use Nikto\Render\Theme;
use Nikto\Render\FearGreedCard;
use Nikto\Text\Persian;

final class FearGreedJob extends Job
{
    public const KEY = 'feargreed';

    public function title(): string
    {
        return 'شاخص ترس و طمع';
    }

    public function icon(): string
    {
        return '😨';
    }

    public function description(): string
    {
        return 'سنجه‌ی شاخص ترس و طمع همراه با مقادیر دیروز، هفته و ماه گذشته';
    }

    public function defaultTheme(): string
    {
        return Theme::DEFAULT;
    }

    public function defaultCaption(): string
    {
        return "😨 <b>شاخص ترس و طمع بازار</b>\n\n{summary}\n\n🗓 {date} — ⏰ {time}\n{link}";
    }

    public function fetch(): mixed
    {
        return FearGreedProvider::fetch();
    }

    public function card(mixed $data): Card
    {
        return new FearGreedCard((array) $data, $this->theme());
    }

    public function summary(mixed $data): string
    {
        $data = (array) $data;
        $zone = $data['zone'] ?? ['fa' => '', 'en' => ''];
        $emoji = match (true) {
            $data['value'] <= 24 => '🟥',
            $data['value'] <= 44 => '🟧',
            $data['value'] <= 55 => '🟨',
            $data['value'] <= 75 => '🟩',
            default              => '🟢',
        };

        $lines = [sprintf('%s شاخص امروز: <b>%d</b> — %s', $emoji, $data['value'], $zone['fa'])];
        $labels = ['yesterday' => 'دیروز', 'week' => '۷ روز پیش', 'month' => '۱ ماه پیش'];
        foreach ($labels as $key => $label) {
            if (isset($data['history'][$key])) {
                $lines[] = sprintf(
                    '• %s: %d (%s)',
                    $label,
                    $data['history'][$key]['value'],
                    $data['history'][$key]['zone']['fa']
                );
            }
        }
        $text = implode("\n", $lines);

        return Settings::get('digits_data') === 'fa' ? Persian::faDigits($text) : $text;
    }
}
}

namespace Nikto\Jobs {
use Nikto\Core\Db;
use Nikto\Core\Settings;
use Nikto\Render\Card;
use Nikto\Render\Theme;

abstract class Job
{
    public const KEY = '';

    protected array $row;

    public function __construct()
    {
        $this->row = $this->loadRow();
    }

    abstract public function title(): string;

    abstract public function icon(): string;

    abstract public function description(): string;

    abstract public function fetch(): mixed;

    abstract public function card(mixed $data): Card;

    abstract public function summary(mixed $data): string;

    public function defaultOptions(): array
    {
        return [];
    }

    public function defaultTheme(): string
    {
        return Theme::DEFAULT;
    }

    public function defaultCaption(): string
    {
        return "{summary}\n\n🗓 {date} — ⏰ {time}\n{link}";
    }

    public function key(): string
    {
        return static::KEY;
    }

    public function enabled(): bool
    {
        return (int) $this->row['enabled'] === 1;
    }

    public function theme(): string
    {
        $theme = (string) $this->row['theme'];

        return isset(Theme::PALETTES[$theme]) ? $theme : Theme::DEFAULT;
    }

    public function caption(): string
    {
        return (string) $this->row['caption'];
    }

    public function options(): array
    {
        $opts = json_decode((string) $this->row['options'], true);

        return array_replace($this->defaultOptions(), is_array($opts) ? $opts : []);
    }

    public function option(string $key, mixed $default = null): mixed
    {
        return $this->options()[$key] ?? $default;
    }

    public function setOption(string $key, mixed $value): void
    {
        $opts = $this->options();
        $opts[$key] = $value;
        $this->update(['options' => json_encode($opts, JSON_UNESCAPED_UNICODE)]);
    }

    public function setEnabled(bool $on): void
    {
        $this->update(['enabled' => $on ? 1 : 0]);
    }

    public function setTheme(string $theme): void
    {
        $this->update(['theme' => $theme]);
    }

    public function setCaption(string $caption): void
    {
        $this->update(['caption' => $caption]);
    }

    protected function update(array $fields): void
    {
        $sets = [];
        $params = [':k' => static::KEY, ':t' => time()];
        foreach ($fields as $name => $value) {
            $sets[] = "$name = :$name";
            $params[':' . $name] = $value;
        }
        $sets[] = 'updated_at = :t';
        Db::exec('UPDATE jobs SET ' . implode(', ', $sets) . ' WHERE key = :k', $params);
        $this->row = $this->loadRow();
    }

    public function channels(): array
    {
        return Db::all(
            'SELECT c.* FROM channels c
             INNER JOIN job_channels jc ON jc.channel_id = c.id
             WHERE jc.job_key = :k AND c.active = 1
             ORDER BY c.id',
            [':k' => static::KEY]
        );
    }

    public function hasChannel(int $channelId): bool
    {
        return Db::one(
            'SELECT 1 FROM job_channels WHERE job_key = :k AND channel_id = :c',
            [':k' => static::KEY, ':c' => $channelId]
        ) !== null;
    }

    public function toggleChannel(int $channelId): bool
    {
        if ($this->hasChannel($channelId)) {
            Db::exec('DELETE FROM job_channels WHERE job_key = :k AND channel_id = :c', [':k' => static::KEY, ':c' => $channelId]);
            return false;
        }
        Db::exec('INSERT INTO job_channels(job_key, channel_id) VALUES(:k, :c)', [':k' => static::KEY, ':c' => $channelId]);

        return true;
    }

    public function schedules(): array
    {
        return Db::all('SELECT * FROM schedules WHERE job_key = :k ORDER BY at_time', [':k' => static::KEY]);
    }

    public function renderCaption(mixed $data): string
    {
        $now = Settings::now();

        $replace = [
            '{summary}' => $this->summary($data),
            '{date}'    => \Nikto\Core\Jalali::format($now, 'l j F Y'),
            '{time}'    => $now->format('H:i'),
            '{brand}'   => Settings::get('brand'),
            '{link}'    => Settings::get('brand_link'),
        ];
        if (Settings::get('digits') === 'fa') {
            $replace['{date}'] = \Nikto\Text\Persian::faDigits($replace['{date}']);
            $replace['{time}'] = \Nikto\Text\Persian::faDigits($replace['{time}']);
        }

        $caption = strtr($this->caption(), $replace);
        $caption = preg_replace("/\n{3,}/", "\n\n", $caption) ?? $caption;

        return trim($caption);
    }

    private function loadRow(): array
    {
        $row = Db::one('SELECT * FROM jobs WHERE key = :k', [':k' => static::KEY]);
        if ($row === null) {
            Db::exec(
                'INSERT INTO jobs(key, title, enabled, theme, caption, options, updated_at)
                 VALUES(:k, :t, 0, :th, :c, :o, :u)',
                [
                    ':k'  => static::KEY,
                    ':t'  => $this->title(),
                    ':th' => $this->defaultTheme(),
                    ':c'  => $this->defaultCaption(),
                    ':o'  => json_encode($this->defaultOptions(), JSON_UNESCAPED_UNICODE),
                    ':u'  => time(),
                ]
            );
            $row = Db::one('SELECT * FROM jobs WHERE key = :k', [':k' => static::KEY]);
        }

        return $row ?? [];
    }
}
}

namespace Nikto\Jobs {
use Nikto\Core\Settings;
use Nikto\Data\LiquidityProvider;
use Nikto\Render\Card;
use Nikto\Render\LiquidityCard;
use Nikto\Text\Persian;

final class LiquidityJob extends Job
{
    public const KEY = 'liquidity';

    public const LEVELS = [3, 4, 5, 6];

    public function title(): string
    {
        return 'کارت نقدینگی بیت‌کوین';
    }

    public function icon(): string
    {
        return '💧';
    }

    public function description(): string
    {
        return 'دیوارهای پرحجم خرید و فروش بیت‌کوین از دفتر سفارش صرافی‌ها (رایگان) روی نمودار ۴۸ ساعته';
    }

    public function defaultOptions(): array
    {
        return [
            'headline' => 'نقشه‌ی نقدینگی بیت‌کوین',
            'levels'   => 5,
        ];
    }

    public function defaultCaption(): string
    {
        return "💧 <b>نقشه‌ی نقدینگی بیت‌کوین</b>\n\n{summary}\n\n🗓 {date} — ⏰ {time}\n{link}";
    }

    public function levels(): int
    {
        $n = (int) $this->option('levels', 5);

        return in_array($n, self::LEVELS, true) ? $n : 5;
    }

    public function fetch(): mixed
    {
        return LiquidityProvider::btc($this->levels());
    }

    public function card(mixed $data): Card
    {
        return new LiquidityCard((array) $data, $this->theme(), [
            'title' => (string) $this->option('headline', 'نقشه‌ی نقدینگی بیت‌کوین'),
        ]);
    }

    public function summary(mixed $data): string
    {
        $data = (array) $data;
        $levels = static function (array $walls): string {
            $out = [];
            foreach (array_slice($walls, 0, 3) as $w) {
                $out[] = sprintf('%s (%s)', number_format((float) $w['price'], 0), LiquidityProvider::formatBtc((float) $w['qty']));
            }

            return $out === [] ? '—' : implode(' · ', $out);
        };

        $share = (float) ($data['imbalance'] ?? 0.5) * 100;
        $lines = [
            '💰 قیمت: <b>$' . number_format((float) ($data['price'] ?? 0), 1) . '</b>',
            '🟥 مقاومت‌ها: ' . $levels((array) ($data['ask_walls'] ?? [])),
            '🟩 حمایت‌ها: ' . $levels((array) ($data['bid_walls'] ?? [])),
            sprintf('⚖️ توازن: خرید %s%% / فروش %s%%', number_format($share, 1), number_format(100 - $share, 1)),
        ];
        $text = implode("\n", $lines);

        return Settings::get('digits_data') === 'fa' ? Persian::faDigits($text) : $text;
    }
}
}

namespace Nikto\Jobs {
use Nikto\Core\Settings;
use Nikto\Data\CoinGlass;
use Nikto\Data\Exchanges;
use Nikto\Data\FuturesProvider;
use Nikto\Render\Card;
use Nikto\Render\MoversCard;
use Nikto\Text\Persian;

final class MoversJob extends Job
{
    public const KEY = 'movers';

    public const COUNTS = [3, 4, 5, 6];

    public const VOLUMES = [1_000_000, 5_000_000, 20_000_000, 50_000_000];

    public function title(): string
    {
        return 'کارت برترین‌های فیوچرز';
    }

    public function icon(): string
    {
        return '🚀';
    }

    public function description(): string
    {
        return 'بیشترین رشد و بیشترین افت ۲۴ ساعته‌ی قراردادهای فیوچرز بایننس';
    }

    public function defaultOptions(): array
    {
        return [
            'headline'   => 'برترین‌های فیوچرز بایننس',
            'count'      => 5,
            'min_volume' => 5_000_000,
        ];
    }

    public function defaultCaption(): string
    {
        return "🚀 <b>برترین‌های فیوچرز بایننس در ۲۴ ساعت گذشته</b>\n\n{summary}\n\n🗓 {date} — ⏰ {time}\n{link}";
    }

    public function count(): int
    {
        $n = (int) $this->option('count', 5);

        return in_array($n, self::COUNTS, true) ? $n : 5;
    }

    public function minVolume(): float
    {
        return (float) $this->option('min_volume', 5_000_000);
    }

    public function fetch(): mixed
    {
        return FuturesProvider::movers($this->count(), $this->minVolume(), false);
    }

    public function card(mixed $data): Card
    {
        return new MoversCard((array) $data, $this->theme(), [
            'title' => $this->withSource((string) $this->option('headline', 'برترین‌های فیوچرز بایننس'), $data),
        ]);
    }

    public function renderCaption(mixed $data): string
    {
        return $this->withSource(parent::renderCaption($data), $data);
    }

    private function withSource(string $text, mixed $data): string
    {
        $exchange = (string) (((array) $data)['exchange'] ?? 'Binance');
        $name = $exchange === 'CoinGlass' ? CoinGlass::NAME_FA : (Exchanges::NAMES_FA[$exchange] ?? $exchange);
        if ($exchange === 'Binance') {
            return $text;
        }

        return str_replace('فیوچرز بایننس', 'فیوچرز ' . $name, $text);
    }

    public function summary(mixed $data): string
    {
        $data = (array) $data;
        $lines = ['🟢 <b>بیشترین رشد</b>'];
        foreach ((array) ($data['gainers'] ?? []) as $i => $row) {
            $lines[] = $this->line($i + 1, $row);
        }
        $lines[] = '';
        $lines[] = '🔴 <b>بیشترین افت</b>';
        foreach ((array) ($data['losers'] ?? []) as $i => $row) {
            $lines[] = $this->line($i + 1, $row);
        }

        $b = (array) ($data['breadth'] ?? []);
        if (isset($b['total'])) {
            $lines[] = '';
            $lines[] = sprintf(
                '📊 %s صعودی · %s نزولی از %s قرارداد',
                Persian::faDigits((string) (int) $b['up']),
                Persian::faDigits((string) (int) $b['down']),
                Persian::faDigits((string) (int) $b['total'])
            );
        }

        return implode("\n", $lines);
    }

    private function line(int $rank, array $row): string
    {
        $pct = (float) $row['change_pct'];
        $text = sprintf('%d. <b>%s</b> %s%s%%', $rank, htmlspecialchars((string) $row['symbol']), $pct > 0 ? '+' : '', number_format($pct, 2));

        return Settings::get('digits_data') === 'fa' ? Persian::faDigits($text) : $text;
    }
}
}

