            'title' => (string) $this->option('headline', 'نوسان ۲۴ ساعته بازار'),
        ]);
    }

    public function summary(mixed $data): string
    {
        $lines = [];
        foreach ((array) $data as $coin) {
            $pct = (float) $coin['change_pct'];
            $icon = $pct > 0.005 ? '🟢' : ($pct < -0.005 ? '🔴' : '⚪️');
            $sign = $pct > 0 ? '+' : '';
            $lines[] = sprintf(
                '%s <b>%s</b> — $%s (%s%s%%)',
                $icon,
                $coin['symbol'],
                PriceProvider::formatPrice((float) $coin['price']),
                $sign,
                number_format($pct, 2)
            );
        }
        $text = implode("\n", $lines);

        return Settings::get('digits_data') === 'fa' ? Persian::faDigits($text) : $text;
    }
}
}

namespace Nikto\Jobs {
final class Registry
{
    private const CLASSES = [
        PricesJob::KEY    => PricesJob::class,
        FearGreedJob::KEY => FearGreedJob::class,
        CalendarJob::KEY  => CalendarJob::class,
        MoversJob::KEY    => MoversJob::class,
        LiquidityJob::KEY => LiquidityJob::class,
    ];

    private static array $instances = [];

    public static function get(string $key): ?Job
    {
        if (!isset(self::CLASSES[$key])) {
            return null;
        }
        if (!isset(self::$instances[$key])) {
            $class = self::CLASSES[$key];
            self::$instances[$key] = new $class();
        }

        return self::$instances[$key];
    }

    public static function all(): array
    {
        $out = [];
        foreach (array_keys(self::CLASSES) as $key) {
            $job = self::get($key);
            if ($job !== null) {
                $out[$key] = $job;
            }
        }

        return $out;
    }

    public static function keys(): array
    {
        return array_keys(self::CLASSES);
    }

    public static function refresh(string $key): ?Job
    {
        unset(self::$instances[$key]);

        return self::get($key);
    }
}
}

namespace Nikto\Jobs {
use DateTimeImmutable;
use Nikto\Core\Db;
use Nikto\Core\Log;
use Nikto\Core\Settings;

final class Scheduler
{
    public const MAX_ATTEMPTS = 3;

    public static function tick(?DateTimeImmutable $now = null): array
    {
        $now ??= Settings::now();
        $catchup = max(0, Settings::int('catchup_minutes', 10));
        $results = [];

        foreach (self::due($now, $catchup) as $due) {
            $attempt = self::claim($due['job_key'], $due['slot']);
            if ($attempt === 0) {
                continue;
            }
            Log::info('Scheduler firing job', ['job' => $due['job_key'], 'slot' => $due['slot'], 'attempt' => $attempt]);
            $result = Dispatcher::run($due['job_key'], ['slot' => $due['slot']]);

            if (($result['retry'] ?? false) && (int) ($result['sent'] ?? 0) === 0 && $attempt < self::MAX_ATTEMPTS) {
                self::release($due['job_key'], $due['slot'], $attempt);
                Log::warn('Job will retry', ['job' => $due['job_key'], 'slot' => $due['slot'], 'attempt' => $attempt]);
            }
            $results[] = ['job' => $due['job_key'], 'slot' => $due['slot'], 'result' => $result];
        }

        return $results;
    }

    public static function due(DateTimeImmutable $now, int $catchupMinutes = 10): array
    {
        $out = [];
        $rows = Db::all('SELECT * FROM schedules WHERE enabled = 1');

        foreach ($rows as $row) {
            $jobKey = (string) $row['job_key'];
            $job = Registry::get($jobKey);
            if ($job === null || !$job->enabled()) {
                continue;
            }
            $atTime = (string) $row['at_time'];
            if (!preg_match('/^([01]\d|2[0-3]):([0-5]\d)$/', $atTime, $m)) {
                continue;
            }

            foreach ([$now, $now->modify('-1 day')] as $day) {
                if (!self::matchesDay((string) $row['days'], $day)) {
                    continue;
                }
                $slotTime = $day->setTime((int) $m[1], (int) $m[2], 0);
                $diff = ($now->getTimestamp() - $slotTime->getTimestamp()) / 60;
                if ($diff < 0 || $diff > $catchupMinutes) {
                    continue;
                }
                $out[] = [
                    'job_key' => $jobKey,
                    'slot'    => $slotTime->format('Y-m-d H:i'),
                    'at_time' => $atTime,
                ];
            }
        }

        return $out;
    }

    private static function claim(string $jobKey, string $slot): int
    {
        $affected = Db::exec(
            'INSERT OR IGNORE INTO runs(job_key, slot, status, detail, created_at)
             VALUES(:j, :s, :st, :d, :t)',
            [':j' => $jobKey, ':s' => $slot, ':st' => 'running', ':d' => '', ':t' => time()]
        );
        if ($affected > 0) {
            return 1;
        }

        $row = Db::one('SELECT status FROM runs WHERE job_key = :j AND slot = :s', [':j' => $jobKey, ':s' => $slot]);
        $status = (string) ($row['status'] ?? '');
        if (!preg_match('/^retry:(\d+)$/', $status, $m)) {
            return 0;
        }
        $taken = Db::exec(
            "UPDATE runs SET status = 'running' WHERE job_key = :j AND slot = :s AND status = :old",
            [':j' => $jobKey, ':s' => $slot, ':old' => $status]
        );

        return $taken > 0 ? (int) $m[1] + 1 : 0;
    }

    private static function release(string $jobKey, string $slot, int $attempt): void
    {
        Db::exec(
            'UPDATE runs SET status = :st WHERE job_key = :j AND slot = :s',
            [':st' => 'retry:' . $attempt, ':j' => $jobKey, ':s' => $slot]
        );
    }

    public static function matchesDay(string $days, DateTimeImmutable $now): bool
    {
        $days = trim($days);
        if ($days === '' || $days === '*') {
            return true;
        }
        $today = (int) $now->format('N');
        $list = array_map('intval', array_filter(explode(',', $days), 'is_numeric'));

        return in_array($today, $list, true);
    }

    public static function nextRun(string $jobKey, ?DateTimeImmutable $now = null): ?DateTimeImmutable
    {
        $now ??= Settings::now();
        $rows = Db::all('SELECT * FROM schedules WHERE job_key = :k AND enabled = 1', [':k' => $jobKey]);
        $best = null;

        foreach ($rows as $row) {
            if (!preg_match('/^([01]\d|2[0-3]):([0-5]\d)$/', (string) $row['at_time'], $m)) {
                continue;
            }
            for ($dayOffset = 0; $dayOffset <= 7; $dayOffset++) {
                $candidate = $now->modify(sprintf('+%d day', $dayOffset))->setTime((int) $m[1], (int) $m[2], 0);
                if ($candidate <= $now) {
                    continue;
                }
                if (!self::matchesDay((string) $row['days'], $candidate)) {
                    continue;
                }
                if ($best === null || $candidate < $best) {
                    $best = $candidate;
                }
                break;
            }
        }

        return $best;
    }
}
}

namespace Nikto\Render {
use Nikto\Data\Countries;

final class CalendarCard extends Card
{
    private const ROW_H     = 46.0;
    private const HEAD_H    = 32.0;
    private const MAX_ROWS  = 18;
    private const TABLE_PAD = 10.0;

    private array $rows;
    private string $title;

    public function __construct(array $rows, ?string $theme = null, array $options = [])
    {
        parent::__construct($theme, $options);
        $this->rows = array_values($rows);
        $this->title = (string) ($options['title'] ?? 'تقویم اقتصادی امروز');
    }

    public function render(): Canvas
    {
        $rows = array_slice($this->rows, 0, self::MAX_ROWS);
        $extra = count($this->rows) - count($rows);

        $tableH = self::TABLE_PAD * 2 + self::HEAD_H + max(1, count($rows)) * self::ROW_H;
        $noteH = $extra > 0 ? 30.0 : 0.0;
        $height = (int) round(84 + Frame::HEADER_H + $tableH + $noteH);

        $c = new Canvas(1200, $height, $this->quality);
        $c->setOutputScale($this->outputScale);
        $t = $this->theme;

        $rect = Frame::draw($c, $t, ['footer' => $this->footer]);
        $top = Frame::header(
            $c,
            $t,
            $rect,
            $this->title,
            $this->dateLine(),
            $this->tnum((string) count($this->rows)) . ' رویداد · به وقت ایران'
        );

        Frame::panel($c, $t, $rect['x'], $top, $rect['w'], $tableH, 18);

        if ($rows === []) {
            $c->text(
                'امروز رویداد مهمی در تقویم اقتصادی ثبت نشده است',
                $rect['x'] + $rect['w'] / 2,
                $top + $tableH / 2,
                13,
                $t->c('ink_dim'),
                Canvas::W_SEMIBOLD,
                'center',
                1.0,
                'ink'
            );

            return $c;
        }

        $cols = $this->columns($rect['x'], $rect['w']);
        $y = $this->headRow($c, $t, $rect['x'] + self::TABLE_PAD, $top + self::TABLE_PAD, $rect['w'] - self::TABLE_PAD * 2, $cols);

        foreach ($rows as $i => $row) {
            if ($i > 0) {
                $c->rect($rect['x'] + self::TABLE_PAD, $y, $rect['w'] - self::TABLE_PAD * 2, 1, $t->c('line'), 0.06);
            }
            $this->row($c, $t, $row, $rect['x'] + self::TABLE_PAD, $y, $rect['w'] - self::TABLE_PAD * 2, $cols);
            $y += self::ROW_H;
        }

        if ($extra > 0) {
            $c->text(
                '+ ' . $this->tnum((string) $extra) . ' رویداد دیگر',
                $rect['x'] + $rect['w'],
                $top + $tableH + 16,
                10.5,
                $t->c('ink_faint'),
                Canvas::W_MEDIUM,
                'right',
                1.0,
                'middle'
            );
        }

        return $c;
    }

    private function columns(float $x, float $w): array
    {
        $right = $x + $w;

        return [
            'time'     => $right - 44,
            'flag'     => $right - 102,
            'currency' => $right - 120,
            'impact'   => $right - 176,
            'title'    => $right - 218,
            'forecast' => $x + 142,
            'previous' => $x + 52,
            'head_cur' => $right - 124,
        ];
    }

    private function headRow(Canvas $c, Theme $t, float $x, float $y, float $w, array $cols): float
    {
        $mid = $y + self::HEAD_H / 2;
        $labels = [
            ['زمان', $cols['time'], 'center'],
            ['ارز', $cols['head_cur'], 'center'],
            ['اهمیت', $cols['impact'], 'center'],
            ['رویداد', $cols['title'], 'right'],
            ['پیش‌بینی', $cols['forecast'], 'center'],
            ['قبلی', $cols['previous'], 'center'],
        ];

        foreach ($labels as [$text, $lx, $align]) {
            $c->text($text, $lx, $mid, 10, $t->c('ink_faint'), Canvas::W_MEDIUM, $align, 1.0, 'middle');
        }

        $c->rect($x, $y + self::HEAD_H, $w, 1, $t->c('line'), 0.10);

        return $y + self::HEAD_H;
    }

    private function row(Canvas $c, Theme $t, array $row, float $x, float $y, float $w, array $cols): void
    {
        $impact = (int) $row['impact'];
        $isHoliday = $impact === 0 || (bool) $row['all_day'];
        $mid = $y + self::ROW_H / 2;

        $time = (string) $row['time'];
        if ($time !== '') {
            $c->text($this->dnum($time), $cols['time'], $mid, 13, $t->c('ink'), Canvas::W_NUM_BOLD, 'center', 1.0, 'num');
        } else {
            $c->text('تعطیل', $cols['time'], $mid, 10.5, $t->c('ink_faint'), Canvas::W_SEMIBOLD, 'center', 1.0, 'middle');
        }

        Flags::draw($c, Countries::code((string) $row['currency']), $cols['flag'] - 11, $mid - 7.5, 22, 15);
        $c->text((string) $row['currency'], $cols['currency'], $mid, 11, $t->c('ink_dim'), Canvas::W_NUM_BOLD, 'right', 1.0, 'num');

        if (!$isHoliday) {
            $this->impactDots($c, $t, $cols['impact'], $mid, $impact);
        }

        $forecast = (string) ($row['forecast'] ?? '');
        $previous = (string) ($row['previous'] ?? '');
        $this->stat($c, $cols['forecast'], $mid, 88, $forecast, $forecast === '' ? $t->c('ink_faint') : $t->c('ink'), Canvas::W_NUM_BOLD);
        $this->stat($c, $cols['previous'], $mid, 84, $previous, $t->c('ink_faint'), Canvas::W_NUM);

        $titleLeft = $cols['forecast'] + 56;
        $text = (string) ($row['title_fa'] !== '' ? $row['title_fa'] : $row['title_en']);
        $c->textFit(
            $text,
            $cols['title'],
            $mid,
            max(160.0, $cols['title'] - $titleLeft),
            12.5,
            $isHoliday ? $t->c('ink_faint') : $t->c('ink'),
            Canvas::W_MEDIUM,
            'right',
            9,
            1.0,
            'ink'
        );
    }

    private function stat(Canvas $c, float $cx, float $mid, float $w, string $value, string $color, string $weight): void
    {
        $c->textFit($value === '' ? '–' : $this->dnum($value), $cx, $mid, $w, 12, $color, $weight, 'center', 8, 1.0, 'num');
    }

    private function impactDots(Canvas $c, Theme $t, float $cx, float $cy, int $impact): void
    {
        $filled = $impact >= 3 ? $t->c('down') : $t->c('ink');
        for ($i = 0; $i < 3; $i++) {
            $c->circle($cx + ($i - 1) * 9, $cy, 3, $i < $impact ? $filled : $t->c('line_soft'));
        }
    }
}
}

namespace Nikto\Render {
use GdImage;
use Nikto\Text\Persian;

final class Canvas
{
    public const W_REGULAR  = 'Regular';
    public const W_MEDIUM   = 'Medium';
    public const W_SEMIBOLD = 'SemiBold';
    public const W_BOLD     = 'Bold';
    public const W_EXTRA    = 'ExtraBold';
    public const W_BLACK    = 'Black';

    public const W_NUM      = 'Num';
    public const W_NUM_BOLD = 'NumBold';

    private GdImage $im;
    private int $scale;
    private int $width;
    private int $height;
    private float $outputScale = 1.0;

    public static bool $trace = false;
    public static array $traceBoxes = [];
    public static array $traceShapes = [];

    public function __construct(int $width, int $height, int $scale = 2, ?string $background = null)
    {
        $this->width  = $width;
        $this->height = $height;
        $this->scale  = max(1, min(4, $scale));

        $im = imagecreatetruecolor($width * $this->scale, $height * $this->scale);
        imagealphablending($im, false);
        imagesavealpha($im, true);
        imagefilledrectangle(
            $im,
            0,
            0,
            imagesx($im),
            imagesy($im),
            imagecolorallocatealpha($im, 0, 0, 0, 127)
        );
        imagealphablending($im, true);
        $this->im = $im;

        if ($background !== null) {
            $this->fill($background);
        }
    }

    public static function fromFile(string $path, int $scale = 1): self
    {
        $src = @imagecreatefromstring((string) file_get_contents($path));
        if (!$src) {
            throw new \RuntimeException('Unable to read image: ' . $path);
        }
        $canvas = new self((int) (imagesx($src) / $scale), (int) (imagesy($src) / $scale), $scale);
        imagecopy($canvas->im, $src, 0, 0, 0, 0, imagesx($src), imagesy($src));
        imagedestroy($src);

        return $canvas;
    }

    public function setOutputScale(float $scale): void
    {
        $this->outputScale = max(0.25, min(4.0, $scale));
    }

    public function gd(): GdImage { return $this->im; }
    public function width(): int  { return $this->width; }
    public function height(): int { return $this->height; }
    public function scale(): int  { return $this->scale; }

    private function s(float $v): int
    {
        return (int) round($v * $this->scale);
    }

    public static function parseColor(string $hex, float $alpha = 1.0): array
    {
        $hex = ltrim(trim($hex), '#');
        if (strlen($hex) === 3) {
            $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
        }
        if (strlen($hex) === 8) {
            $alpha *= hexdec(substr($hex, 6, 2)) / 255;
            $hex = substr($hex, 0, 6);
        }
        if (strlen($hex) !== 6 || !ctype_xdigit($hex)) {
            $hex = '000000';
        }
        return [
            (int) hexdec(substr($hex, 0, 2)),
            (int) hexdec(substr($hex, 2, 2)),
            (int) hexdec(substr($hex, 4, 2)),
            (int) round(127 * (1 - max(0.0, min(1.0, $alpha)))),
        ];
    }

    public function color(string $hex, float $alpha = 1.0): int
    {
        [$r, $g, $b, $a] = self::parseColor($hex, $alpha);
        return imagecolorallocatealpha($this->im, $r, $g, $b, $a);
    }

    public static function mix(string $a, string $b, float $t): string
    {
        [$r1, $g1, $b1] = self::parseColor($a);
        [$r2, $g2, $b2] = self::parseColor($b);
        $t = max(0.0, min(1.0, $t));
        return sprintf(
            '#%02X%02X%02X',
            (int) round($r1 + ($r2 - $r1) * $t),
            (int) round($g1 + ($g2 - $g1) * $t),
            (int) round($b1 + ($b2 - $b1) * $t)
        );
    }

    public function fill(string $hex, float $alpha = 1.0): void
    {
        imagealphablending($this->im, true);
        imagefilledrectangle($this->im, 0, 0, imagesx($this->im), imagesy($this->im), $this->color($hex, $alpha));
    }

    public function rect(float $x, float $y, float $w, float $h, string $hex, float $alpha = 1.0): void
    {
        imagefilledrectangle(
            $this->im,
            $this->s($x),
            $this->s($y),
            $this->s($x + $w) - 1,
            $this->s($y + $h) - 1,
            $this->color($hex, $alpha)
        );
    }

    public function roundRect(float $x, float $y, float $w, float $h, float $r, string $hex, float $alpha = 1.0): void
    {
        if (self::$trace && $alpha >= 0.05) {
            self::$traceShapes[] = ['x' => $x, 'y' => $y, 'w' => $w, 'h' => $h];
        }
        [$red, $green, $blue, $a] = self::parseColor($hex, $alpha);
        if ($a <= 0) {
            $this->roundRectColor($this->im, $this->s($x), $this->s($y), $this->s($w), $this->s($h), $this->s($r), $this->color($hex, $alpha));
            return;
        }
        if ($a >= 127) {
            return;
        }

        $lw = max(1, $this->s($w));
        $lh = max(1, $this->s($h));
        $layer = imagecreatetruecolor($lw, $lh);
        imagealphablending($layer, false);
        imagesavealpha($layer, true);
        imagefilledrectangle($layer, 0, 0, $lw, $lh, imagecolorallocatealpha($layer, 0, 0, 0, 127));
        $col = imagecolorallocatealpha($layer, $red, $green, $blue, $a);
        $this->roundRectColor($layer, 0, 0, $lw, $lh, $this->s($r), $col);

        imagealphablending($this->im, true);
        imagecopy($this->im, $layer, $this->s($x), $this->s($y), 0, 0, $lw, $lh);
        imagedestroy($layer);
    }

    private function roundRectColor(GdImage $im, int $x, int $y, int $w, int $h, int $rs, int $col): void
    {
        $x2 = $x + $w - 1;
        $y2 = $y + $h - 1;
        $rs = max(0, min($rs, (int) (min($w, $h) / 2)));

        if ($rs <= 0) {
            imagefilledrectangle($im, $x, $y, $x2, $y2, $col);
            return;
        }
        imagefilledrectangle($im, $x + $rs, $y, $x2 - $rs, $y2, $col);
        imagefilledrectangle($im, $x, $y + $rs, $x2, $y2 - $rs, $col);
        $d = $rs * 2;
        imagefilledellipse($im, $x + $rs, $y + $rs, $d, $d, $col);
        imagefilledellipse($im, $x2 - $rs, $y + $rs, $d, $d, $col);
        imagefilledellipse($im, $x + $rs, $y2 - $rs, $d, $d, $col);
        imagefilledellipse($im, $x2 - $rs, $y2 - $rs, $d, $d, $col);
    }

    public function strokeRoundRect(
        float $x,
        float $y,
        float $w,
        float $h,
        float $r,
        string $hex,
        float $thickness = 1,
        float $alpha = 1.0
    ): void {
        [$red, $green, $blue, $a] = self::parseColor($hex, $alpha);
        if ($a >= 127) {
            return;
        }
        $t = max(1, $this->s($thickness));
        $pad = $t + 2;
        $lw = max(1, $this->s($w) + $pad * 2);
        $lh = max(1, $this->s($h) + $pad * 2);

        $layer = imagecreatetruecolor($lw, $lh);
        imagealphablending($layer, false);
        imagesavealpha($layer, true);
        imagefilledrectangle($layer, 0, 0, $lw, $lh, imagecolorallocatealpha($layer, 0, 0, 0, 127));
        $col = imagecolorallocatealpha($layer, $red, $green, $blue, $a);

        $x1 = $pad;
        $y1 = $pad;
        $x2 = $pad + $this->s($w) - 1;
        $y2 = $pad + $this->s($h) - 1;
        $rs = max(0, min($this->s($r), (int) (min($this->s($w), $this->s($h)) / 2)));

        imagesetthickness($layer, $t);
        imageline($layer, $x1 + $rs, $y1, $x2 - $rs, $y1, $col);
        imageline($layer, $x1 + $rs, $y2, $x2 - $rs, $y2, $col);
        imageline($layer, $x1, $y1 + $rs, $x1, $y2 - $rs, $col);
        imageline($layer, $x2, $y1 + $rs, $x2, $y2 - $rs, $col);
        if ($rs > 0) {
            $d = $rs * 2;
            imagearc($layer, $x1 + $rs, $y1 + $rs, $d, $d, 180, 270, $col);
            imagearc($layer, $x2 - $rs, $y1 + $rs, $d, $d, 270, 360, $col);
            imagearc($layer, $x1 + $rs, $y2 - $rs, $d, $d, 90, 180, $col);
            imagearc($layer, $x2 - $rs, $y2 - $rs, $d, $d, 0, 90, $col);
        }
        imagesetthickness($layer, 1);

        imagealphablending($this->im, true);
        imagecopy($this->im, $layer, $this->s($x) - $pad, $this->s($y) - $pad, 0, 0, $lw, $lh);
        imagedestroy($layer);
    }

    public function gradient(
        float $x,
        float $y,
        float $w,
        float $h,
        string $from,
        string $to,
        string $dir = 'v',
        float $radius = 0,
        float $alpha = 1.0
    ): void {
        [$r1, $g1, $b1] = self::parseColor($from);
        [$r2, $g2, $b2] = self::parseColor($to);
        $a = (int) round(127 * (1 - max(0.0, min(1.0, $alpha))));

        $x1 = $this->s($x);
        $y1 = $this->s($y);
        $w1 = max(1, $this->s($w));
        $h1 = max(1, $this->s($h));

        $layer = imagecreatetruecolor($w1, $h1);
        imagealphablending($layer, false);
        imagesavealpha($layer, true);

        $steps = $dir === 'h' ? $w1 : $h1;
        for ($i = 0; $i < $steps; $i++) {
            $t = $steps > 1 ? $i / ($steps - 1) : 0.0;
            $col = imagecolorallocatealpha(
                $layer,
                (int) round($r1 + ($r2 - $r1) * $t),
                (int) round($g1 + ($g2 - $g1) * $t),
                (int) round($b1 + ($b2 - $b1) * $t),
                $a
            );
            if ($dir === 'h') {
                imagefilledrectangle($layer, $i, 0, $i, $h1, $col);
            } elseif ($dir === 'd') {
                imagefilledrectangle($layer, 0, $i, $w1, $i, $col);
            } else {
                imagefilledrectangle($layer, 0, $i, $w1, $i, $col);
            }
        }
        if ($dir === 'd') {
            $rot = imagerotate($layer, -20, imagecolorallocatealpha($layer, 0, 0, 0, 127));
            if ($rot) {
                $cx = (int) ((imagesx($rot) - $w1) / 2);
                $cy = (int) ((imagesy($rot) - $h1) / 2);
                $tmp = imagecreatetruecolor($w1, $h1);
                imagealphablending($tmp, false);
                imagesavealpha($tmp, true);
                imagecopy($tmp, $rot, 0, 0, max(0, $cx), max(0, $cy), $w1, $h1);
                imagedestroy($rot);
                imagedestroy($layer);
                $layer = $tmp;
            }
        }

        if ($radius > 0) {
            $this->applyRoundMask($layer, $this->s($radius));
        }
        imagealphablending($this->im, true);
        imagecopy($this->im, $layer, $x1, $y1, 0, 0, $w1, $h1);
        imagedestroy($layer);
    }

    public function radialGlow(float $cx, float $cy, float $radius, string $hex, float $alpha = 0.6, int $steps = 72): void
    {
        $steps = max(8, $steps);
        $perStep = 28 / $steps;
        for ($i = $steps; $i > 0; $i--) {
            $t = $i / $steps;
            $rr = $radius * $t;
            $a = $alpha * (1 - $t) ** 1.7 * $perStep;
            if ($a <= 0.004) {
                continue;
            }
            imagefilledellipse(
                $this->im,
                $this->s($cx),
                $this->s($cy),
                $this->s($rr * 2),
                $this->s($rr * 2),
                $this->color($hex, $a)
            );
        }
    }

    public function shadow(
        float $x,
        float $y,
        float $w,
        float $h,
        float $radius,
        string $hex = '#000000',
        float $alpha = 0.35,
        float $blur = 18,
        float $offsetY = 6
    ): void {
        $pad = (int) ($blur * 2);
        $lw = max(4, $this->s($w + $pad * 2));
        $lh = max(4, $this->s($h + $pad * 2));
        $down = 4;
        $sw = max(4, (int) ($lw / $down));
        $sh = max(4, (int) ($lh / $down));

        $mask = imagecreatetruecolor($sw, $sh);
        imagefilledrectangle($mask, 0, 0, $sw, $sh, imagecolorallocate($mask, 0, 0, 0));
        $rx = (int) ($this->s($pad) / $down);
        $rw = (int) ($this->s($w) / $down);
        $rh = (int) ($this->s($h) / $down);
        $rr = max(1, (int) ($this->s($radius) / $down));
        $this->roundRectColor($mask, $rx, $rx, $rw, $rh, $rr, imagecolorallocate($mask, 255, 255, 255));

        $passes = max(1, (int) round($blur / 3));
        for ($i = 0; $i < $passes; $i++) {
            imagefilter($mask, IMG_FILTER_GAUSSIAN_BLUR);
        }

        [$r, $g, $b] = self::parseColor($hex);
        $layer = imagecreatetruecolor($sw, $sh);
        imagealphablending($layer, false);
        imagesavealpha($layer, true);
        $palette = [];
        for ($v = 0; $v < 256; $v++) {
            $palette[$v] = imagecolorallocatealpha($layer, $r, $g, $b, 127 - (int) round($v / 255 * $alpha * 127));
        }
        for ($py = 0; $py < $sh; $py++) {
            for ($px = 0; $px < $sw; $px++) {
                imagesetpixel($layer, $px, $py, $palette[imagecolorat($mask, $px, $py) & 0xFF]);
            }
        }
        imagedestroy($mask);

        imagealphablending($this->im, true);
        imagecopyresampled(
            $this->im,
            $layer,
            $this->s($x - $pad),
            $this->s($y - $pad + $offsetY),
            0,
            0,
            $lw,
            $lh,
            $sw,
            $sh
        );
        imagedestroy($layer);
    }

    public function shadowOutside(
        float $x,
        float $y,
        float $w,
        float $h,
        float $radius,
        string $hex = '#000000',
        float $alpha = 0.3,
        float $blur = 18,
        float $offsetY = 6
    ): void {
        $sx = max(0, $this->s($x));
        $sy = max(0, $this->s($y));
        $sw = min($this->s($w), imagesx($this->im) - $sx);
        $sh = min($this->s($h), imagesy($this->im) - $sy);
        if ($sw < 4 || $sh < 4) {
            $this->shadow($x, $y, $w, $h, $radius, $hex, $alpha, $blur, $offsetY);
            return;
        }

        $saved = imagecreatetruecolor($sw, $sh);
        imagealphablending($saved, false);
        imagesavealpha($saved, true);
        imagecopy($saved, $this->im, 0, 0, $sx, $sy, $sw, $sh);

        $this->shadow($x, $y, $w, $h, $radius, $hex, $alpha, $blur, $offsetY);

        $this->applyRoundMask($saved, $this->s($radius));
        imagealphablending($this->im, true);
        imagecopy($this->im, $saved, $sx, $sy, 0, 0, $sw, $sh);
        imagedestroy($saved);
    }

    public function glass(float $x, float $y, float $w, float $h, float $radius = 16, array $options = []): void
    {
        $fill      = (float) ($options['fill'] ?? 0.055);
        $border    = (float) ($options['border'] ?? 0.13);
        $blur      = (int) ($options['blur'] ?? 3);
        $highlight = (bool) ($options['highlight'] ?? true);
        $tint      = (string) ($options['tint'] ?? '#FFFFFF');
        $shadow    = (bool) ($options['shadow'] ?? true);

        if ($shadow) {
            $this->shadow($x, $y, $w, $h, $radius, '#000000', 0.30, 14, 5);
        }
        if ($blur > 0) {
            $this->backdropBlur($x, $y, $w, $h, $radius, $blur);
        }

        $this->roundRect($x, $y, $w, $h, $radius, $tint, $fill);
        if ($highlight) {
            $band = min($h * 0.5, 56.0);
            for ($i = 0; $i < $band; $i += 2) {
                $a = 0.05 * (1 - $i / $band) ** 2;
                if ($a < 0.003) {
                    break;
                }
                $inset = $i < $radius ? ($radius - sqrt(max(0.0, $radius ** 2 - ($radius - $i) ** 2))) : 0.0;
                $this->rect($x + $inset + 1, $y + $i + 1, $w - ($inset + 1) * 2, 2, '#FFFFFF', $a);
            }
            $this->line($x + $radius * 0.8, $y + 0.9, $x + $w - $radius * 0.8, $y + 0.9, '#FFFFFF', 1, 0.20);
        }
        if ($border > 0) {
            $this->strokeRoundRect($x, $y, $w, $h, $radius, '#FFFFFF', 1, $border);
        }
    }

    public function backdropBlur(float $x, float $y, float $w, float $h, float $radius, int $passes = 3): void
    {
        $sx = max(0, $this->s($x));
        $sy = max(0, $this->s($y));
        $sw = min($this->s($w), imagesx($this->im) - $sx);
        $sh = min($this->s($h), imagesy($this->im) - $sy);
        if ($sw < 4 || $sh < 4) {
            return;
        }

        $down = 4;
        $tw = max(2, (int) ($sw / $down));
        $th = max(2, (int) ($sh / $down));

        $small = imagecreatetruecolor($tw, $th);
        imagealphablending($small, false);
        imagesavealpha($small, true);
        imagecopyresampled($small, $this->im, 0, 0, $sx, $sy, $tw, $th, $sw, $sh);
        imagealphablending($small, true);
        for ($i = 0; $i < max(1, $passes); $i++) {
            imagefilter($small, IMG_FILTER_GAUSSIAN_BLUR);
        }

        $layer = imagecreatetruecolor($sw, $sh);
        imagealphablending($layer, false);
        imagesavealpha($layer, true);
        imagecopyresampled($layer, $small, 0, 0, 0, 0, $sw, $sh, $tw, $th);
        imagedestroy($small);

        $this->applyRoundMask($layer, $this->s($radius));
        imagealphablending($this->im, true);
        imagecopy($this->im, $layer, $sx, $sy, 0, 0, $sw, $sh);
        imagedestroy($layer);
    }

    public function image(string $path, float $x, float $y, float $w, float $h, float $alpha = 1.0, bool $round = false): bool
    {
        $src = self::loadImage($path);
        if ($src === null) {
            return false;
        }
        $dw = $this->s($w);
        $dh = $this->s($h);

        $scaled = imagecreatetruecolor($dw, $dh);
        imagealphablending($scaled, false);
        imagesavealpha($scaled, true);
        imagefilledrectangle($scaled, 0, 0, $dw, $dh, imagecolorallocatealpha($scaled, 0, 0, 0, 127));
        imagecopyresampled($scaled, $src, 0, 0, 0, 0, $dw, $dh, imagesx($src), imagesy($src));
        if ($round) {
            $this->applyRoundMask($scaled, (int) floor(min($dw, $dh) / 2));
            imagealphablending($scaled, false);
        }

        imagealphablending($this->im, true);
        if ($alpha >= 1.0) {
            imagecopy($this->im, $scaled, $this->s($x), $this->s($y), 0, 0, $dw, $dh);
        } else {
            imagecopymerge($this->im, $scaled, $this->s($x), $this->s($y), 0, 0, $dw, $dh, (int) round($alpha * 100));
        }
        imagedestroy($scaled);

        return true;
    }

    private static array $imageCache = [];

    public static function loadImage(string $path): ?GdImage
    {
        if (array_key_exists($path, self::$imageCache)) {
            return self::$imageCache[$path];
        }
        $image = null;
        if (is_file($path)) {
            $data = @file_get_contents($path);
            if ($data !== false) {
                $loaded = @imagecreatefromstring($data);
                if ($loaded !== false) {
                    imagealphablending($loaded, false);
                    imagesavealpha($loaded, true);
                    $image = $loaded;
                }
            }
        }

        return self::$imageCache[$path] = $image;
    }

    public static function imageLuminance(string $path): float
    {
        $src = self::loadImage($path);
        if ($src === null) {
            return 0.5;
        }
        $w = imagesx($src);
        $h = imagesy($src);
        $sum = 0.0;
        $count = 0;
        $step = max(1, (int) ($w / 24));

        for ($y = 0; $y < $h; $y += $step) {
            for ($x = 0; $x < $w; $x += $step) {
                $rgba = imagecolorat($src, $x, $y);
                $a = ($rgba >> 24) & 0x7F;
                if ($a > 90) {
                    continue;
                }
                $r = ($rgba >> 16) & 0xFF;
                $g = ($rgba >> 8) & 0xFF;
                $b = $rgba & 0xFF;
                $sum += (0.2126 * $r + 0.7152 * $g + 0.0722 * $b) / 255;
                $count++;
            }
        }

        return $count > 0 ? $sum / $count : 0.5;
    }

    public function gradientLine(
        float $x1,
        float $y1,
        float $x2,
        float $y2,
        string $from,
        string $to,
        float $thickness = 2,
        float $alpha = 1.0
    ): void {
        $steps = max(8, (int) (abs($x2 - $x1) + abs($y2 - $y1)) / 4);
        for ($i = 0; $i < $steps; $i++) {
            $t1 = $i / $steps;
            $t2 = ($i + 1) / $steps;
            $this->rect(
                $x1 + ($x2 - $x1) * $t1,
                $y1 + ($y2 - $y1) * $t1 - $thickness / 2,
                ($x2 - $x1) * ($t2 - $t1) + 0.8,
                $thickness,
                self::mix($from, $to, $t1),
                $alpha
            );
        }
    }

    public function areaGradient(array $points, float $x, float $y, float $w, float $h, string $hex, float $alphaTop = 0.35): void
    {
        if (count($points) < 2 || $w <= 0 || $h <= 0) {
            return;
        }
        $lw = max(2, $this->s($w));
        $lh = max(2, $this->s($h));

        $layer = imagecreatetruecolor($lw, $lh);
        imagealphablending($layer, false);
        imagesavealpha($layer, true);

        [$r, $g, $b] = self::parseColor($hex);
        for ($row = 0; $row < $lh; $row++) {
            $t = $row / max(1, $lh - 1);
            $a = $alphaTop * (1 - $t) ** 1.35;
            imagefilledrectangle(
                $layer,
                0,
                $row,
                $lw,
                $row,
                imagecolorallocatealpha($layer, $r, $g, $b, (int) round(127 * (1 - $a)))
            );
        }

        $clear = imagecolorallocatealpha($layer, 0, 0, 0, 127);
        $count = count($points);
        for ($i = 0; $i < $count - 1; $i++) {
            $ax = $this->s($points[$i][0] - $x);
            $ay = $this->s($points[$i][1] - $y);
            $bx = $this->s($points[$i + 1][0] - $x);
            $by = $this->s($points[$i + 1][1] - $y);
            $span = max(1, $bx - $ax);
            for ($col = $ax; $col <= $bx; $col++) {
                if ($col < 0 || $col >= $lw) {
                    continue;
                }
                $curve = (int) round($ay + ($by - $ay) * (($col - $ax) / $span));
                if ($curve > 0) {
                    imagefilledrectangle($layer, $col, 0, $col, min($lh - 1, $curve), $clear);
                }
            }
        }
        $firstX = $this->s($points[0][0] - $x);
        $lastX = $this->s($points[$count - 1][0] - $x);
        if ($firstX > 0) {
            imagefilledrectangle($layer, 0, 0, $firstX - 1, $lh, $clear);
        }
        if ($lastX < $lw - 1) {
            imagefilledrectangle($layer, $lastX + 1, 0, $lw, $lh, $clear);
        }

        imagealphablending($this->im, true);
        imagecopy($this->im, $layer, $this->s($x), $this->s($y), 0, 0, $lw, $lh);
        imagedestroy($layer);
    }

    public function line(float $x1, float $y1, float $x2, float $y2, string $hex, float $thickness = 1, float $alpha = 1.0): void
    {
        imagesetthickness($this->im, max(1, $this->s($thickness)));
        imageline($this->im, $this->s($x1), $this->s($y1), $this->s($x2), $this->s($y2), $this->color($hex, $alpha));
        imagesetthickness($this->im, 1);
    }

    public function dashedLine(float $x1, float $y1, float $x2, float $y2, string $hex, float $thickness = 1, float $dash = 6, float $gap = 5, float $alpha = 1.0): void
    {
        $len = sqrt(($x2 - $x1) ** 2 + ($y2 - $y1) ** 2);
        if ($len <= 0) {
            return;
        }
        $dx = ($x2 - $x1) / $len;
        $dy = ($y2 - $y1) / $len;
        for ($p = 0.0; $p < $len; $p += $dash + $gap) {
            $e = min($len, $p + $dash);
            $this->line($x1 + $dx * $p, $y1 + $dy * $p, $x1 + $dx * $e, $y1 + $dy * $e, $hex, $thickness, $alpha);
        }
    }

    public function circle(float $cx, float $cy, float $radius, string $hex, float $alpha = 1.0): void
    {
        imagefilledellipse($this->im, $this->s($cx), $this->s($cy), $this->s($radius * 2), $this->s($radius * 2), $this->color($hex, $alpha));
    }

    public function ring(float $cx, float $cy, float $radius, float $thickness, string $hex, float $start = 0, float $end = 360, float $alpha = 1.0): void
    {
        $col = $this->color($hex, $alpha);
        $steps = max(24, (int) (($end - $start) * 2));
        $inner = $radius - $thickness / 2;
        $outer = $radius + $thickness / 2;
        $pts = [];
        for ($i = 0; $i <= $steps; $i++) {
            $ang = deg2rad($start + ($end - $start) * $i / $steps);
            $pts[] = $this->s($cx + cos($ang) * $outer);
            $pts[] = $this->s($cy + sin($ang) * $outer);
        }
        for ($i = $steps; $i >= 0; $i--) {
            $ang = deg2rad($start + ($end - $start) * $i / $steps);
            $pts[] = $this->s($cx + cos($ang) * $inner);
            $pts[] = $this->s($cy + sin($ang) * $inner);
        }
        imagefilledpolygon($this->im, $pts, $col);
    }

    public function polygon(array $points, string $hex, float $alpha = 1.0): void
    {
        $flat = [];
        foreach ($points as $p) {
            $flat[] = $this->s($p[0]);
            $flat[] = $this->s($p[1]);
        }
        if (count($flat) < 6) {
            return;
        }
        imagefilledpolygon($this->im, $flat, $this->color($hex, $alpha));
    }

    public function polyline(array $points, string $hex, float $thickness = 2, float $alpha = 1.0): void
    {
        $n = count($points);
        for ($i = 1; $i < $n; $i++) {
            $this->line($points[$i - 1][0], $points[$i - 1][1], $points[$i][0], $points[$i][1], $hex, $thickness, $alpha);
            if ($thickness > 2 && $i < $n - 1) {
                $this->circle($points[$i][0], $points[$i][1], $thickness / 2, $hex, $alpha);
            }
        }
    }

    public function triangle(float $cx, float $cy, float $size, bool $up, string $hex, float $alpha = 1.0): void
    {
        $h = $size * 0.86;
        $points = $up
            ? [[$cx, $cy - $h / 2], [$cx - $size / 2, $cy + $h / 2], [$cx + $size / 2, $cy + $h / 2]]
            : [[$cx, $cy + $h / 2], [$cx - $size / 2, $cy - $h / 2], [$cx + $size / 2, $cy - $h / 2]];
        $this->polygon($points, $hex, $alpha);
    }

    public function arrow(float $cx, float $cy, float $size, bool $up, string $hex, float $alpha = 1.0): void
    {
        $this->triangle($cx, $cy - ($up ? $size * 0.18 : -$size * 0.18), $size * 0.82, $up, $hex, $alpha);
        $this->rect(
            $cx - $size * 0.13,
            $up ? $cy + $size * 0.08 : $cy - $size * 0.46,
            $size * 0.26,
            $size * 0.38,
            $hex,
            $alpha
        );
    }

    public static function fontPath(string $weight = self::W_BOLD): string
    {
        if ($weight === self::W_NUM || $weight === self::W_NUM_BOLD) {
            $numeric = APP_ASSETS . '/fonts/NiktoNum-' . ($weight === self::W_NUM_BOLD ? 'SemiBold' : 'Medium') . '.ttf';
            if (is_file($numeric)) {
                return $numeric;
            }
            $weight = $weight === self::W_NUM_BOLD ? self::W_SEMIBOLD : self::W_MEDIUM;
        }

        $file = APP_ASSETS . '/fonts/Vazirmatn-' . $weight . '.ttf';
        if (is_file($file)) {
            return $file;
        }
        $fallback = APP_ASSETS . '/fonts/Vazirmatn-Regular.ttf';
        if (is_file($fallback)) {
            return $fallback;
        }
        return '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf';
    }

    private static array $metricsCache = [];

    public function metrics(float $size, string $weight = self::W_BOLD): array
    {
        $fs = $size * $this->scale;
        $key = $weight . '|' . $fs;
        if (isset(self::$metricsCache[$key])) {
            return self::$metricsCache[$key];
        }

        $box = imagettfbbox($fs, 0, self::fontPath($weight), 'الکجMg0');
        $top = $box === false ? -$fs : (float) $box[7];
        $bottom = $box === false ? $fs * 0.25 : (float) $box[1];

        return self::$metricsCache[$key] = ['top' => $top, 'height' => $bottom - $top];
    }

    private static function fontFor(string $weight, string $text): string
    {
        if (($weight === self::W_NUM || $weight === self::W_NUM_BOLD)
            && preg_match('/[\x{0600}-\x{06FF}\x{FB50}-\x{FDFF}\x{FE70}-\x{FEFF}]/u', $text) === 1
        ) {
            return $weight === self::W_NUM_BOLD ? self::W_SEMIBOLD : self::W_MEDIUM;
        }

        return $weight;
    }

    private static array $digitCache = [];

    private function digitCenter(string $text, float $fs, string $font): float
    {
        $reference = preg_match('/[\x{06F0}-\x{06F9}\x{0660}-\x{0669}]/u', $text) === 1
            ? '۱۲۳۴۶۷۸۹'
            : '0123456789';
        $key = $font . '|' . $fs . '|' . $reference;
        if (!isset(self::$digitCache[$key])) {
            $box = imagettfbbox($fs, 0, $font, $reference);
            self::$digitCache[$key] = $box === false
                ? -$fs * 0.36
                : ((float) $box[7] + (float) $box[1]) / 2;
        }

        return self::$digitCache[$key];
    }

    private function inkCenter(string $visual, float $fs, string $font): float
    {
        $box = imagettfbbox($fs, 0, $font, $visual);
        if ($box === false) {
            return -$fs * 0.35;
        }

        return ((float) $box[7] + (float) $box[1]) / 2;
    }

    public function inkHeight(string $text, float $size, string $weight = self::W_BOLD): float
    {
        $weight = self::fontFor($weight, $text);
        $visual = Persian::prepare($text);
        if ($visual === '') {
            return 0.0;
        }
        $box = imagettfbbox($size * $this->scale, 0, self::fontPath($weight), $visual);

        return $box === false ? $size * 0.7 : ((float) $box[1] - (float) $box[7]) / $this->scale;
    }

    public function lineHeight(float $size, string $weight = self::W_BOLD): float
    {
        return $this->metrics($size, $weight)['height'] / $this->scale;
    }

    public function measure(string $text, float $size, string $weight = self::W_BOLD, bool $prepared = false): array
    {
        $weight = self::fontFor($weight, $text);
        $visual = $prepared ? $text : Persian::prepare($text);
        if ($visual === '') {
            return ['w' => 0.0, 'h' => 0.0, 'top' => 0.0];
        }
        $box = imagettfbbox($size * $this->scale, 0, self::fontPath($weight), $visual);
        if ($box === false) {
            return ['w' => 0.0, 'h' => 0.0, 'top' => 0.0];
        }
        $metrics = $this->metrics($size, $weight);

        return [
            'w'   => abs($box[2] - $box[0]) / $this->scale,
            'h'   => $metrics['height'] / $this->scale,
            'top' => $metrics['top'] / $this->scale,
        ];
    }

    public function textWidth(string $text, float $size, string $weight = self::W_BOLD): float
    {
        return $this->measure($text, $size, $weight)['w'];
    }

    public function text(
        string $text,
        float $x,
        float $y,
        float $size,
        string $hex,
        string $weight = self::W_BOLD,
        string $align = 'right',
        float $alpha = 1.0,
        string $valign = 'top',
        float $letterSpacing = 0.0
    ): float {
        if (trim($text) === '') {
            return 0.0;
        }
        $weight = self::fontFor($weight, $text);
        $visual = Persian::prepare($text);
        $font = self::fontPath($weight);
        $col  = $this->color($hex, $alpha);
        $fs   = $size * $this->scale;
        $metrics = $this->metrics($size, $weight);

        $drawY = match ($valign) {
            'baseline' => $this->s($y),
            'middle'   => $this->s($y) - (int) round($metrics['height'] / 2 + $metrics['top']),
            'ink'      => $this->s($y) - (int) round($this->inkCenter($visual, $fs, $font)),
            'num'      => $this->s($y) - (int) round($this->digitCenter($text, $fs, $font)),
            default    => $this->s($y) - (int) round($metrics['top']),
        };

        if ($letterSpacing > 0.0) {
            return $this->textSpaced($visual, $x, $drawY, $size, $col, $font, $align, $letterSpacing);
        }

        $box = imagettfbbox($fs, 0, $font, $visual);
        $w = abs($box[2] - $box[0]);
        $drawX = match ($align) {
            'center' => $this->s($x) - (int) round($w / 2),
            'left'   => $this->s($x),
            default  => $this->s($x) - $w,
        };

        imagettftext($this->im, $fs, 0, (int) $drawX - $box[0], $drawY, $col, $font, $visual);

        if (self::$trace) {
            $ink = [
                ($drawX) / $this->scale,
                ($drawY + $box[7]) / $this->scale,
                ($drawX + $w) / $this->scale,
                ($drawY + $box[1]) / $this->scale,
            ];
            $optical = match ($valign) {
                'num'   => $drawY + $this->digitCenter($text, $fs, $font),
                'ink'   => $drawY + ($box[7] + $box[1]) / 2,
                default => $drawY + $metrics['top'] + $metrics['height'] / 2,
            };
            self::$traceBoxes[] = [
                'optical' => $optical / $this->scale,
                'x'    => $drawX / $this->scale,
                'y'    => ($drawY + $metrics['top']) / $this->scale,
                'w'    => $w / $this->scale,
                'h'    => $metrics['height'] / $this->scale,
                'text'   => mb_substr($text, 0, 28),
                'size'   => $size,
                'ink'    => $ink,
                'base'   => $drawY / $this->scale,
                'weight' => $weight,
                'valign' => $valign,
            ];
        }

        return $w / $this->scale;
    }

    private function textSpaced(
        string $visual,
        float $x,
        int $drawY,
        float $size,
        int $col,
        string $font,
        string $align,
        float $spacing
    ): float {
        $chars = preg_split('//u', $visual, -1, PREG_SPLIT_NO_EMPTY) ?: [];
        $fs = $size * $this->scale;
        $sp = $spacing * $this->scale;

        $total = 0.0;
        $widths = [];
        foreach ($chars as $ch) {
            $b = imagettfbbox($fs, 0, $font, $ch);
            $cw = $b[2] - $b[0];
            if ($ch === ' ') {
                $cw = max($cw, (int) ($fs * 0.32));
            }
            $widths[] = $cw;
            $total += $cw + $sp;
        }
        $total -= $sp;

        $cursor = match ($align) {
            'center' => $this->s($x) - $total / 2,
            'left'   => $this->s($x),
            default  => $this->s($x) - $total,
        };

        foreach ($chars as $i => $ch) {
            if (trim($ch) !== '') {
                imagettftext($this->im, $fs, 0, (int) round($cursor), $drawY, $col, $font, $ch);
            }
            $cursor += $widths[$i] + $sp;
        }

        return $total / $this->scale;
    }

    public function textFit(
        string $text,
        float $x,
        float $y,
        float $maxWidth,
        float $size,
        string $hex,
        string $weight = self::W_BOLD,
        string $align = 'right',
        float $minSize = 9,
        float $alpha = 1.0,
        string $valign = 'top'
    ): float {
        $s = $size;
        while ($s > $minSize && $this->textWidth($text, $s, $weight) > $maxWidth) {
            $s -= 0.5;
        }
        if ($this->textWidth($text, $s, $weight) > $maxWidth) {
            $text = $this->ellipsize($text, $maxWidth, $s, $weight);
        }
        $offset = $valign === 'top'
            ? ($this->lineHeight($size, $weight) - $this->lineHeight($s, $weight)) / 2
            : 0.0;
        $this->text($text, $x, $y + $offset, $s, $hex, $weight, $align, $alpha, $valign);

        return $s;
    }

    public function ellipsize(string $text, float $maxWidth, float $size, string $weight = self::W_BOLD): string
    {
        if ($this->textWidth($text, $size, $weight) <= $maxWidth) {
            return $text;
        }
        $chars = preg_split('//u', $text, -1, PREG_SPLIT_NO_EMPTY) ?: [];
        $out = '';
        foreach ($chars as $ch) {
            if ($this->textWidth($out . $ch . '…', $size, $weight) > $maxWidth) {
                break;
            }
            $out .= $ch;
        }
        return rtrim($out) . '…';
    }

    public function wrap(string $text, float $maxWidth, float $size, string $weight = self::W_REGULAR, int $maxLines = 3): array
    {
        $words = preg_split('/\s+/u', trim($text)) ?: [];
        $lines = [];
        $cur = '';
        foreach ($words as $word) {
            $try = $cur === '' ? $word : $cur . ' ' . $word;
            if ($this->textWidth($try, $size, $weight) <= $maxWidth || $cur === '') {
                $cur = $try;
            } else {
                $lines[] = $cur;
                $cur = $word;
                if (count($lines) >= $maxLines) {
                    break;
                }
            }
        }
        if ($cur !== '' && count($lines) < $maxLines) {
            $lines[] = $cur;
        }
        if (count($lines) === $maxLines) {
            $last = array_pop($lines);
            $lines[] = $this->ellipsize((string) $last, $maxWidth, $size, $weight);
        }
        return $lines;
    }

    public function paste(GdImage $src, float $x, float $y, ?float $w = null, ?float $h = null): void
    {
        $sw = imagesx($src);
        $sh = imagesy($src);
        $dw = $w !== null ? $this->s($w) : $sw;
        $dh = $h !== null ? $this->s($h) : $sh;
        imagealphablending($this->im, true);
        imagecopyresampled($this->im, $src, $this->s($x), $this->s($y), 0, 0, $dw, $dh, $sw, $sh);
    }

    public function pasteCanvas(self $other, float $x, float $y): void
    {
        imagealphablending($this->im, true);
        imagecopy($this->im, $other->im, $this->s($x), $this->s($y), 0, 0, imagesx($other->im), imagesy($other->im));
    }

    public function noise(float $intensity = 6.0): void
    {
        $w = imagesx($this->im);
        $h = imagesy($this->im);
        $step = max(2, $this->scale);
        for ($y = 0; $y < $h; $y += $step) {
            for ($x = 0; $x < $w; $x += $step) {
                if (random_int(0, 6) !== 0) {
                    continue;
                }
                $a = (int) round(127 - $intensity * random_int(2, 10) / 10);
                imagefilledrectangle(
                    $this->im,
                    $x,
                    $y,
                    $x + $step - 1,
                    $y + $step - 1,
                    imagecolorallocatealpha($this->im, 255, 255, 255, max(100, min(127, $a)))
                );
            }
        }
    }

    public function savePng(string $path): string
    {
        $out = $this->flatten();
        imagepng($out, $path, 4);
        imagedestroy($out);
        return $path;
    }

    public function saveJpeg(string $path, int $quality = 92): string
    {
        $out = $this->flatten('#0B0E17');
        imagejpeg($out, $path, $quality);
        imagedestroy($out);
        return $path;
    }

    private function flatten(?string $bg = null): GdImage
    {
        $outW = (int) round($this->width * $this->outputScale);
        $outH = (int) round($this->height * $this->outputScale);

        $out = imagecreatetruecolor($outW, $outH);
        imagealphablending($out, false);
        imagesavealpha($out, true);
        if ($bg !== null) {
            [$r, $g, $b] = self::parseColor($bg);
            imagefilledrectangle($out, 0, 0, $outW, $outH, imagecolorallocate($out, $r, $g, $b));
            imagealphablending($out, true);
        } else {
            imagefilledrectangle($out, 0, 0, $outW, $outH, imagecolorallocatealpha($out, 0, 0, 0, 127));
        }
        imagecopyresampled(
            $out,
            $this->im,
            0,
            0,
            0,
            0,
            $outW,
            $outH,
            imagesx($this->im),
            imagesy($this->im)
        );
        imagesavealpha($out, true);

        return $out;
    }

    public function __destruct()
    {
        if (isset($this->im)) {
            @imagedestroy($this->im);
        }
    }

    private function applyRoundMask(GdImage $layer, int $radius): void
    {
        $w = imagesx($layer);
        $h = imagesy($layer);
        $radius = max(0, min($radius, (int) (min($w, $h) / 2)));
        if ($radius <= 0) {
            return;
        }
        imagealphablending($layer, false);
        $clear = imagecolorallocatealpha($layer, 0, 0, 0, 127);
        $corners = [[0, 0, $radius, $radius], [$w - $radius, 0, $w - $radius - 1, $radius],
            [0, $h - $radius, $radius, $h - $radius - 1], [$w - $radius, $h - $radius, $w - $radius - 1, $h - $radius - 1]];
        foreach ($corners as [$sx, $sy, $cx, $cy]) {
            for ($y = $sy; $y < $sy + $radius; $y++) {
                for ($x = $sx; $x < $sx + $radius; $x++) {
                    if ($x < 0 || $y < 0 || $x >= $w || $y >= $h) {
                        continue;
                    }
                    if ((($x - $cx) ** 2 + ($y - $cy) ** 2) > $radius ** 2) {
                        imagesetpixel($layer, $x, $y, $clear);
                    }
                }
            }
        }
        imagealphablending($layer, true);
    }
}
}

namespace Nikto\Render {
use DateTimeImmutable;
use Nikto\Core\Jalali;
use Nikto\Core\Settings;
use Nikto\Text\Persian;

abstract class Card
{
    protected Theme $theme;
    protected string $footer;
    protected DateTimeImmutable $now;
    protected int $quality;
    protected float $outputScale;

    public function __construct(?string $theme = null, array $options = [])
    {
        $this->theme  = new Theme($theme);
        $this->footer = (string) ($options['footer'] ?? Settings::get('brand_link'));
        $this->now    = $options['now'] ?? Settings::now();
        [$this->quality, $this->outputScale] = self::qualityProfile();
    }

    protected static function qualityProfile(): array
    {
        $profiles = [
            'normal' => [2, 1.5],
            'high'   => [3, 2.5],
            'ultra'  => [4, 3.0],
        ];
        $key = Settings::get('quality');
        [$scale, $output] = $profiles[$key] ?? $profiles['high'];

        $limit = self::memoryLimitBytes();
        if ($limit > 0) {
            while ($scale > 2 && (1200 * $scale) * (900 * $scale) * 5 > $limit) {
                $scale--;
            }
        }

        return [$scale, $output];
    }

    private static function memoryLimitBytes(): int
    {
        $raw = trim((string) ini_get('memory_limit'));
        if ($raw === '' || $raw === '-1') {
            return 0;
        }
        $unit = strtolower(substr($raw, -1));
        $value = (int) $raw;

        return match ($unit) {
            'g'     => $value * 1024 * 1024 * 1024,
            'm'     => $value * 1024 * 1024,
            'k'     => $value * 1024,
            default => $value,
        };
    }

    abstract public function render(): Canvas;

    public function save(?string $path = null): string
    {
        $path ??= APP_STORAGE . '/cards/' . static::slug() . '-' . $this->now->format('Ymd-His') . '.png';
        $dir = dirname($path);
        if (!is_dir($dir)) {
            @mkdir($dir, 0775, true);
        }

        return $this->render()->savePng($path);
    }

    public static function slug(): string
    {
        $parts = explode('\\', static::class);

        return strtolower(preg_replace('/([a-z])([A-Z])/', '$1-$2', end($parts)) ?? 'card');
    }

    protected function tnum(string $text): string
    {
        return Settings::get('digits') === 'fa' ? Persian::faDigits($text) : Persian::enDigits($text);
    }

    protected function dnum(string $text): string
    {
        return Settings::get('digits_data') === 'fa' ? Persian::faDigits($text) : Persian::enDigits($text);
    }

    protected function jalaliDate(string $pattern = 'l j F Y'): string
    {
        return $this->tnum(Jalali::format($this->now, $pattern));
    }

    protected function clockText(): string
    {
        return $this->tnum($this->now->format('H:i'));
    }

    protected function dateLine(): string
    {
        return $this->jalaliDate('l j F Y') . ' — ساعت ' . $this->clockText();
    }
}
}

namespace Nikto\Render {
use Nikto\Data\Coins;

final class CoinLogo
{
    public static bool $lightSurface = true;

    private static array $preferWhite = [];

    public static function path(string $symbol, bool $white = false): ?string
    {
        $file = APP_ASSETS . '/coins/' . ($white ? 'white' : 'color') . '/' . strtolower($symbol) . '.png';

        return is_file($file) ? $file : null;
    }

    public static function exists(string $symbol): bool
    {
        return self::path($symbol) !== null;
    }

    public static function draw(Canvas $c, string $symbol, float $cx, float $cy, float $size, bool $plate = true): void
    {
        $symbol = strtoupper($symbol);
        $radius = $size / 2;

        if ($plate) {
            if (self::$lightSurface) {
                $c->circle($cx, $cy, $radius, '#F4F7F5', 1.0);
                $c->ring($cx, $cy, $radius - 0.5, 1.1, '#0A0F0D', 0, 360, 0.16);
            } else {
                $c->circle($cx, $cy, $radius, '#FFFFFF', 0.08);
                $c->ring($cx, $cy, $radius - 0.5, 1, '#FFFFFF', 0, 360, 0.16);
            }
        }

        $path = self::path($symbol);
        if ($path !== null) {
            if (!self::$lightSurface) {
                if (!isset(self::$preferWhite[$symbol])) {
                    self::$preferWhite[$symbol] = Canvas::imageLuminance($path) < 0.22
                        && self::path($symbol, true) !== null;
                }
                if (self::$preferWhite[$symbol]) {
                    $path = self::path($symbol, true) ?? $path;
                }
            }
            $inner = $plate ? $size * 0.72 : $size;
            $c->image($path, $cx - $inner / 2, $cy - $inner / 2, $inner, $inner, 1.0, !$plate);

            return;
        }

        $color = Coins::color($symbol);
        $ink = '#FFFFFF';
        if (self::$lightSurface) {
            $c->circle($cx, $cy, $radius - 1, '#E4E4E1', 1.0);
            $ink = '#3A3A38';
        } else {
            $c->circle($cx, $cy, $radius - 1, $color, 0.22);
        }
        $mark = mb_strlen($symbol) <= 3 ? $symbol : mb_substr($symbol, 0, 1);
        $c->text(
            $mark,
            $cx,
            $cy,
            $size * (mb_strlen($mark) === 1 ? 0.42 : 0.32),
            $ink,
            Canvas::W_BOLD,
            'center',
            0.96,
            'ink'
        );
    }
}
}

namespace Nikto\Render {
use Nikto\Data\FearGreedProvider;

final class FearGreedCard extends Card
{
    private array $data;

    private const HISTORY_LABELS = [
        'yesterday' => 'دیروز',
        'week'      => '۷ روز پیش',
        'month'     => '۱ ماه پیش',
    ];

    private const BOUNDS = [0, 25, 45, 56, 76, 101];

    private const TOP_H = 188.0;
    private const GAP   = 16.0;

    public function __construct(array $data, ?string $theme = null, array $options = [])
    {
        parent::__construct($theme, $options);
        $this->data = $data;
    }

    public function render(): Canvas
    {
        $c = new Canvas(1200, 616, $this->quality);
        $c->setOutputScale($this->outputScale);
        $t = $this->theme;

        $rect = Frame::draw($c, $t, ['footer' => $this->footer]);
        $top = Frame::header($c, $t, $rect, 'شاخص ترس و طمع بازار', $this->dateLine(), 'Fear & Greed Index');

        $this->today($c, $t, $rect['x'], $top, $rect['w'], self::TOP_H);

        $chartY = $top + self::TOP_H + self::GAP;
        $this->trend($c, $t, $rect['x'], $chartY, $rect['w'], $rect['y'] + $rect['h'] - $chartY);

        return $c;
    }

    private function zoneIndex(int $value): int
    {
        foreach (FearGreedProvider::ZONES as $i => $zone) {
            if ($value <= $zone['max']) {
                return $i;
            }
        }

        return count(FearGreedProvider::ZONES) - 1;
    }

    private function zoneColor(Theme $t, int $index): string
    {
        $down = $t->c('down');
        $up = $t->c('up');

        return [
            $down,
            Canvas::mix($down, '#FFFFFF', 0.45),
            Canvas::mix($t->c('flat'), '#FFFFFF', 0.35),
            Canvas::mix($up, '#FFFFFF', 0.45),
            $up,
        ][$index] ?? $t->c('ink');
    }

    private function zoneStrong(Theme $t, int $index): string
    {
        return match (true) {
            $index <= 1 => $t->c('down'),
            $index === 2 => $t->c('ink_dim'),
            default     => $t->c('up'),
        };
    }

    private function today(Canvas $c, Theme $t, float $x, float $y, float $w, float $h): void
    {
        $value = max(0, min(100, (int) $this->data['value']));
        $index = $this->zoneIndex($value);

        Frame::panel($c, $t, $x, $y, $w, $h, 20);

        $pad = 32.0;
        $right = $x + $w - $pad;
        $c->text('شاخص امروز', $right, $y + 38, 11, $t->c('ink_faint'), Canvas::W_MEDIUM, 'right', 1.0, 'middle');
        $c->text($this->dnum((string) $value), $right, $y + 94, 50, $t->c('ink'), Canvas::W_NUM_BOLD, 'right', 1.0, 'num');
        $c->text((string) $this->data['zone']['fa'], $right, $y + 146, 15, $this->zoneStrong($t, $index), Canvas::W_BOLD, 'right', 1.0, 'middle');

        $barL = $x + $pad;
        $barR = $x + $w - 260;
        $barW = $barR - $barL;
        $barY = $y + 94;
        $gap = 3.0;
        $usable = $barW - $gap * 4;

        foreach (array_keys(FearGreedProvider::ZONES) as $i) {
            $from = self::BOUNDS[$i];
            $to = self::BOUNDS[$i + 1];
            $segX = $barL + $usable * ($from / 100) + $gap * $i;
            $c->roundRect($segX, $barY - 4, $usable * (($to - $from) / 100), 8, 4, $this->zoneColor($t, $i), 1.0);
        }

        $markX = $barL + $usable * ($value / 100) + $gap * min(4, $index);
        $c->circle($markX, $barY, 11, '#FFFFFF');
        $c->circle($markX, $barY, 8, $t->c('line'));

        $c->text('ترس شدید', $barL, $barY + 32, 10, $t->c('ink_faint'), Canvas::W_MEDIUM, 'left', 1.0, 'middle');
        $c->text('طمع شدید', $barR, $barY + 32, 10, $t->c('ink_faint'), Canvas::W_MEDIUM, 'right', 1.0, 'middle');
    }

    private function trend(Canvas $c, Theme $t, float $x, float $y, float $w, float $h): void
    {
        Frame::panel($c, $t, $x, $y, $w, $h, 20);

        $pad = 32.0;
        $rowY = $y + 34;
        $c->text('۳۰ روز اخیر', $x + $pad, $rowY, 11, $t->c('ink_faint'), Canvas::W_MEDIUM, 'left', 1.0, 'middle');

        $history = (array) ($this->data['history'] ?? []);
        $cursor = $x + $w - $pad;
        foreach (self::HISTORY_LABELS as $key => $label) {
            if (!isset($history[$key])) {
                continue;
            }
            $c->text($label, $cursor, $rowY, 11, $t->c('ink_faint'), Canvas::W_MEDIUM, 'right', 1.0, 'middle');
            $cursor -= $c->textWidth($label, 11, Canvas::W_MEDIUM) + 8;
            $valueText = $this->dnum((string) (int) $history[$key]['value']);
            $c->text($valueText, $cursor, $rowY, 15, $t->c('ink'), Canvas::W_NUM_BOLD, 'right', 1.0, 'num');
            $cursor -= $c->textWidth($valueText, 15, Canvas::W_NUM_BOLD) + 34;
        }

        $series = array_values(array_map('intval', (array) ($this->data['series'] ?? [])));
        $n = count($series);
        if ($n < 5) {
            return;
        }

        $chartX = $x + $pad;
        $chartW = $w - $pad * 2;
        $chartY = $rowY + 28;
        $chartH = $y + $h - 30 - $chartY;
        $min = min($series);
        $span = max(1, max($series) - $min);

        $points = [];
        foreach ($series as $i => $v) {
            $points[] = [$chartX + $chartW * ($i / ($n - 1)), $chartY + $chartH - (($v - $min) / $span) * $chartH];
        }

        $color = $this->zoneStrong($t, $this->zoneIndex((int) $this->data['value']));
        $c->areaGradient($points, $chartX, $chartY, $chartW, $chartH, $color, 0.10);
        $c->polyline($points, $color, 2.0, 1.0);
        $last = $points[$n - 1];
        $c->circle($last[0], $last[1], 4.5, $color);
    }
}
}

namespace Nikto\Render {
final class Flags
{
    public static function draw(Canvas $c, string $code, float $x, float $y, float $w, float $h): void
    {
        $code = strtoupper(trim($code));
        $method = 'flag' . $code;

        $c->rect($x, $y, $w, $h, '#FFFFFF');
        if (method_exists(self::class, $method)) {
            self::$method($c, $x, $y, $w, $h);
        } else {
            self::flagGeneric($c, $code, $x, $y, $w, $h);
        }
        $c->strokeRoundRect($x, $y, $w, $h, 2, '#8B93A7', 1.1, 0.55);
    }

    private static function bandsH(Canvas $c, float $x, float $y, float $w, float $h, array $colors): void
    {
        $n = count($colors);
        $bh = $h / $n;
        foreach ($colors as $i => $color) {
            $c->rect($x, $y + $i * $bh, $w, $bh + 0.5, $color);
        }
    }

    private static function bandsV(Canvas $c, float $x, float $y, float $w, float $h, array $colors): void
    {
        $n = count($colors);
        $bw = $w / $n;
        foreach ($colors as $i => $color) {
            $c->rect($x + $i * $bw, $y, $bw + 0.5, $h, $color);
        }
    }

    private static function nordicCross(Canvas $c, float $x, float $y, float $w, float $h, string $bg, string $cross, string $inner = ''): void
    {
        $c->rect($x, $y, $w, $h, $bg);
        $t = $h * 0.22;
        $cxPos = $x + $w * 0.36;
        if ($inner !== '') {
            $c->rect($cxPos - $t * 0.85, $y, $t * 1.7, $h, $inner);
            $c->rect($x, $y + $h / 2 - $t * 0.85, $w, $t * 1.7, $inner);
        }
        $c->rect($cxPos - $t / 2, $y, $t, $h, $cross);
        $c->rect($x, $y + $h / 2 - $t / 2, $w, $t, $cross);
    }

    private static function stars(Canvas $c, float $cx, float $cy, float $radius, int $count, string $color, float $dot): void
    {
        for ($i = 0; $i < $count; $i++) {
            $ang = deg2rad(-90 + 360 * $i / $count);
            $c->circle($cx + cos($ang) * $radius, $cy + sin($ang) * $radius, $dot, $color);
        }
    }

    private static function flagUS(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $stripe = $h / 13;
        for ($i = 0; $i < 13; $i++) {
            $c->rect($x, $y + $i * $stripe, $w, $stripe + 0.4, $i % 2 === 0 ? '#B22234' : '#FFFFFF');
        }
        $cw = $w * 0.42;
        $ch = $stripe * 7;
        $c->rect($x, $y, $cw, $ch, '#3C3B6E');
        for ($r = 0; $r < 4; $r++) {
            for ($col = 0; $col < 5; $col++) {
                $c->circle(
                    $x + $cw * (0.12 + $col * 0.19),
                    $y + $ch * (0.16 + $r * 0.23),
                    max(0.6, $w * 0.018),
                    '#FFFFFF'
                );
            }
        }
    }

    private static function flagEU(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#003399');
        self::stars($c, $x + $w / 2, $y + $h / 2, min($w, $h) * 0.29, 12, '#FFCC00', max(0.8, $w * 0.026));
    }

    private static function flagGB(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#012169');
        $c->line($x, $y, $x + $w, $y + $h, '#FFFFFF', $h * 0.22);
        $c->line($x + $w, $y, $x, $y + $h, '#FFFFFF', $h * 0.22);
        $c->line($x, $y, $x + $w, $y + $h, '#C8102E', $h * 0.10);
        $c->line($x + $w, $y, $x, $y + $h, '#C8102E', $h * 0.10);
        $c->rect($x + $w * 0.40, $y, $w * 0.20, $h, '#FFFFFF');
        $c->rect($x, $y + $h * 0.35, $w, $h * 0.30, '#FFFFFF');
        $c->rect($x + $w * 0.445, $y, $w * 0.11, $h, '#C8102E');
        $c->rect($x, $y + $h * 0.41, $w, $h * 0.18, '#C8102E');
    }

    private static function flagJP(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#FFFFFF');
        $c->circle($x + $w / 2, $y + $h / 2, min($w, $h) * 0.30, '#BC002D');
    }

    private static function flagCA(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#FFFFFF');
        $c->rect($x, $y, $w * 0.25, $h, '#D80621');
        $c->rect($x + $w * 0.75, $y, $w * 0.25, $h, '#D80621');
        $cx = $x + $w / 2;
        $cy = $y + $h / 2;
        $s = min($w, $h) * 0.34;
        $c->polygon([
            [$cx, $cy - $s], [$cx + $s * 0.28, $cy - $s * 0.30], [$cx + $s * 0.72, $cy - $s * 0.42],
            [$cx + $s * 0.46, $cy + $s * 0.06], [$cx + $s * 0.86, $cy + $s * 0.26], [$cx + $s * 0.24, $cy + $s * 0.38],
            [$cx + $s * 0.16, $cy + $s * 0.92], [$cx - $s * 0.16, $cy + $s * 0.92], [$cx - $s * 0.24, $cy + $s * 0.38],
            [$cx - $s * 0.86, $cy + $s * 0.26], [$cx - $s * 0.46, $cy + $s * 0.06], [$cx - $s * 0.72, $cy - $s * 0.42],
            [$cx - $s * 0.28, $cy - $s * 0.30],
        ], '#D80621');
    }

    private static function flagCH(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#D52B1E');
        $t = min($w, $h) * 0.20;
        $c->rect($x + $w / 2 - $t / 2, $y + $h * 0.22, $t, $h * 0.56, '#FFFFFF');
        $c->rect($x + $w * 0.22, $y + $h / 2 - $t / 2, $w * 0.56, $t, '#FFFFFF');
    }

    private static function flagCN(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#DE2910');
        $c->circle($x + $w * 0.18, $y + $h * 0.28, max(1.2, $w * 0.055), '#FFDE00');
        foreach ([[0.34, 0.14], [0.42, 0.26], [0.40, 0.44], [0.30, 0.54]] as [$sx, $sy]) {
            $c->circle($x + $w * $sx, $y + $h * $sy, max(0.7, $w * 0.022), '#FFDE00');
        }
    }

    private static function flagDE(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::bandsH($c, $x, $y, $w, $h, ['#000000', '#DD0000', '#FFCE00']);
    }

    private static function flagFR(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::bandsV($c, $x, $y, $w, $h, ['#002395', '#FFFFFF', '#ED2939']);
    }

    private static function flagIT(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::bandsV($c, $x, $y, $w, $h, ['#008C45', '#F4F5F0', '#CD212A']);
    }

    private static function flagES(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#AA151B');
        $c->rect($x, $y + $h * 0.25, $w, $h * 0.5, '#F1BF00');
    }

    private static function flagAU(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#00008B');
        self::flagGB($c, $x, $y, $w * 0.5, $h * 0.5);
        $c->circle($x + $w * 0.28, $y + $h * 0.80, max(0.9, $w * 0.035), '#FFFFFF');
        foreach ([[0.70, 0.22], [0.78, 0.46], [0.70, 0.70], [0.62, 0.46], [0.86, 0.62]] as [$sx, $sy]) {
            $c->circle($x + $w * $sx, $y + $h * $sy, max(0.7, $w * 0.024), '#FFFFFF');
        }
    }

    private static function flagNZ(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#00247D');
        self::flagGB($c, $x, $y, $w * 0.5, $h * 0.5);
        foreach ([[0.72, 0.26], [0.80, 0.48], [0.72, 0.72], [0.64, 0.48]] as [$sx, $sy]) {
            $c->circle($x + $w * $sx, $y + $h * $sy, max(0.9, $w * 0.030), '#CC142B');
        }
    }

    private static function flagKR(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#FFFFFF');
        $r = min($w, $h) * 0.22;
        $c->circle($x + $w / 2, $y + $h / 2, $r, '#CD2E3A');
        $c->ring($x + $w / 2, $y + $h / 2 + $r * 0.5, $r * 0.5, $r, '#0047A0', 0, 180, 1.0);
    }

    private static function flagIN(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::bandsH($c, $x, $y, $w, $h, ['#FF9933', '#FFFFFF', '#138808']);
        $c->circle($x + $w / 2, $y + $h / 2, $h * 0.12, '#000080');
    }

    private static function flagBR(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#009C3B');
        $c->polygon([
            [$x + $w / 2, $y + $h * 0.12], [$x + $w * 0.88, $y + $h / 2],
            [$x + $w / 2, $y + $h * 0.88], [$x + $w * 0.12, $y + $h / 2],
        ], '#FFDF00');
        $c->circle($x + $w / 2, $y + $h / 2, $h * 0.17, '#002776');
    }

    private static function flagMX(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::bandsV($c, $x, $y, $w, $h, ['#006847', '#FFFFFF', '#CE1126']);
        $c->circle($x + $w / 2, $y + $h / 2, $h * 0.14, '#8B5E3C');
    }

    private static function flagZA(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::bandsH($c, $x, $y, $w, $h, ['#E03C31', '#FFFFFF', '#007A4D']);
        $c->polygon([[$x, $y], [$x + $w * 0.42, $y + $h / 2], [$x, $y + $h]], '#001489');
        $c->polygon([[$x, $y + $h * 0.16], [$x + $w * 0.30, $y + $h / 2], [$x, $y + $h * 0.84]], '#FFB612');
    }

    private static function flagRU(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::bandsH($c, $x, $y, $w, $h, ['#FFFFFF', '#0039A6', '#D52B1E']);
    }

    private static function flagTR(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#E30A17');
        $r = $h * 0.26;
        $c->circle($x + $w * 0.38, $y + $h / 2, $r, '#FFFFFF');
        $c->circle($x + $w * 0.45, $y + $h / 2, $r * 0.82, '#E30A17');
        $c->circle($x + $w * 0.60, $y + $h / 2, $r * 0.34, '#FFFFFF');
    }

    private static function flagSE(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::nordicCross($c, $x, $y, $w, $h, '#006AA7', '#FECC00');
    }

    private static function flagNO(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::nordicCross($c, $x, $y, $w, $h, '#BA0C2F', '#00205B', '#FFFFFF');
    }

    private static function flagDK(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::nordicCross($c, $x, $y, $w, $h, '#C8102E', '#FFFFFF');
    }

    private static function flagPL(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        self::bandsH($c, $x, $y, $w, $h, ['#FFFFFF', '#DC143C']);
    }

    private static function flagIL(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#FFFFFF');
        $c->rect($x, $y + $h * 0.12, $w, $h * 0.13, '#0038B8');
        $c->rect($x, $y + $h * 0.75, $w, $h * 0.13, '#0038B8');
        $s = $h * 0.22;
        $cx = $x + $w / 2;
        $cy = $y + $h / 2;
        $c->polygon([[$cx, $cy - $s], [$cx + $s * 0.87, $cy + $s * 0.5], [$cx - $s * 0.87, $cy + $s * 0.5]], '#0038B8');
        $c->polygon([[$cx, $cy + $s], [$cx + $s * 0.87, $cy - $s * 0.5], [$cx - $s * 0.87, $cy - $s * 0.5]], '#0038B8');
    }

    private static function flagWW(Canvas $c, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#2F3B54');
        $c->ring($x + $w / 2, $y + $h / 2, min($w, $h) * 0.28, 1.6, '#9FB3D9', 0, 360, 0.9);
        $c->line($x + $w * 0.20, $y + $h / 2, $x + $w * 0.80, $y + $h / 2, '#9FB3D9', 1.4, 0.9);
    }

    private static function flagGeneric(Canvas $c, string $code, float $x, float $y, float $w, float $h): void
    {
        $c->rect($x, $y, $w, $h, '#E7EBF3');
        $c->text(substr($code, 0, 2), $x + $w / 2, $y + $h / 2 - $h * 0.32, $h * 0.55, '#4A5675', Canvas::W_BOLD, 'center');
    }
}
}

namespace Nikto\Render {
final class Frame
{
    public const HEADER_H = 78.0;

    public static function draw(Canvas $c, Theme $t, array $options = []): array
    {
        $margin = (float) ($options['margin'] ?? 18);
        $footer = trim((string) ($options['footer'] ?? ''));

        $w = $c->width();
        $h = $c->height();
        $c->gradient(0, 0, $w, $h, $t->c('bg_from'), $t->c('bg_to'), 'v');
        $c->strokeRoundRect($margin, $margin, $w - $margin * 2, $h - $margin * 2, 28, $t->c('line'), 1.0, 0.10);

        $pad = $margin + 24;
        $bottom = $pad + ($footer !== '' ? 22 : 0);

        if ($footer !== '') {
            $c->text($footer, $w / 2, $h - $margin - 24, 10.5, $t->c('ink_faint'), Canvas::W_SEMIBOLD, 'center', 1.0, 'middle', 2.0);
        }

        return [
            'x' => $pad,
            'y' => $pad,
            'w' => $w - $pad * 2,
            'h' => $h - $pad - $bottom,
        ];
    }

    public static function header(
        Canvas $c,
        Theme $t,
        array $rect,
        string $title,
        string $subtitle = '',
        string $badge = '',
        ?callable $left = null
    ): float {
        $x = $rect['x'];
        $w = $rect['w'];
        $y = $rect['y'];

        $c->text($title, $x + $w, $y + 14, 19, $t->c('ink'), Canvas::W_BLACK, 'right', 1.0, 'middle');
        if ($subtitle !== '') {
            $c->text($subtitle, $x + $w, $y + 40, 11, $t->c('ink_faint'), Canvas::W_MEDIUM, 'right', 1.0, 'top');
        }

        if ($left !== null) {
            $left($x, $y);
        } elseif ($badge !== '') {
            self::tagBadge($c, $t, $badge, $x, $y + 2);
        }

        $lineY = $y + 62;
        $c->rect($x, $lineY, $w, 1, $t->c('line'), 0.08);

        return $lineY + 16;
    }

    public static function tagBadge(Canvas $c, Theme $t, string $text, float $x, float $y, float $size = 10.5): float
    {
        $c->text($text, $x, $y + 12, $size, $t->c('ink_faint'), Canvas::W_MEDIUM, 'left', 1.0, 'middle');

        return $c->textWidth($text, $size, Canvas::W_MEDIUM);
    }

    public static function panel(Canvas $c, Theme $t, float $x, float $y, float $w, float $h, float $radius = 18, array $o = []): void
    {
        if (isset($o['fill']) && $o['fill'] !== $t->c('surface')) {
            self::well($c, $t, $x, $y, $w, $h, $radius);
            return;
        }

        if ($o['shadow'] ?? true) {
            $c->shadowOutside($x, $y, $w, $h, $radius, $t->c('shadow'), 0.06, 18, 6);
        }
        $c->roundRect($x, $y, $w, $h, $radius, '#FFFFFF', $t->glassAlpha());
        $c->strokeRoundRect($x + 0.6, $y + 0.6, $w - 1.2, $h - 1.2, $radius - 0.6, '#FFFFFF', 1.2, 0.9);
    }

    public static function well(Canvas $c, Theme $t, float $x, float $y, float $w, float $h, float $radius = 10, float $strength = 1.0): void
    {
        $c->roundRect($x, $y, $w, $h, $radius, $t->c('line'), 0.03 * $strength);
    }

    public static function chip(
        Canvas $c,
        Theme $t,
        string $text,
        float $x,
        float $y,
        float $size = 10,
        ?string $color = null,
        string $weight = Canvas::W_SEMIBOLD,
        bool $solid = false
    ): float {
        $w = $c->textWidth($text, $size, $weight) + 22;
        $h = $size + 14;
        $tone = $color ?? $t->c('line');

        if ($solid) {
            $c->roundRect($x, $y, $w, $h, $h / 2, $tone, 1.0);
            $c->text($text, $x + $w / 2, $y + $h / 2, $size, '#FFFFFF', $weight, 'center', 1.0, 'ink');

            return $w;
        }

        $c->text($text, $x + $w / 2, $y + $h / 2, $size, $color ?? $t->c('ink_dim'), $weight, 'center', 1.0, 'ink');

        return $w;
    }
}
}

namespace Nikto\Render {
use Nikto\Data\LiquidityProvider;

final class LiquidityCard extends Card
{
    private const MAP_H     = 330.0;
    private const LIST_HEAD = 50.0;
    private const ROW_H     = 36.0;
    private const BALANCE_H = 64.0;
    private const GAP       = 16.0;
    private const GUTTER    = 86.0;

    private array $data;
    private string $title;

    public function __construct(array $data, ?string $theme = null, array $options = [])
    {
        parent::__construct($theme, $options);
        $this->data = $data;
        $this->title = (string) ($options['title'] ?? 'نقشه‌ی نقدینگی بیت‌کوین');
    }

    public function render(): Canvas
    {
        $rows = max(1, count($this->data['bid_walls'] ?? []), count($this->data['ask_walls'] ?? []));
        $listH = self::LIST_HEAD + $rows * self::ROW_H + self::BALANCE_H;
        $height = (int) round(84 + Frame::HEADER_H + self::MAP_H + self::GAP + $listH);

        $c = new Canvas(1200, $height, $this->quality);
        $c->setOutputScale($this->outputScale);
        $t = $this->theme;

        $rect = Frame::draw($c, $t, ['footer' => $this->footer]);
        $top = Frame::header(
            $c,
            $t,
            $rect,
            $this->title,
            $this->dateLine(),
            '',
            fn (float $x, float $y) => $this->priceWidget($c, $t, $x, $y)
        );

        $this->map($c, $t, $rect['x'], $top, $rect['w'], self::MAP_H);
        $this->walls($c, $t, $rect['x'], $top + self::MAP_H + self::GAP, $rect['w'], $listH, $rows);

        return $c;
    }

    private function price(float $p): string
    {
        $bucket = (float) ($this->data['bucket'] ?? 100);

        return $this->dnum(number_format($p, $bucket < 1 ? 2 : 0));
    }

    private function priceWidget(Canvas $c, Theme $t, float $x, float $y): void
    {
        $c->text('$' . $this->dnum(number_format((float) $this->data['price'], 1)), $x, $y + 14, 17, $t->c('ink'), Canvas::W_NUM_BOLD, 'left', 1.0, 'num');
        $c->text(
            'BTC / USDT · ' . implode(' + ', (array) ($this->data['sources'] ?? [])),
            $x,
            $y + 42,
            9.5,
            $t->c('ink_faint'),
            Canvas::W_NUM,
            'left',
            1.0,
            'num'
        );
    }

    private function map(Canvas $c, Theme $t, float $x, float $y, float $w, float $h): void
    {
        Frame::panel($c, $t, $x, $y, $w, $h, 20);

        $pad = 24.0;
        $top = $y + $pad + 6;
        $bottom = $y + $h - $pad - 6;
        $chartL = $x + $pad;
        $chartR = $x + $w - $pad - self::GUTTER - 10;
        $gutterL = $chartR + 10;

        $candles = (array) ($this->data['candles'] ?? []);
        $bidWalls = (array) ($this->data['bid_walls'] ?? []);
        $askWalls = (array) ($this->data['ask_walls'] ?? []);
        $price = (float) $this->data['price'];

        $prices = [$price];
        foreach ($candles as $k) {
            $prices[] = (float) $k['h'];
            $prices[] = (float) $k['l'];
        }
        foreach (array_merge($bidWalls, $askWalls) as $wall) {
            $prices[] = (float) $wall['price'];
        }
        $lo = min($prices);
        $hi = max($prices);
        $padP = max(($hi - $lo) * 0.05, $price * 0.001);
        $lo -= $padP;
        $hi += $padP;
        $yOf = static fn (float $p): float => $bottom - ($p - $lo) / ($hi - $lo) * ($bottom - $top);

        $labels = [['y' => $yOf($price), 'text' => $this->dnum(number_format($price, 1)), 'color' => $t->c('line'), 'pill' => true]];
        foreach ([[$bidWalls, $t->c('up')], [$askWalls, $t->c('down')]] as [$walls, $color]) {
            foreach ($walls as $wall) {
                $labels[] = ['y' => $yOf((float) $wall['price']), 'text' => $this->price((float) $wall['price']), 'color' => $color, 'pill' => false];
            }
        }

        $this->candles($c, $t, $candles, $chartL, $chartR, $yOf);

        $py = $yOf($price);
        $c->dashedLine($chartL, $py, $chartR, $py, $t->c('line'), 1.2, 5, 4, 0.8);

        $this->labels($c, $t, $labels, $gutterL, $top, $bottom);
    }

    private function candles(Canvas $c, Theme $t, array $candles, float $left, float $right, callable $yOf): void
    {
        $n = count($candles);
        if ($n === 0) {
            return;
        }
        $slot = ($right - $left) / $n;
        $bodyW = max(2.0, min(8.0, $slot * 0.56));
        $ink = $t->c('line');

        foreach (array_values($candles) as $i => $k) {
            $cx = $left + $slot * ($i + 0.5);
            $o = (float) $k['o'];
            $cl = (float) $k['c'];
            $c->line($cx, $yOf((float) $k['h']), $cx, $yOf((float) $k['l']), $ink, 1.0, 0.45);
            $yTop = $yOf(max($o, $cl));
            $bodyH = max(1.4, $yOf(min($o, $cl)) - $yTop);
            if ($cl >= $o) {
                $c->rect($cx - $bodyW / 2, $yTop, $bodyW, $bodyH, '#FFFFFF', 1.0);
                $c->strokeRoundRect($cx - $bodyW / 2, $yTop, $bodyW, $bodyH, 0.6, $ink, 1.0, 0.6);
            } else {
                $c->rect($cx - $bodyW / 2, $yTop, $bodyW, $bodyH, $ink, 0.6);
            }
        }
    }

    private function labels(Canvas $c, Theme $t, array $labels, float $left, float $top, float $bottom): void
    {
        $h = 20.0;
        $gap = 2.0;
        usort($labels, static fn (array $a, array $b): int => $a['y'] <=> $b['y']);
        $n = count($labels);
        $pos = array_column($labels, 'y');

        for ($pass = 0; $pass < 6; $pass++) {
            for ($i = 1; $i < $n; $i++) {
                if ($pos[$i] - $pos[$i - 1] < $h + $gap) {
                    $pos[$i] = $pos[$i - 1] + $h + $gap;
                }
            }
            $pos[$n - 1] = min($pos[$n - 1], $bottom - $h / 2);
            for ($i = $n - 2; $i >= 0; $i--) {
                if ($pos[$i + 1] - $pos[$i] < $h + $gap) {
                    $pos[$i] = $pos[$i + 1] - $h - $gap;
                }
            }
            $pos[0] = max($pos[0], $top + $h / 2);
        }

        $w = self::GUTTER;
        foreach ($labels as $i => $label) {
            $ly = $pos[$i];
            if ($label['pill']) {
                $c->roundRect($left, $ly - $h / 2, $w, $h, 6, $label['color'], 1.0);
                $c->textFit($label['text'], $left + $w / 2, $ly, $w - 10, 11, '#FFFFFF', Canvas::W_NUM_BOLD, 'center', 8, 1.0, 'num');
            } else {
                $c->textFit($label['text'], $left + 6, $ly, $w - 6, 11.5, $label['color'], Canvas::W_NUM_BOLD, 'left', 8, 1.0, 'num');
            }
        }
    }

    private function walls(Canvas $c, Theme $t, float $x, float $y, float $w, float $h, int $rows): void
    {
        Frame::panel($c, $t, $x, $y, $w, $h, 20);

        $pad = 28.0;
        $mid = $x + $w / 2;
        $this->side($c, $t, 'حمایت‌ها', (array) ($this->data['bid_walls'] ?? []), $t->c('up'), $mid + $pad, $x + $w - $pad, $y);
        $this->side($c, $t, 'مقاومت‌ها', (array) ($this->data['ask_walls'] ?? []), $t->c('down'), $x + $pad, $mid - $pad, $y);
        $c->rect($mid, $y + 22, 1, self::LIST_HEAD + $rows * self::ROW_H - 30, $t->c('line'), 0.07);

        $share = max(0.0, min(1.0, (float) ($this->data['imbalance'] ?? 0.5)));
        $barY = $y + self::LIST_HEAD + $rows * self::ROW_H + 34;
        $barL = $x + $pad;
        $barR = $x + $w - $pad;
        $gap = 3.0;
        $bidW = max(6.0, ($barR - $barL - $gap) * $share);
        $c->roundRect($barR - $bidW, $barY, $bidW, 6, 3, $t->c('up'), 1.0);
        $c->roundRect($barL, $barY, max(6.0, $barR - $barL - $gap - $bidW), 6, 3, $t->c('down'), 1.0);

        $labelY = $barY - 14;
        $c->text('خرید ' . $this->dnum(number_format($share * 100, 1)) . '%', $barR, $labelY, 10.5, $t->c('ink_dim'), Canvas::W_SEMIBOLD, 'right', 1.0, 'middle');
        $c->text('فروش ' . $this->dnum(number_format((1 - $share) * 100, 1)) . '%', $barL, $labelY, 10.5, $t->c('ink_dim'), Canvas::W_SEMIBOLD, 'left', 1.0, 'middle');
    }

    private function side(Canvas $c, Theme $t, string $title, array $walls, string $color, float $left, float $right, float $y): void
    {
        $headMid = $y + self::LIST_HEAD / 2 + 2;
        $c->circle($right - 4, $headMid, 4, $color);
        $c->text($title, $right - 14, $headMid, 13, $t->c('ink'), Canvas::W_BLACK, 'right', 1.0, 'middle');

        if ($walls === []) {
            $c->text('سطح پرحجمی پیدا نشد', $right, $y + self::LIST_HEAD + self::ROW_H / 2, 10.5, $t->c('ink_faint'), Canvas::W_MEDIUM, 'right', 1.0, 'middle');
            return;
        }

        foreach (array_values($walls) as $i => $wall) {
            $ry = $y + self::LIST_HEAD + $i * self::ROW_H;
            $rowMid = $ry + self::ROW_H / 2;
            $c->rect($left, $ry, $right - $left, 1, $t->c('line'), 0.06);
            $c->text($this->price((float) $wall['price']), $right, $rowMid, 13.5, $t->c('ink'), Canvas::W_NUM_BOLD, 'right', 1.0, 'num');
            $c->text($this->dnum(LiquidityProvider::formatBtc((float) $wall['qty'])), $left, $rowMid, 12, $t->c('ink_faint'), Canvas::W_NUM, 'left', 1.0, 'num');
        }
    }
}
}

namespace Nikto\Render {
use Nikto\Data\PriceProvider;

final class MoversCard extends Card
{
    private const ROW_H  = 56.0;
    private const HEAD_H = 52.0;

    private array $data;
    private string $title;

    public function __construct(array $data, ?string $theme = null, array $options = [])
    {
        parent::__construct($theme, $options);
        $this->data = $data;
        $this->title = (string) ($options['title'] ?? 'برترین‌های فیوچرز بایننس');
    }

    public function render(): Canvas
    {
        $rows = max(1, count($this->data['gainers'] ?? []), count($this->data['losers'] ?? []));
        $columnH = self::HEAD_H + $rows * self::ROW_H + 12;
        $height = (int) round(84 + Frame::HEADER_H + $columnH);

        $c = new Canvas(1200, $height, $this->quality);
        $c->setOutputScale($this->outputScale);
        $t = $this->theme;
        CoinLogo::$lightSurface = true;

        $rect = Frame::draw($c, $t, ['footer' => $this->footer]);
        $source = (string) ($this->data['source'] ?? 'Binance Futures');
        $top = Frame::header($c, $t, $rect, $this->title, $this->dateLine(), $source . ' · 24h');

        $colW = ($rect['w'] - 16) / 2;
        $this->column($c, $t, 'بیشترین رشد', (array) ($this->data['gainers'] ?? []), true, $rect['x'] + $colW + 16, $top, $colW, $columnH);
        $this->column($c, $t, 'بیشترین افت', (array) ($this->data['losers'] ?? []), false, $rect['x'], $top, $colW, $columnH);

        return $c;
    }

    private function column(Canvas $c, Theme $t, string $title, array $rows, bool $gainers, float $x, float $y, float $w, float $h): void
    {
        Frame::panel($c, $t, $x, $y, $w, $h, 18);

        $pad = 22.0;
        $right = $x + $w - $pad;
        $headMid = $y + self::HEAD_H / 2 + 2;
        $c->triangle($right - 5, $headMid, 9, $gainers, $gainers ? $t->c('up') : $t->c('down'));
        $c->text($title, $right - 16, $headMid, 14, $t->c('ink'), Canvas::W_BLACK, 'right', 1.0, 'middle');

        $rowY = $y + self::HEAD_H;
        if ($rows === []) {
            $c->text('موردی نیست', $x + $w / 2, $rowY + self::ROW_H / 2, 11, $t->c('ink_faint'), Canvas::W_MEDIUM, 'center', 1.0, 'middle');
            return;
        }

        foreach (array_values($rows) as $i => $row) {
            $ry = $rowY + $i * self::ROW_H;
            $c->rect($x + $pad, $ry, $w - $pad * 2, 1, $t->c('line'), 0.07);
            $this->row($c, $t, $row, $i + 1, $x + $pad, $ry, $w - $pad * 2);
        }
    }

    private function row(Canvas $c, Theme $t, array $row, int $rank, float $x, float $y, float $w): void
    {
        $pct = (float) $row['change_pct'];
        $mid = $y + self::ROW_H / 2;
        $right = $x + $w;

        $c->text($this->dnum((string) $rank), $right, $mid, 12, $t->c('ink_faint'), Canvas::W_NUM_BOLD, 'right', 1.0, 'num');

        $logoS = 28.0;
        $logoCx = $right - 30 - $logoS / 2;
        CoinLogo::draw($c, (string) ($row['logo'] ?? $row['symbol']), $logoCx, $mid, $logoS, false);

        $c->textFit((string) $row['symbol'], $logoCx - $logoS / 2 - 10, $mid, 130, 14, $t->c('ink'), Canvas::W_NUM_BOLD, 'right', 10, 1.0, 'num');

        $pctText = ($pct > 0 ? '+' : ($pct < 0 ? '−' : '')) . $this->dnum(number_format(abs($pct), 2)) . '%';
        $c->text($pctText, $x, $mid, 14, $t->trend($pct), Canvas::W_NUM_BOLD, 'left', 1.0, 'num');

        $c->textFit(
            '$' . $this->dnum(PriceProvider::formatPrice((float) $row['price'])),
            $x + 200,
            $mid,
            100,
            13,
            $t->c('ink_dim'),
            Canvas::W_NUM,
            'right',
            10,
            1.0,
            'num'
        );
    }
}
}

namespace Nikto\Render {
use Nikto\Data\PriceProvider;

final class PriceCard extends Card
{
    private const TILE_H = 172.0;
    private const GAP    = 16.0;

    private array $coins;
    private string $title;

    public function __construct(array $coins, ?string $theme = null, array $options = [])
    {
        parent::__construct($theme, $options);
        $this->coins = array_slice(array_values($coins), 0, 9);
        $this->title = (string) ($options['title'] ?? 'نوسان ۲۴ ساعته بازار');
    }

    public function render(): Canvas
    {
        $count = max(1, count($this->coins));
        $cols  = $count <= 4 ? min(2, $count) : 3;
        $rows  = (int) ceil($count / $cols);

        $height = (int) round(84 + Frame::HEADER_H + $rows * self::TILE_H + ($rows - 1) * self::GAP);

        $c = new Canvas(1200, $height, $this->quality);
        $c->setOutputScale($this->outputScale);
        $t = $this->theme;
        CoinLogo::$lightSurface = true;

        $rect = Frame::draw($c, $t, ['footer' => $this->footer]);
        $top = Frame::header($c, $t, $rect, $this->title, $this->dateLine());

        $tileW = ($rect['w'] - self::GAP * ($cols - 1)) / $cols;

        foreach ($this->coins as $i => $coin) {
            $col = $i % $cols;
            $row = (int) floor($i / $cols);
            $x = $rect['x'] + ($cols - 1 - $col) * ($tileW + self::GAP);
            $y = $top + $row * (self::TILE_H + self::GAP);
            $this->tile($c, $t, $coin, $x, $y, $tileW, self::TILE_H);
        }

        return $c;
    }

    private function tile(Canvas $c, Theme $t, array $coin, float $x, float $y, float $w, float $h): void
    {
        $pct   = (float) $coin['change_pct'];
        $trend = $t->trend($pct);

        Frame::panel($c, $t, $x, $y, $w, $h, 18);

        $pad   = 18.0;
        $left  = $x + $pad;
        $right = $x + $w - $pad;
        $inner = $w - $pad * 2;

        $logoSize = 32.0;
        $logoCx = $right - $logoSize / 2;
        $logoCy = $y + 34;
        CoinLogo::draw($c, (string) $coin['symbol'], $logoCx, $logoCy, $logoSize, false);

        $labelRight = $logoCx - $logoSize / 2 - 10;
        $c->text(strtoupper((string) $coin['symbol']), $labelRight, $logoCy - 10, 14.5, $t->c('ink'), Canvas::W_NUM_BOLD, 'right', 1.0, 'num');
        $c->textFit((string) $coin['name_fa'], $labelRight, $logoCy + 12, $w * 0.44, 10, $t->c('ink_faint'), Canvas::W_MEDIUM, 'right', 8.5, 1.0, 'middle');

        $this->change($c, $t, $pct, $left, $logoCy, $trend);

        $price = '$' . PriceProvider::formatPrice((float) $coin['price']);
        $c->textFit($this->dnum($price), $right, $y + 86, $inner, 28, $t->c('ink'), Canvas::W_NUM_BOLD, 'right', 16, 1.0, 'num');

        $spark = array_values(array_map('floatval', (array) ($coin['spark'] ?? [])));
        if (count($spark) >= 4) {
            $this->sparkline($c, $spark, $left, $y + 114, $inner, $h - 114 - 16, $trend);
        }
    }

    private function change(Canvas $c, Theme $t, float $pct, float $x, float $cy, string $color): void
    {
        if (abs($pct) < 0.005) {
            $c->rect($x, $cy - 1, 8, 2, $color);
        } else {
            $c->triangle($x + 4, $cy, 8, $pct > 0, $color);
        }
        $c->text($this->dnum(number_format(abs($pct), 2) . '%'), $x + 13, $cy, 13, $color, Canvas::W_NUM_BOLD, 'left', 1.0, 'num');
    }

    private function sparkline(Canvas $c, array $values, float $x, float $y, float $w, float $h, string $color): void
    {
        $min = min($values);
        $max = max($values);
        $span = ($max - $min) ?: max(1e-9, abs($max) * 0.001);
        $n = count($values);

        $points = [];
        foreach ($values as $i => $v) {
            $points[] = [$x + $w * ($i / ($n - 1)), $y + $h - (($v - $min) / $span) * ($h - 4) - 2];
        }

        $c->areaGradient($points, $x, $y, $w, $h, $color, 0.10);
        $c->polyline($points, $color, 1.8, 1.0);
    }
}
}

