    private function screenAdmins(): array
    {
        $admins = Access::list();
        $lines = ['<b>مدیران ربات</b>', ''];
        foreach ($admins as $i => $admin) {
            $lines[] = sprintf(
                '%s) <code>%s</code>%s',
                $this->fa((string) ($i + 1)),
                $admin['user_id'],
                isset($admin['fixed']) ? ' — ثابت' : ''
            );
        }

        $kb = [[$this->btn('افزودن مدیر', 's:adm:add')]];
