    \Nikto\Bundle\Runtime::boot(NIKTO_CONFIG + ['root' => __DIR__]);

    if (!defined('NIKTO_LIBRARY')) {
        if (PHP_SAPI === 'cli') {
            exit(\Nikto\Bundle\Runtime::handleCli($argv ?? []));
        }
        \Nikto\Bundle\Runtime::handleWeb();
    }
}
